window.__FEED__ = {"last_updated":"2026-10-29T21:18:44+08:00","total":361,"items":[{"title":"厚积成势 向新而进 伊利前三季度营收核心经营利润双增","summary":"伊利股份前三季度业绩报告显示，公司营收与核心经营利润同步提升。报告强调企业通过积累优势与创新驱动实现增长，这一趋势反映出中国乳企在激烈市场竞争中保持领先地位。伊利持续投入研发与市场拓展，为婴幼儿奶粉行业树立标杆，其成功经验对同类企业具有重要借鉴意义。","source_id":"gnews_cn_brand_fin","source_name":"搜狐网","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://news.google.com/rss/articles/CBMijwFBVV95cUxQS0VPNzNuUjNVUWdudUVkQnRTY2pXLWphVmU5SkRnOHRzWkx5RExwS2c3T3dUVDJCQWt0U2ZPQkVPQjc2Y0kxbm84ZXoxdTgxQXRFc01qSFFqTHFFRjRiZXkwSmpibW1ORWtDdU81cVdWMVFUeUpQMmxqT0t1U1N4d0tiS0RkMks2R0xfaW1tbw","published_at":"2026-10-29T20:56:04+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:28+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","政策法规"],"priority":"P1","score":8.0,"matched":["伊利","营收"],"id":"b24b8d9fca934511","title_zh":"厚积成势 向新而进 伊利前三季度营收核心经营利润双增","summary_source":"llm","summary_kind":"brief","points":["伊利营收利润同步提升","强调积累与创新驱动","保持行业领先地位"],"points_source":"llm","translated":true},{"title":"Nestlé tackles regenerative agriculture’s missing piece","summary":"雀巢与欧洲鸟类保护组织启动三年半项目，测量再生农业对生物多样性的影响。这一举措标志着行业从关注土壤健康和碳减排转向生态系统修复的更广泛转变。对跨境母婴行业而言，可持续农业实践将影响原料供应链和产品配方研发方向，推动行业向更环保、更可持续的方向发展，促使企业更加重视生态平衡和生物多样性保护，以适应未来市场变化和消费者需求。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/29/nestle-x-birdlife-collaboration-signals-next-phase-of-regenerative-agriculture","published_at":"2026-10-29T18:56:30+08:00","published_guessed":false,"fetched_at":"2026-10-29T19:01:44+08:00","language":"en","author":"Donna Eastlake","tags":["品牌动态","政策法规","质量安全"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/UI766HWE6BHYLOL7MHUMCUDI4Q.jpg?auth=52122dfa8e8ed938af79534ebbd1fec3bf74b87b07e0485aa58c525cd496cd98&smart=true&width=4528&height=3012","score":4.8,"matched":["nestlé"],"id":"2a1ee9da1c2d9416","title_zh":"雀巢解决再生农业的缺失环节","summary_source":"llm","summary_kind":"brief","points":["转向生态系统修复","推动农业可持续发展"],"points_source":"llm","translated":true},{"title":"伊利股份前三季度营收、核心经营利润双增，中期分红26.6亿","summary":"伊利股份公布前三季度财报，营收与核心经营利润实现双增长，并宣布中期分红26.6亿元。这一业绩表现反映出公司在母婴奶粉市场的强劲竞争力，分红政策增强投资者信心。伊利作为行业龙头，其经营状况对整个乳制品行业具有风向标意义，持续增长也表明市场对高品质婴幼儿奶粉的需求稳定。","source_id":"gnews_cn_brand_fin","source_name":"金融界","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://news.google.com/rss/articles/CBMiY0FVX3lxTE9qT0tfOXo2NXRLOXRQMXM0U1FYbjNCYTFlcnlvbEJ0Z1dYY25ZMnJRUmZGd3FQb3ppWUZEOTd5ZGI0ZUxrNGZSOTdVbFNxWFpRb09qeUZMc2pxeGczemlXS1dzZw","published_at":"2026-10-29T18:54:50+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:28+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","政策法规"],"priority":"P1","score":8.0,"matched":["伊利","营收"],"id":"c1b9e52b97c811f7","title_zh":"伊利股份前三季度营收、核心经营利润双增，中期分红26.6亿","summary_source":"llm","summary_kind":"brief","points":["伊利营收利润双增长","中期分红26.6亿元","母婴市场竞争力强劲"],"points_source":"llm","translated":true},{"title":"从“全球奶粉销量第一”口径看佳贝艾特悦白：细分品类的吸收与低敏验证_行业新闻","summary":"佳贝艾特悦白奶粉作为全球销量领先的细分品类产品，通过吸收与低敏验证，满足了特定需求消费者。这一成功案例为母婴行业提供了细分市场开发的参考，从业者可借鉴其产品研发和市场定位策略。","source_id":"gnews_cn_crossborder","source_name":"证券之星","source_url":"https://news.google.com/rss/search?q=%E8%B7%A8%E5%A2%83%E7%94%B5%E5%95%86%20(%E5%A5%B6%E7%B2%89%20OR%20%E5%A9%B4%E9%85%8D%20OR%20%E6%AF%8D%E5%A9%B4)%20OR%20%E6%B5%B7%E5%85%B3%20(%E5%A9%B4%E5%B9%BC%E5%84%BF%E9%85%8D%E6%96%B9%E4%B9%B3%E7%B2%89%20OR%20%E5%A5%B6%E7%B2%89)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://finance.stockstar.com/IG2026102900037607.shtml","published_at":"2026-10-29T15:54:31+08:00","published_guessed":false,"fetched_at":"2026-10-29T19:02:04+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","质量安全"],"priority":"P0","score":12.8,"matched":["奶粉","佳贝艾特"],"id":"44ebedad34982d08","title_zh":"从“全球奶粉销量第一”口径看佳贝艾特悦白：细分品类的吸收与低敏验证","summary_source":"llm","summary_kind":"brief","points":["佳贝艾特悦白奶粉销量领先","细分品类产品通过吸收与低敏验证","为母婴行业提供市场开发参考","借鉴产品研发和市场定位策略"],"points_source":"llm","translated":true,"link_resolved":true,"image":"https://i.ssimg.cn/ssimages/2026/10/29/bc3c0dc9f604478d97ec743862c8adba.jpg"},{"title":"Bubs Australia (ASX:BUB) Secures Permanent FDA Authorisation for Three Infant Formula Products","summary":"Bubs Australia（澳交所：BUB）宣布其三种婴儿奶粉产品获得美国FDA的永久授权。这一重要进展表明该公司产品符合美国严格的食品安全标准，有助于提升品牌在美国市场的竞争力。对于跨境母婴行业从业者，这意味着Bubs Australia的产品将更容易进入美国市场，为消费者提供更多选择。同时，这也反映了美国市场对高品质婴儿奶粉的需求持续增长，为行业提供了新的发展机遇。","source_id":"gnews_en_reg","source_name":"Kalkine","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://news.google.com/rss/articles/CBMiygFBVV95cUxNendmMldJeXMtN0d3Y0FaUEszREpRYWRNaldwX2otREk3cENIdXVuMndsdGZ5TTRqX3FYejZONUVVdXhxVXROQmdJSWV0akVqdDRVd0RreEl0cGQtUlIxRzhPWEN4cGd3QmRLZ0tmZ2kwbzJIT09JcnY2SDRGWDNLR0RIdVZtWVpFRmZvX3lkYmdkaU5HSWgxbzFmSklNSklMd1dodVpjaXhlLWdPeGVMMlY2bXVuOFhxaWNBSTQxRTI1bnFmOHVrcnBn","published_at":"2026-10-29T12:58:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:45+08:00","language":"en","author":"","tags":["品牌动态","政策法规","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"b3007213b8c619e8","title_zh":"Bubs Australia（澳交所：BUB）获得美国FDA对三种婴儿奶粉产品的永久授权","summary_source":"llm","summary_kind":"brief","points":["获得FDA永久授权"],"points_source":"llm","translated":true},{"title":"光明致优如何决胜实体母婴？","summary":"光明致优通过打击窜货行为，强化实体渠道管控，提升品牌形象。2025年，坦图在杭州发现一箱窜货奶粉，最终溯源至湖南张家界。这一行动展示了光明致优对渠道管理的重视，对行业其他企业具有借鉴意义。窜货行为损害品牌声誉，加强管控有助于维护市场秩序，提升消费者信任度。","source_id":"muyingqianyan","source_name":"母婴前沿","source_url":"https://www.muyingqianyan.com/feed","original_url":"https://www.muyingqianyan.com/123368.html","published_at":"2026-10-29T11:26:51+08:00","published_guessed":false,"fetched_at":"2026-10-29T13:02:01+08:00","language":"zh","author":"前沿, 母婴","tags":["品牌动态","跨境电商","政策法规"],"priority":"P0","score":10.9,"matched":["奶粉","母婴店","母婴"],"id":"43e59e1bfb11eac0","title_zh":"光明致优如何决胜实体母婴？","summary_source":"llm","summary_kind":"brief","points":["打击窜货行为强化管控","提升消费者信任度"],"points_source":"llm","translated":true,"body":"2025年，坦图在杭州市场发现一箱窜货奶粉。顺着货流追查，货源最终指向湖南张家界一家母婴店。为查清这条线索，坦图团队亲自驱车前往，来回近1000公里，12小时，住宿、油费、人力加起来至少2000块。 如果你想问，就为了一条窜货线索，值吗？算单笔账，血亏。但坦图却认为， 这趟必须得走，要让全国代理商和门店都看见，光明致优在控货这件事上，不是说说而已。 到了张家界，门店拿出一套微信聊天记录，试图解释货物流向，但坦图团队还是从蛛丝马迹中发现，聊天记录是门店伪造的，查实了窜货源头。 在婴配粉行业，控货防串是人人都会念的经，但真正愿意为了一条窜货线索就烧掉几千块，屈指可数。但坦图算的不是这一单的账，而是另一本账： 你放过一家窜货门店，就会有100个门店不再相信你。 在一个出生人口跌到792万，婴配粉销量增长几乎全靠价增的年份里，渠道信任比黄金贵，这就是坦图的“狠”。 “狠”也在另一组数字里： 九个客服，一年回访出76%以上的回购率，退货率控制在万分之六；不碰大连锁，只做单体店和中小连锁；河北、湖北、湖南还有几个地级市没进，但这些市场空白全部都要消灭掉。 2023年，坦图接手光明致优，第一年55万罐，2024年155万罐，2025年200多万罐。在存量市场里画出这条上升曲线，靠的不是风口和速度，是用最笨的办法，守最贵的信任。 对母婴品牌来说，实体渠道中最稀缺的资源，从来不是门店数量，而是“愿意认真卖一个品牌”的门店意愿。而摧毁这种意愿最直接的方式，就是串货和乱价。 坦图团队一直强调，价格体系就是婴配粉事业的“基石”，并且给出了一个在业内并不常见的责任划分： 价格管控95%的责任在厂家，不在门店，不在代理商，更不在串货商。 这句话的分量就在于，它承认了一个基本事实：渠道不会主动维护一个品牌的价格秩序， 除非品牌方自己把这件事当作生死线来守。 据了解，坦图在思慕尔时期就上了“天眼系统”，24小时追踪监控全国货物流向，对可疑的窜货门店进行筛选、监督和核查，对于非法渠道销售、恶意窜货的产品，坦图会通过追溯系统赋予红码，打上“本罐禁止销售”标签，以警示消费者。 曾有一名“推广女将”私发了一件奶粉给疑似串货商，查实后直接辞退。还有代理商在窜货被查后打电话求饶四十多分钟，哭诉说市场建起来不容易，愿意接受更大处罚，但仍被终止合作。 坦图总经理何康辉在跟笔者讲述这些事的时候很平静，或许因为整个团队已经想得足够清楚： 高压线就是高压线，谁碰谁走，能力再强再优秀也得走。 不过，在市场管控这件事上，坦图并不觉得已经做到头了， 还需要更努力，把要求提得更高，把市场管得更细，只有将窜货空间和低价翘客行为极限遏制，市场才能更健康，光明致优才有更长久的未来， 全国八九千家门店在前端经营时，没有后顾之忧。据悉，坦图已经推出了积分系统，接下来还将在市场管控上，陆续推出更多的优化措施。","image":"https://www.muyingqianyan.com/wp-content/uploads/2021/07/e6570c2e9d90b442ec5abe68c80669c.png"},{"title":"孩子王前三季度营收75亿元，门店加速下沉，利润增长仍承压","summary":"孩子王前三季度营收达75亿元，加速门店下沉战略，但利润增长面临压力。这反映了母婴零售市场对综合服务的需求，但利润承压提醒从业者需优化运营效率与成本控制，平衡扩张与盈利能力。10月28日，孩子王发布2026年第三季度报告。前三季度，公司实现营业收入75.06亿元，同比增长2.14%；归属于上市公司股东的净利润2.08亿元，同比下降0.40%。","source_id":"gnews_cn_retail","source_name":"搜狐网","source_url":"https://news.google.com/rss/search?q=%28%E6%AF%8D%E5%A9%B4%E5%BA%97%20OR%20%E6%AF%8D%E5%A9%B4%E8%BF%9E%E9%94%81%20OR%20%E5%AD%A9%E5%AD%90%E7%8E%8B%20OR%20%E7%88%B1%E5%A9%B4%E5%AE%A4%20OR%20%E6%AF%8D%E5%A9%B4%E6%B8%A0%E9%81%93%29%20%28%E5%A5%B6%E7%B2%89%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%85%B3%E5%BA%97%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.sohu.com/a/1094249051_120773210?scm=10001.325_13-325_13.0.0-0-0-0-0.5_1334","published_at":"2026-10-29T10:25:44+08:00","published_guessed":false,"fetched_at":"2026-10-29T11:02:59+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P0","score":9.6,"matched":["孩子王","营收"],"id":"514125654f70d5ed","title_zh":"孩子王前三季度营收75亿元，门店加速下沉，利润增长仍承压","summary_source":"llm","summary_kind":"brief","points":["孩子王营收75亿元"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月28日，孩子王发布2026年第三季度报告。前三季度，公司实现营业收入75.06亿元，同比增长2.14%；归属于上市公司股东的净利润2.08亿元，同比下降0.40%。其中，第三季度营收24.11亿元，同比下降1.08%；归母净利润3669.80万元，同比下降44.42%。据界面新闻报道，孩子王第三季度净利润出现明显下滑。 门店扩张是孩子王当前的重要策略。财报显示，前三季度公司新增加盟门店近180家。此前，公司披露，2026年上半年加盟精选店累计开业近300家，加盟业务收入达5.08亿元，同比增长超过200%。 下沉市场的机会，在于把母婴商品与服务送到更多家庭身边。围绕奶粉、纸尿裤、婴幼儿洗护等高频消费品，孩子王可以利用门店和会员体系，结合宝宝不同成长阶段开展精准推荐，并通过会员专属优惠、组合购及育儿服务带动复购。对加盟门店而言，统一选品、供应链和数字化运营，也有助于减少经营摸索成本。 与此同时，孩子王还在拓展母婴以外的业务。财报显示，丝域生物前三季度新增门店172家，其中中国港澳地区及海外市场新增6家。母婴零售与养发服务面向不同消费需求，能否形成稳定的协同效应，仍需观察后续经营表现。 扩张也带来现实压力。据东方财富网报道，孩子王第三季度净利润同比下降约四成，新店前期投入以及下沉市场加盟业务仍处于扩张期，是需要关注的经营因素。 对孩子王来说，挑战不只是开出更多门店，还要让新店尽快形成稳定销售。奶粉、纸尿裤等刚需商品有助于提高消费频次，但价格透明、品牌竞争激烈，单纯依靠打折促销可能挤压利润。公司可以通过优化商品组合、发展自有及差异化商品、提高会员复购率来改善经营质量，同时加强加盟门店的库存管理和单店盈利评估，避免规模增长快于经营效率提升。 接下来，孩子王需要同时回答两个问题：下沉加盟能否持续贡献收入，丝域生物能否在扩店后实现稳定回报。前三季度营收仍保持增长，但利润表现说明，扩张速度与盈利质量之间的平衡，将成为公司后续经营的重要考验。","image":"https://q7.itc.cn/images01/20261029/b7caa323e5924d228f934369c3d92b46.jpeg"},{"title":"周末露营塞婴儿车，X5放倒座椅2070L，GLE后备厢差在哪","summary":"周末露营塞婴儿车，X5放倒座椅2070L，GLE后备厢差在哪 汽车之家","source_id":"gnews_cn_baby_category","source_name":"汽车之家","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://chejiahao.autohome.com.cn/info/26760443?reply=reply","published_at":"2026-10-29T09:51:39+08:00","published_guessed":false,"fetched_at":"2026-10-29T13:02:16+08:00","language":"zh","author":"","tags":["行业动态"],"priority":"P1","score":11.2,"matched":["婴儿","婴儿车"],"id":"a83a28f3ba87a349","link_resolved":true,"image":"https://www2.autoimg.cn/chejiahaodfs/g34/M09/63/B4/autohomecar__ChxpV2ripN2AeJuQAAKK4KmMUYc000.jpg"},{"title":"Bega Cheese Asks Queensland Dairy Farmers to Boost Milk Supply","summary":"贝加奶酪公司向澳大利亚昆士兰州奶农提出增加牛奶供应的要求。这一举动可能影响全球乳制品供应链，特别是依赖澳大利亚奶源的跨境母婴品牌需密切关注原奶供应变化，评估潜在的市场风险与成本波动。对行业从业者而言，澳大利亚奶源的变化直接关系到产品成本和供应稳定性，需及时调整采购策略以应对市场波动。","source_id":"gnews_en_nz_dairy","source_name":"www.marketscreener.com","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.marketscreener.com/news/bega-cheese-asks-queensland-dairy-farmers-to-boost-milk-supply-ce785cd3db80fe24","published_at":"2026-10-29T09:14:20+08:00","published_guessed":false,"fetched_at":"2026-10-29T11:03:08+08:00","language":"en","author":"","tags":["供应链","市场数据","质量安全"],"priority":"P0","score":11.2,"matched":["dairy","milk supply"],"id":"3fb42204bcb0ee3f","summary_source":"llm","summary_kind":"brief","points":["Bega Cheese要求增加牛奶供应","影响全球乳制品供应链"],"points_source":"llm","translated":true,"title_zh":"贝加奶酪要求昆士兰州奶农增加牛奶供应","link_resolved":true},{"title":"快60岁“苗连”满头白发抱奶瓶，小27岁央视妻悄悄领证！被嘲“爷孙恋”后，打了谁的脸","summary":"《我是特种兵》里骂新兵跟骂儿子似的“苗连”，现实里快60了，被路人拍到在小区门口抱个小娃娃，头发白一大片，卫衣旧得发毛，手里还拎个粉色保温奶瓶。网友先愣住：这咋像邻家爷爷接孙女放学？再一扒，娃娃是他亲闺女。老婆是央视十七套的出镜记者、制片人商文婷，硕士，去过日本交流，常年在田埂上拍基层片子，比他小27岁。俩人没办婚礼，2025年悄悄领证，回家吃顿家宴就算完事。","source_id":"gnews_cn_baby_category","source_name":"360娱乐","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://yule.360.com/detail/5271272","published_at":"2026-10-29T07:29:20+08:00","published_guessed":false,"fetched_at":"2026-10-29T13:02:16+08:00","language":"zh","author":"","tags":["行业动态"],"priority":"P1","score":4.8,"matched":["奶瓶"],"id":"3283771ad56a711d","summary_source":"extract","link_resolved":true,"body":"有个事挺炸的。《我是特种兵》里骂新兵跟骂儿子似的“苗连”，现实里快60了，被路人拍到在小区门口抱个小娃娃，头发白一大片，卫衣旧得发毛，手里还拎个粉色保温奶瓶。网友先愣住：这咋像邻家爷爷接孙女放学？再一扒，娃娃是他亲闺女。老婆是央视十七套的出镜记者、制片人商文婷，硕士，去过日本交流，常年在田埂上拍基层片子，比他小27岁。俩人没办婚礼，2025年悄悄领证，回家吃顿家宴就算完事。片场共事认识的——2023年公益电影《那年我们十八岁》，他主演，她管宣传制片。没人信这段能成。年龄差摆在那，网上阴阳怪气的不少：“老演员傍小才女”“晚年折腾”“图流量吧”。周惠林不回。商文婷也不回。后来有博主发图：菜市场里他提着一袋小白菜，她低头回工作微信，婴儿车放中间，像普通两口子。 周惠林是江苏连云港赣榆青口镇人。1983年进化工厂，三班倒，下班对着镜子练台词。1986年借调淮海歌舞团，1987考进江苏省戏剧学校，1990调南京市话剧团。上世纪90年代和同乡侯勇演小品《退票》，俩人挤小剧场后台吃盒饭，抠词抠到半夜。1994年央视《三国演义》他演毛玠，镜头没几句词。2002年《DA师》演坦克团团长包尔达夫，站坦克边腰板直。《我是特种兵》苗连凶，转头往被窝塞干粮。《利刃出鞘》范天雷鬼主意多。他不挑戏，几场戏也抠人物。拍军旅戏先扎部队，跟新兵出操、爬战术、滚泥地。女儿出生那天他在外地拍戏。接到电话当天跟组里请半月假，飞回来在产房外来回走，手心全是汗。孩子一哭，这演了半辈子硬汉的男人背过身，眼圈红了半天。之后他推掉长周期外景。冲奶粉拿温度计控40度，辅食火候写便签，换尿布从手忙脚乱到利索。有回带娃逛公园，全程抱怀里，逗孩子哼军歌调子，跟戏里教官判若两人。 商文婷没退圈，央视纪实报道还做，只是节奏慢了，家里辅食锅和采访本放一块。侯勇也是赣榆人，同岁。《大染坊》演主角，飞天金鹰拿遍。三段婚姻，第三任王瑞小二十岁，珠宝设计师，2017北京办婚礼闹过一阵。2024年57岁得儿子，出席活动状态年轻。周惠林头婚，侯勇三婚。一个藏名字在角色后头，一个把名字顶在片头上。被拍到同框那次，周惠林鬓角白，商文婷气质舒展，视觉差一眼就出来。有营销号写“爷孙恋”，底下有人怼：人家片场较真，一个抠本子一个抠镜头，你懂啥。周惠林现在主要排话剧、客串，不接大量影视剧。有次演出结束，观众凑过去合影，他怀里娃娃睡着了，他比了个“嘘”。商文婷在旁边拎着帆布包，包上别个“乡村振兴采访”徽章。网上传过“周惠林靠老婆上央视资源”，没实锤，也没人出来辟。也有人翻他早年话剧奖：江苏省五一工程奖、全国小品大赛个人表演奖。不炒绯闻那套，他不会。女儿百天没发朋友圈，亲戚说就煮了锅红鸡蛋。侯勇那边热搜是“硬汉升级奶爸”，周惠林这边是路人图先火。有剧粉说：苗连当年罚卧撑，现在半夜起来拍嗝，角色没白演，心软了。商文婷之前跑基层，蹲半天拍麦农，稿子不煽情。周惠林排练厅啃馒头看剧本，导演说“老周你别太轴”，他说“兵不是演出来的”。俩人家里没豪宅图流出，客厅婴儿垫占半间，茶几上话剧本压着育儿书。有回商文婷发工作图，背景虚掉那角，有人认出是周惠林在哄娃。没加文案，没挂情侣标。周惠林原单位南京话剧团老同事聊过：他中年才影视圈混出来，从不攀关系。《三国演义》那会儿住招待所，侯勇来找他，俩人分一根冰棍。现在侯勇儿子小，周惠林闺女小，同乡硬汉都晚当爹。拍《那年我们十八岁》时，商文婷嫌他一条过太板，他嫌她剪辑太花，后来片尾字幕俩人名字挨着。没吻戏，没绯闻镜头，就片场盒饭坐一张桌子。有记者问商文婷“差27岁怎么处”，她说“他背词比我都熟”。周惠林被问“老来得女累不累”，回“比爬战术轻松点”。被拍到抱娃买包子，老板娘认出来：这不是电视里那个连长嘛。他笑笑：连长下岗了，现在管喂奶。商文婷在旁边扫码付款，顺手把包子掰小块喂他。没摆拍，没通稿。网上吵“年龄差婚姻靠不靠谱”，他家灯晚上九点就灭了，婴儿哭一声他先醒。侯勇携妻儿走红毯，周惠林推婴儿车走菜场路。一个镜头前，一个镜头外。话剧《雷雨》他演周萍爹辈角色，谢幕抱花下去，兜里露出半个磨牙棒。舞美小伙说：老周以前进组先敬礼，现在进组先问“有没有母婴室”。商文婷做十七套农业选题，出差带吸奶器，他在外地戏份压缩到三天拍完赶回。没说爱不爱，就是孩子发烧他守到天亮，她改稿到三点，俩人分一碗粥。有八卦号编“周惠林靠央视老婆洗白资源”，底下剧迷列他九几年话剧票根：那时候她还在上学。也有人说商文婷“下嫁老演员”，她同事回：她最烦油嘴男的，周惠林片场较真像老教务主任，她对路数。女儿周岁没请圈里人，侯勇寄了套小军装，周惠林发张娃穿反的照片，没配字。商文婷妈晒过一条：外孙女抓周抓了支 周惠林快六十岁了才当上爹。这事挺意外，毕竟他以前在镜头前是个硬汉形象。他娶了个小他二十七岁的女人，对方是央视的记者周周。两人年龄差摆在那儿，刚在一起时大家都觉得挺新鲜，纷纷送祝福。可最近他们一块儿出现时，气氛似乎变了味。老张脸上的褶子深得像刀刻的一样，每一道都藏着年纪。他旁边的老伴儿站在那儿，身板挺得笔直，衣服穿得整整齐齐，看着一点没显老态。这两人凑在一块儿，岁数差着好几轮呢，外人看着都觉得稀罕。窗外的风刮过来，吹得窗帘角轻轻晃了一下。十六岁那年，也就是1983年，他进了县七二化工厂干活，身份是个普通工人。人生的转折往往就藏在那些看似不经意的瞬间里，周惠林的经历就是最典型的注脚。1986年，他去了市淮海歌舞团。那是借调，身份不算正式。他在那儿当演员，日子就这么混过去了。第二年，他考进了省戏剧学校。不是随便玩玩，是去学真本事。系统性的训练，把底子打得死死的。基本功这东西，急不得，得一点点磨出来。1990年，他进了南京市话剧团。职业演员这条路算是正式迈开了腿。刚进去的那阵子，没挑活儿。什么配角都接，龙套也演。","image":"https://p0.qhimg.com/t11508c75c8b114d663b12b0016.jpg"},{"title":"Fonterra Reports Strong FY26 Performance With $9.69 Milk Payout And $1B Protein Push","summary":"恒天然发布FY26财年业绩报告，表现强劲，每公斤乳酪分红9.69美元，并启动10亿美元蛋白质投资计划。这一分红水平创历史新高，显示出恒天然在乳制品市场回暖背景下的盈利能力。对于跨境母婴从业者而言，恒天然作为全球重要的乳业原料供应商，其分红增加和投资计划意味着上游原料供应的稳定性提升，且未来可能推出更多高蛋白产品。","source_id":"gnews_en_nz_dairy","source_name":"https://en.edairynews.com/","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://en.edairynews.com/fonterra-reports-strong-fy26-performance-with-9-69-milk-payout-and-1b-protein-push/","published_at":"2026-10-29T04:54:39+08:00","published_guessed":false,"fetched_at":"2026-10-29T06:55:42+08:00","language":"en","author":"","tags":["供应链"],"priority":"P0","score":16.0,"matched":["payout","milk payout","fonterra"],"id":"c186de2c4ee12f29","title_zh":"恒天然FY26财年表现强劲 每公斤乳酪分红9.69美元","summary_source":"llm","summary_kind":"brief","points":["恒天然FY26财年表现强劲","每公斤乳酪分红9.69美元","启动10亿美元蛋白质投资计划"],"points_source":"llm","translated":true,"link_resolved":true,"body":"The cooperative posted an underlying operating profit for its continuing operations of $1.8 billion and a consolidated profit after tax of $1.2 billion, achieving a return on capital of 14.2 percent, well above its long-term target threshold of 10 to 12 percent. This financial outcome confirms that Fonterra has already restored underlying earnings to pre-divestment baselines, meeting its operational targets ahead of schedule following the divestiture of its global Consumer brands and the Mainland Group. The cooperative’s core Ingredients division served as the primary earnings engine, generating $1,293 million in operating profit on the back of favorable product mix optimization and surging global demand for functional milk proteins, while the Foodservice unit contributed $547 million in operating profit through volume and pricing expansion across key Asian and Middle Eastern corridors. Capitalizing on its refined business-to-business (B2B) focus, Fonterra announced an incremental capital commitment of $1 billion over the next three years to expand and upgrade its South Island industrial processing network. The multi-year capital deployment will accelerate advanced protein fractionation, expand high-spec drying infrastructure, and install modernized environmental systems to lower industrial emissions and improve factory water recycling. The new facilities, slated to become fully operational in 2029, are engineered to capture premium global margins for specialized nutritional ingredients while generating 50 to 60 permanent manufacturing jobs alongside substantial regional construction activity across the South Island. The cooperative’s specialized organic pool achieved a historic financial milestone, with the final organic milk price of $14.13 per kgMS marking a sixth consecutive year of payout increases, up from $12.35 per kgMS in FY25. Andrew Henderson, Fonterra’s General Manager for Organic, noted that export demand for certified grass-fed organic ingredients remains strong—particularly across the United States, where domestic organic milk availability has faced localized supply deficits. To service these high-margin overseas contracts, Fonterra is actively recruiting additional pasture-based dairy suppliers across both the North Island and South Island to expand its specialized organic and pasture-certified milk pools.","image":"https://en.edairynews.com/wp-content/uploads/2026/10/Fonterra-reports-strong-FY26-performance-with-9.69-milk-payout-and-1B-protein-push.jpeg"},{"title":"Nestlé targets two booming beverage trends with latest launch","summary":"雀巢扩展了Sanpellegrino零添加糖系列，推出草莓奶油口味。这款低卡产品融合了甜点风味和功能性，反映了市场对兼具享受与健康的高端软饮日益增长的需求。这一举措对从业者意味着，在追求健康的同时，创新口味和功能性是吸引消费者的关键。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/nestle-taps-two-booming-beverage-trends-with-sanpellegrino-strawberry-crema","published_at":"2026-10-29T00:47:49+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:54:40+08:00","language":"en","author":"Donna Eastlake","tags":["品牌动态","市场数据","质量安全"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/3YNAZB5DGFD47MFA6C6CTIN7BY.jpg?auth=acf671ad43d9dd6912940efe9dbcf6d11d24b22aa5473487bf3443ec2c6b211f&smart=true&width=1920&height=1080","score":4.8,"matched":["nestlé"],"id":"11955b536b079d23","title_zh":"雀巢推出新品，瞄准两大增长饮料趋势","summary_source":"llm","summary_kind":"brief","points":["推出草莓奶油口味零添加糖饮料","产品低卡且融合甜点风味和功能性","反映高端软饮市场对健康与享受结合的需求增长"],"points_source":"llm","translated":true},{"title":"Nestlé targets two booming beverage trends with latest launch","summary":"雀巢通过推出含草莓奶油的零添加糖桑培乐，将甜点风味与健康益处相结合，拓展零添加糖系列。这一举措反映了消费者对兼具享受与健康的高端软饮料需求增长。对跨境母婴行业从业者而言，雀巢的行动表明企业正积极迎合健康消费趋势，推动产品创新。","source_id":"foodnavigator_asia","source_name":"FoodNavigator-Asia","source_url":"https://www.foodnavigator-asia.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/nestle-taps-two-booming-beverage-trends-with-sanpellegrino-strawberry-crema","published_at":"2026-10-29T00:47:49+08:00","published_guessed":false,"fetched_at":"2026-10-29T01:42:37+08:00","language":"en","author":"Donna Eastlake","tags":["品牌动态","市场数据","质量安全"],"priority":"P1","image":"https://www.foodnavigator.com/resizer/v2/3YNAZB5DGFD47MFA6C6CTIN7BY.jpg?auth=acf671ad43d9dd6912940efe9dbcf6d11d24b22aa5473487bf3443ec2c6b211f&smart=true&width=1920&height=1080","score":4.8,"matched":["nestlé"],"id":"99d93592a89672eb","title_zh":"雀巢瞄准两大饮料趋势推出新品","summary_source":"llm","summary_kind":"brief","points":["零添加糖系列拓展","高端软饮料需求增长","健康消费趋势明显"],"points_source":"llm","translated":true},{"title":"High&GoGo Story有机成长奶粉上市，为学龄期成长添动力，身高·眼脑·自护一步到位","summary":"High&GoGo品牌推出有机成长奶粉，专为3-14岁学龄期儿童设计，强调有机奶源和科学配方，注重身高、眼脑、自护三大维度的营养支持。该产品符合当前市场对有机、科学喂养的需求，对跨境母婴行业从业者意味着需关注高端有机奶粉市场趋势和消费者对产品功能的关注点。再搭配维生素A、铁、锌等协同营养，让孩子“看得清黑板、记得住知识”，学习效率自然提升。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/6/20261029/1869549.shtml","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T17:08:56+08:00","language":"zh","author":"","tags":["品牌动态","质量安全","市场数据"],"priority":"P1","score":9.6,"matched":["奶粉","上市"],"id":"1e16afed98f6eced","image":"https://objectem.oss-cn-shenzhen.aliyuncs.com/yhdoc/202610/29/20261029162554646991263.png","body":"10月底，源自丹麦的高端儿童营养品牌High&GoGo正式官宣新品——High&GoGo Story有机成长奶粉上市。这款专为3-14岁学龄期儿童定制的配方奶粉，以“有机奶源+科学配比”为核心，凭借“成长、眼脑、自护、吸收”四效合一的卓越配方，为中国家庭提供儿童成长营养的科学新方案。 3-14岁是儿童眼脑发育、骨骼发育、认知进阶、免疫力构建的“黄金窗口期”，营养供给的“精准度”与“天然性”直接影响成长质量。High&GoGo Story有机成长奶粉从源头把控品质，甄选北欧百年牧场有机奶源，遵循欧盟有机认证标准，拒绝化肥、农药与激素，确保每一滴奶的纯净安全。同时，依托“Clean Recipe”理念，将有机奶源中的天然活性营养精准保留，让“纯净”与“高效”完美融合，为孩子打下安全且有力的成长地基。 针对学龄期儿童“长不高、用眼多、注意力易分散、易生病”的家长痛点，High&GoGo Story有机儿童配方奶粉从身高、眼脑、自护力三大维度构建“协同营养矩阵”： 针对学龄期用眼过度、学习分心问题，配方科学注入“眼脑黄金”——叶黄素酯(犹如眼睛的“防晒伞”，过滤蓝光损伤)与牛磺酸(大脑的“加油站”，提升专注力与记忆力)。再搭配维生素A、铁、锌等协同营养，让孩子“看得清黑板、记得住知识”，学习效率自然提升。 配方特含BIO CBP(初乳碱性蛋白)，唤醒骨骼生长力;搭配原生天然牛乳钙与天然赖氨酸，为骨骼强健提供充足的营养支持，让孩子的成长更有底气。。此外，丹麦益生菌的加入进一步调节肠道菌群平衡，让营养“吸得进、留得住”，全链路助力身高突破。 免疫力是成长的“隐形盾牌”。High&GoGo Story有机成长奶粉以乳铁蛋白构建第一道防线，减少换季小状况，让孩子“少生病、活力足”，家长更安心。 除了核心功能，新品更打造“一站式营养补给”：欧洲12种维生素+6种矿物质覆盖成长所需，96%以上有机配方比例，既满足“有机纯净”需求，又实现“科学全面”补给;同时通过BB-12 & LGG益生菌+有机FOS益生元组合，调节肠道菌群、促进营养吸收，解决“补了白补”的吸收难题，让每一口奶粉都转化为成长动力。 “孩子的生长不是一场冲刺，而是一段需要耐心守护的旅程。”High&GoGo品牌负责人表示，“我们希望用一杯‘有机+科学’的奶粉，让家长放下焦虑，让孩子在身高、眼脑、自护力的协同发展中，自信探索世界。” 11月起，High&GoGo Story有机儿童成长奶粉将正式发售。从北欧牧场的纯净奶源，到实验室里的科学配比，再到孩子手中的每一杯温暖，High&GoGo正以“有机为底，科学为翼”，为学龄期儿童成长书写新的营养篇章，陪伴孩子们健康、快乐地迈向未来!","points":["High&GoGo有机成长奶粉上市","3-14岁学龄期儿童配方","有机奶源科学配比","身高眼脑自护营养支持"],"points_source":"llm","summary_source":"llm","title_zh":"High&GoGo Story有机成长奶粉上市，为学龄期成长添动力，身高·眼脑·自护一步到位","translated":true},{"title":"向善守护 强健未来——第四届强健宝宝成长峰会聚力儿童健康","summary":"10月23日，由人民网-人民幼教主办，新西特承办的第四届强健宝宝成长峰会暨“塞上护苗”困境幼儿养育帮扶项目启动仪式在宁夏银川举办。本次峰会汇聚了宁夏民政公益领导、幼教平台代表、医学专家、行业大咖、全国母婴渠道代表，以及奥运冠军孙杨。大会围绕儿童科学营养、儿童公益实践等议题展开交流，共探母婴行业高质量发展路径。","source_id":"baobei360","source_name":"中婴网","source_url":"https://www.baobei360.com/","original_url":"http://info.baobei360.com/info/2026-10-29/10028874.html","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T17:07:47+08:00","language":"zh","author":"","tags":["行业动态"],"priority":"P1","score":8.0,"matched":["宝宝","儿童"],"id":"0641a6711b3d25cd","image":"https://m.baobei360.com/upfile/news/202610/202610291532294399_400x300.jpg","body":"10月23日，由人民网-人民幼教主办，新西特承办的第四届强健宝宝成长峰会暨“塞上护苗”困境幼儿养育帮扶项目启动仪式在宁夏银川举办。本次峰会汇聚了宁夏民政公益领导、幼教平台代表、医学专家、行业大咖、全国母婴渠道代表，以及奥运冠军孙杨。大会围绕儿童科学营养、儿童公益实践等议题展开交流，共探母婴行业高质量发展路径。 峰会现场，宁夏回族自治区民政厅慈善事业促进处处长赵琨、人民网・人民幼教总经理李静先后致辞。致辞中聚焦儿童健康发展与公益帮扶，呼吁社会各界持续关注困境儿童成长，凝聚多方力量护航孩子科学养育、强健成长，为本次峰会定下专业向善的主基调。 峰会邀请多位行业权威专家带来主题分享。北京大学第一医院杨艳玲教授围绕《脑健康与营养代谢》展开分享，解读儿童大脑发育关键周期，为渠道从业者与广大家长普及儿童认知成长相关科学知识。 西北妇女儿童医院李占魁聚焦婴幼儿牛奶蛋白过敏议题，拆解宝宝过敏各类预警信号，分享婴幼儿过敏的科学干预与养育方案。 乳业专家宋亮发表《营养品：母婴行业下一个主战场与品牌制胜之道》主题演讲。他指出营养品时代已经到来，结合当前母婴行业新格局，剖析营养品赛道增长机遇、竞争挑战以及品牌突围方向，解读人口新周期下行业发展趋势，为在场渠道伙伴提供务实的行业参考。 新西特总裁宋海华阐述品牌“改善中国宝宝体质”的初心使命，回顾品牌深耕乳铁蛋白、DHA等科学营养领域的积淀，矢志把科学营养理念送入万千普通母婴家庭，守护孩子健康成长。他始终聚焦儿童营养健康，希望用专业营养力量，为更多宝宝筑牢成长根基。宋总表示选择孙杨为品牌代言人，正是看中冠军身上拼搏坚守、恪守高标准的精神内核，将这份严谨与坚持融入品牌理念，依托冠军榜样力量，向广大家长传递科学养育的理念，守护每一位孩子的强健未来。 孙杨登台带来《强大，不止于天赋》主题分享，结合自身竞技生涯，诠释坚持、自律、热爱对于成长的重要意义。他将竞技体育的成长逻辑延伸至儿童养育，提出孩子强健体质离不开长期科学营养的浇灌，宝宝自护力养成没有捷径，需要日复一日的呵护。 儿童的健康成长，是民生关切，也是一份温暖的时代使命。宁夏困境幼儿的现实难题，需要更多爱心力量接力守护。峰会现场新西特携手各界代表正式启动“塞上护苗” 困境幼儿养育帮扶项目。 据了解，新西特早在2017年便已在宁夏红寺堡落地助学帮扶行动。在今年9月中华慈善日，品牌捐赠价值101万元爱心物资，用于帮扶困境儿童。本次峰会现场，相关领导、专家为到场的红寺堡受助儿童发放爱心礼包。宁夏慈善总会副会长彭荣军现场发言号召更多社会力量参与困境儿童关爱事业。 本届峰会虽已落幕，新西特表示，未来将继续坚守“改善中国宝宝体质”的品牌初心，联动专家、渠道与社会各界力量，兼顾产品创新与公益践行，守护更多中国宝宝健康强健成长。","points":["在今年9月中华慈善日，品牌捐赠价值101万元爱心物资，用于帮扶困境儿童"],"points_source":"extract","summary_source":"extract"},{"title":"爸爸打呼噜，会不会吵坏宝宝睡眠？","summary":"爸爸打呼噜可能影响宝宝睡眠质量，尤其对于新生儿和早产儿。婴儿睡眠浅，对声音敏感，爸爸的鼾声可能导致他们频繁醒来，影响生长发育。家长需关注宝宝睡眠状况，必要时调整睡姿或分房睡。对于跨境母婴从业者，了解不同文化背景下的睡眠习惯差异，能更好地为消费者提供科学育儿建议，促进产品销售和服务升级。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/1/20261029/1869550.shtml","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T19:02:41+08:00","language":"zh","author":"","tags":["质量安全","海外动态"],"priority":"P1","score":4.8,"matched":["宝宝"],"id":"1a185d30f94ed47e","title_zh":"爸爸打呼噜，会不会吵坏宝宝睡眠？","summary_source":"llm","summary_kind":"brief","points":["打呼噜影响婴儿睡眠","新生儿对声音敏感","需关注宝宝睡眠质量","调整睡姿或分房睡"],"points_source":"llm","translated":true,"body":"很多宝妈宝爸夜里都会被同一个问题困扰：爸爸呼噜声一响，宝宝会不会被吵醒?会不会影响睡眠质量?结论是：有可能吵到，但不等于一定会“吵坏”。关键要看呼噜声的大小、变化、持续时间，以及宝宝自己的反应。 宝宝的睡眠结构和成人不同，浅睡眠比例更高，外界声音突然变大、变尖、断断续续时，更容易惊醒、翻动或哭闹。呼噜声往往忽高忽低，还可能伴随呼吸暂停后的突然声响，对宝宝来说并不是稳定的“背景音”。所以，爸爸打呼噜确实可能增加宝宝夜醒、入睡困难或浅睡增多的情况。但宝宝也有一定适应能力，如果声音较低、隔得较远、持续时间稳定，影响可能相对小一些。 判断会不会影响，不能只听呼噜声大不大，更要看宝宝表现。如果宝宝夜间惊醒增多、夜醒次数明显增加、入睡变难、白天烦躁或精神差，就要考虑睡眠环境中的呼噜声因素。调整睡眠安排后，宝宝睡眠变稳，说明关系可能较大。如果宝宝睡眠和白天状态都正常，不必过度焦虑，但仍建议减少长期大声暴露。 减少影响可以从环境和健康两方面做。宝宝应睡独立小床，保持仰卧、床面平整，同房不同床;让宝宝与打呼噜的大人保持距离，必要时分房或隔墙睡;可以先哄睡宝宝，再让大人入睡;不建议给宝宝戴耳塞;白噪音音量要低，不要用白噪音去掩盖呼噜声。爸爸方面，睡前少饮酒，尽量侧睡，控制体重，处理鼻塞;如果打鼾声音很大、伴有憋气、白天嗜睡，建议就医评估睡眠呼吸暂停。 总之，爸爸打呼噜可能干扰宝宝睡眠，但多数情况可以通过调整睡眠位置和改善打鼾来降低影响。宝妈宝爸既要重视，也不必恐慌。多观察宝宝夜醒和白天状态，必要时咨询儿科或耳鼻喉科医生。安全睡眠永远是第一位。"},{"title":"宝宝夜里哭闹是什么原因？先排查这一点","summary":"许多宝妈宝爸面临宝宝夜里哭闹的问题。文章指出，在给哭闹贴上“缺钙”“被吓到”或“故意闹人”的标签前，应先排查宝宝的基本生理需求和安全睡眠环境。常见原因包括饥饿、尿布湿、温度不适、衣物或床品不舒服等。家长需按顺序检查尿布、后颈和手脚温度、衣物松紧、床面平整度，并确保空气流通。安全睡眠环境要求宝宝仰卧睡在独立小床上，周围不放枕头、厚被、毛绒玩具等。作息和环境因素如白天小睡不足、睡前玩得太兴奋、光线过亮、声音突然变大等也会影响夜间睡眠。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/2/20261029/1869551.shtml","published_at":"2026-10-29T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T21:19:42+08:00","language":"zh","author":"","tags":["质量安全","品牌动态"],"priority":"P1","score":4.8,"matched":["宝宝"],"id":"7200d30af024a46c","body":"宝宝夜里哭闹，是很多宝妈宝爸都会遇到的事。先别急着给哭闹贴上“缺钙”“被吓到”或“故意闹人”的标签，也不要一哭就喂奶或长时间摇晃。第一步应先排查：宝宝的基本生理需求和安全睡眠环境有没有问题。 先看基本需求。宝宝夜里哭闹，常见原因是饿了、尿布湿了、太热或太冷、衣服或床品不舒服。家长可以按顺序快速检查：尿布是否湿脏，后颈和手脚温度是否合适，衣物是否过紧，床面是否有硌人的东西。不要只看手脚凉就加被子，后颈温热、不出汗通常更可靠。若宝宝有鼻塞、呼吸不畅，也可能睡不安稳，需要先清理鼻腔、保持空气流通。还要看睡眠环境是否安全舒适：宝宝应仰卧睡在独立小床上，床面平整，周围不放枕头、厚被、毛绒玩具和松散物品，坚持同房不同床。安全睡眠永远是第一位。 再排查作息和环境。宝宝过度疲劳时反而更难入睡，夜里也容易频繁哭闹。白天小睡不足、入睡时间太晚、睡前玩得太兴奋，都可能影响夜间睡眠。卧室光线太亮、声音突然变大、温度不适、睡前流程混乱，也会让宝宝睡不踏实。家长可以固定睡前流程，降低光线和声音刺激，让宝宝在相对稳定的环境里入睡。 之后再看身体和情绪因素。出牙不适、肠胀气、湿疹瘙痒、鼻塞、分离焦虑、睡眠倒退等，都可能让宝宝夜里哭闹。处理时要先安抚，再观察，不要盲目用药，也不要用偏方。哭闹时可以先轻拍、低声安抚，检查基本需求，避免一哭就喂导致过度喂养，也避免剧烈摇晃。若宝宝只是短暂翻动或哼唧，可以先观察片刻，不一定马上抱起。 还要记住就医信号。如果宝宝出现发热、呼吸费力、频繁呕吐、精神差、哭声尖或弱、拒奶、尿量明显减少等情况，应及时就医。多数夜里哭闹通过排查需求、调整作息和改善睡眠环境可以缓解。家长不必过度焦虑，但要用顺序排查代替胡乱猜测。先排查基本需求和安全睡眠环境，再找其他原因，往往更稳妥。","summary_source":"llm","title_zh":"宝宝夜里哭闹是什么原因？先排查这一点","points":["排查基本生理需求","注意安全睡眠环境","关注身体和情绪因素"],"points_source":"llm","translated":true},{"title":"Danone joins Nestlé, Coca-Cola in revising recycling labels after EU greenwashing probe","summary":"在欧盟针对“漂绿”行为的调查背景下，达能、雀巢和可口可乐等食品饮料巨头正修订其回收标签。此举旨在明确标注瓶身回收材料的比例并避免误导性营销，体现了行业巨头对环保合规及消费者透明度要求的重视，对跨境出口产品的标签合规具有警示意义。对行业从业者而言，需关注欧盟环保法规变化，确保产品标签符合最新要求，避免合规风险。","source_id":"fooddive","source_name":"Food Dive","source_url":"https://www.fooddive.com/feeds/news/","original_url":"https://www.fooddive.com/news/danone-joins-nestle-coca-cola-revises-recycling-labels-after-eu-greenwashing-complaint/872777","published_at":"2026-10-28T22:18:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T22:44:57+08:00","language":"en","author":"Zoya Mirza","tags":["政策法规","质量安全","海外动态"],"priority":"P1","image":"https://imgproxy.divecdn.com/SFoJ6ZtSs8AMGzArpdRaKY5NZKQtnhTOH2Y7q_SNlv0/g:ce/rs:fill:1600:900:1/Z3M6Ly9kaXZlc2l0ZS1zdG9yYWdlL2RpdmVpbWFnZS9ldmlhbi5qcGc=.webp","score":9.6,"matched":["danone","nestlé"],"id":"f2376a5fff873fda","title_zh":"达能加入雀巢与可口可乐行列修订回收标签","summary_source":"llm","summary_kind":"brief","points":["达能修订回收标签应对欧盟调查","明确标注瓶身回收材料比例","避免误导性营销 claims"],"points_source":"llm","translated":true},{"title":"Dairy Farmers of America closes in on Nestlé in global dairy rankings","summary":"美国乳农合作社DFA通过一系列收购行动，正在重新塑造全球乳业排名，预计其销售额将超越雀巢。这一变化凸显了全球乳业竞争格局的动态调整，并购整合成为行业巨头提升市场地位的重要手段。对跨境母婴行业从业者而言，这意味着需要密切关注全球乳业的竞争态势，理解并购整合可能对市场格局及供应链带来的影响，以便及时调整策略以适应变化的市场环境。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/dairy-ma-reshapes-global-rankings-and-growth-strategies","published_at":"2026-10-28T21:44:27+08:00","published_guessed":false,"fetched_at":"2026-10-28T22:44:57+08:00","language":"en","author":"Timothy Inklebarger","tags":["市场数据","品牌动态","供应链"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/MANMYZOHVZCMVGAG7TEY5U4NTI.jpg?auth=b245991f1d2c2796ebe5eb60977f65c8d27a7c896642792fe663d2d0d2b0ebcf&smart=true&width=2121&height=1414","score":9.6,"matched":["nestlé","dairy"],"id":"4f58f2280bc22ba0","title_zh":"美国乳农合作社全球排名逼近雀巢","summary_source":"llm","summary_kind":"brief","points":["美国乳农合作社通过收购重塑排名","有望在销售额上超越雀巢","全球乳业竞争格局正在发生变化"],"points_source":"llm","translated":true},{"title":"Dairy Farmers of America closes in on Nestlé in global dairy rankings","summary":"美国乳农合作社DFA通过收购重塑全球乳业排名，有望在销售额上超越雀巢。这一动态表明全球乳业竞争格局正在发生变化，并购整合成为行业巨头提升排名的重要手段。对跨境母婴行业从业者而言，需关注全球乳业竞争态势，理解并购整合对市场格局及供应链可能产生的影响。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/dairy-ma-reshapes-global-rankings-and-growth-strategies","published_at":"2026-10-28T21:44:27+08:00","published_guessed":false,"fetched_at":"2026-10-29T09:17:46+08:00","language":"en","author":"Timothy Inklebarger","tags":["市场数据","品牌动态","供应链"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/MANMYZOHVZCMVGAG7TEY5U4NTI.jpg?auth=b245991f1d2c2796ebe5eb60977f65c8d27a7c896642792fe663d2d0d2b0ebcf&smart=true&width=2121&height=1414","score":9.6,"matched":["nestlé","dairy"],"id":"281895efb1bc9a51","title_zh":"美国乳农合作社DFA有望超越雀巢全球排名","translated":true,"summary_source":"llm","summary_kind":"brief","points":["美国乳农合作社DFA通过收购提升排名","全球乳业竞争格局变化","并购整合成为重要手段","关注全球乳业竞争态势"],"points_source":"llm"},{"title":"今天，达能最新季报出炉：亚太区前三季度增长最快，爱他美奶粉双11渠道进货积极","summary":"达能最新季报显示，亚太区前三季度增长最快，其中爱他美奶粉在双11期间渠道进货积极。这一数据反映出中国等亚太市场对婴幼儿奶粉的需求持续增长，对跨境奶粉品牌和渠道商意味着市场潜力巨大，需持续优化渠道策略以抓住增长机遇。最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。回顾前三季度，达能销售额同比增长3.6%，亚太市场以4.9%增幅成为增长最高的大区，且主要由销量/组合拉动。","source_id":"gnews_cn_ecom","source_name":"小食代","source_url":"https://news.google.com/rss/search?q=%E5%A5%B6%E7%B2%89%20%28%E7%9B%B4%E6%92%AD%20OR%20%E6%8A%96%E9%9F%B3%20OR%20%E5%A4%A9%E7%8C%AB%20OR%20%E4%BA%AC%E4%B8%9C%20OR%20%E5%8F%8C11%20OR%20%E6%8B%BC%E5%A4%9A%E5%A4%9A%29%20%28%E9%94%80%E9%87%8F%20OR%20%E5%A2%9E%E9%95%BF%20OR%20%E4%BB%B7%E6%A0%BC%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.foodinc.com.cn/2026/10/28/20261028002/","published_at":"2026-10-28T21:42:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:39:46+08:00","language":"zh","author":"","tags":["市场数据","跨境电商","品牌动态"],"priority":"P0","score":20.8,"matched":["奶粉","达能","爱他美","渠道"],"id":"cd68197b09ca2665","title_zh":"达能亚太区增长强劲，爱他美双11渠道活跃","summary_source":"llm","summary_kind":"brief","points":["达能亚太区增长最快","爱他美双11渠道进货积极","反映亚太市场需求增长","跨境奶粉品牌需优化渠道策略"],"points_source":"llm","translated":true,"link_resolved":true,"body":"最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。回顾前三季度，达能销售额同比增长3.6%，亚太市场以4.9%增幅成为增长最高的大区，且主要由销量/组合拉动。 财报显示，今年第三季度，达能销售额为72.33亿欧元（约合人民币536亿元），同比增长4%，其中销量/组合增长0.4%，定价增长3.6%。今年前三季度，该集团销售额为211.76亿欧元（约合人民币1570亿元），同比增长3.6%，其中销量/组合增长1.3%。 达能首席执行官盛睿安（Antoine de Saint-Affrique）表示，达能又一季的强劲表现反映出 全品类和地区的广泛增长势头 。该集团的多引擎增长模式继续展现出韧性，这得益于以健康为核心的产品优势和与市场趋势的契合度。 “从高蛋白、肠道健康到医学营养品，我们优势产品的需求在全球范围内保持强劲。”盛睿安说。 他又指，在依然波动的环境中，达能重申全年业绩指引不变。2026年，该集团预计销售额同比增长在3%～5%之间，经常性营业利润增速将高于销售额增长，两者均与达能中期目标保持一致。 小食代留意到，如何控制成本通胀在会上也是受关注话题之一。前几年，不少跨国快消企业因为通胀提价而遭遇销量下滑，处理好成本消化与品牌需求维持的矛盾成为共同课题。 据Esser透露，第三季度，油价及相关商品价格指数持续高企。 基于以往通胀周期经验，达能当季采取了主动且审慎的定价行动，按品类、按市场有选择地执行 ，始终将消费者置于决策的中心，平衡好可负担性、产品竞争力和可持续价值创造。 “ 我们尽早且果断地采取行动而不是拖延，以避免后续更大幅度的涨价。 ” Esser说，“油价持续高企，意味着我们通过大宗商品常规对冲所受到的保护越来越少，因此通胀压力正在逐季增加。” 他表示，面对这种情况，达能除了采取定价措施，也正大力提升生产力和效率。围绕销量/组合、定价和生产力的“组合拳”，将是达能在今年剩余时间和2027年推动利润率朝正确方向发展的关键。 财报显示，今年第三季度，达能亚太市场销售额同比增长 3.6% 至 16.46 亿欧元（约合人民币 122 亿元）。其中，销量 / 组合增长 1.7 % ，定价增长 1.9% 。前三季度 ，该大区 实现销售收入 47.62亿欧元，同比增长4.9% ，其中 销量 / 组合增长 3 .7 % 。 当季，达能亚太的专业特殊营养销售额同比增长7.9%至10.96亿欧元。达能首席财务官Juergen Esser表示， 专业特殊营养最重要的市场是中国。当季，中国业务对该品类业绩做出了超额贡献（注：即对增长贡献的占比超过自身规模占比）。 婴幼儿奶粉品牌爱他美保持良好表现，ESSENSIS熠系列仍是最大贡献者。 渠道在双11对达能奶粉的进货也非常积极 ，这是潜在需求强劲的一个信号。 “虽然（婴幼儿奶粉）品类增长疲软，但我们的表现优于市场，ESSENSIS熠系列做得非常好，销量/组合销售呈现积极态势。” Esser说。 他又指出，医学营养品也保持增长， 作为传统产品的医院肠内管饲继续增长。同时，达能也正大力投资院外业务，包括在药店销售的口服非处方营养品。 新业务虽然尚未真正规模化，但正加速发展，反响令人振奋。 再来看看脉动所在的饮料与饮用水。第三季度，达能饮用水和饮料业务实现销售收入13.70亿欧元，同比增长3.6%。","image":"https://www.foodinc.com.cn/wp-content/uploads/2026/10/c1ce4011396fd5707b8de31ef9fee156.jpg"},{"title":"今天，达能最新季报出炉：亚太区前三季度增长最快，爱他美奶粉双11渠道进货积极","summary":"达能第三季度销售额同比增长4%，亚太区增幅达4.9%，主要得益于销量和组合增长。亚太区前三季度销售额同比增长3.6%，其中中国对专业特殊营养品类业绩贡献突出。爱他美奶粉在双11期间渠道进货积极，ESSENSIS熠系列表现优异。达能正通过调整定价、提升生产效率等措施应对通胀压力，预计2026年销售额同比增长3%-5%。最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。","source_id":"gnews_cn_brands","source_name":"小食代","source_url":"https://news.google.com/rss/search?q=(%E9%9B%80%E5%B7%A2%20OR%20%E8%BE%BE%E8%83%BD%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E4%BC%8A%E5%88%A9%20OR%20%E6%BE%B3%E4%BC%98)%20(%E5%A5%B6%E7%B2%89%20OR%20%E5%A9%B4%E9%85%8D)%20-%E8%82%A1%E7%A5%A8&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.foodinc.com.cn/2026/10/28/20261028002/","published_at":"2026-10-28T21:42:00+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:39:14+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":20.8,"matched":["奶粉","达能","爱他美","渠道"],"id":"e85eba0d36d837a6","title_zh":"达能亚太区前三季度增长最快，爱他美奶粉双11渠道进货积极","summary_source":"llm","summary_kind":"brief","points":["达能亚太区增长快","爱他美双11进货积极","跨境电商渠道表现好"],"points_source":"llm","translated":true,"link_resolved":true,"body":"最新财报显示，第三季度，达能销售额同比增长4%，所有品类与大区均录得正增长。回顾前三季度，达能销售额同比增长3.6%，亚太市场以4.9%增幅成为增长最高的大区，且主要由销量/组合拉动。 财报显示，今年第三季度，达能销售额为72.33亿欧元（约合人民币536亿元），同比增长4%，其中销量/组合增长0.4%，定价增长3.6%。今年前三季度，该集团销售额为211.76亿欧元（约合人民币1570亿元），同比增长3.6%，其中销量/组合增长1.3%。 达能首席执行官盛睿安（Antoine de Saint-Affrique）表示，达能又一季的强劲表现反映出 全品类和地区的广泛增长势头 。该集团的多引擎增长模式继续展现出韧性，这得益于以健康为核心的产品优势和与市场趋势的契合度。 “从高蛋白、肠道健康到医学营养品，我们优势产品的需求在全球范围内保持强劲。”盛睿安说。 他又指，在依然波动的环境中，达能重申全年业绩指引不变。2026年，该集团预计销售额同比增长在3%～5%之间，经常性营业利润增速将高于销售额增长，两者均与达能中期目标保持一致。 小食代留意到，如何控制成本通胀在会上也是受关注话题之一。前几年，不少跨国快消企业因为通胀提价而遭遇销量下滑，处理好成本消化与品牌需求维持的矛盾成为共同课题。 据Esser透露，第三季度，油价及相关商品价格指数持续高企。 基于以往通胀周期经验，达能当季采取了主动且审慎的定价行动，按品类、按市场有选择地执行 ，始终将消费者置于决策的中心，平衡好可负担性、产品竞争力和可持续价值创造。 “ 我们尽早且果断地采取行动而不是拖延，以避免后续更大幅度的涨价。 ” Esser说，“油价持续高企，意味着我们通过大宗商品常规对冲所受到的保护越来越少，因此通胀压力正在逐季增加。” 他表示，面对这种情况，达能除了采取定价措施，也正大力提升生产力和效率。围绕销量/组合、定价和生产力的“组合拳”，将是达能在今年剩余时间和2027年推动利润率朝正确方向发展的关键。 财报显示，今年第三季度，达能亚太市场销售额同比增长 3.6% 至 16.46 亿欧元（约合人民币 122 亿元）。其中，销量 / 组合增长 1.7 % ，定价增长 1.9% 。前三季度 ，该大区 实现销售收入 47.62亿欧元，同比增长4.9% ，其中 销量 / 组合增长 3 .7 % 。 当季，达能亚太的专业特殊营养销售额同比增长7.9%至10.96亿欧元。达能首席财务官Juergen Esser表示， 专业特殊营养最重要的市场是中国。当季，中国业务对该品类业绩做出了超额贡献（注：即对增长贡献的占比超过自身规模占比）。 婴幼儿奶粉品牌爱他美保持良好表现，ESSENSIS熠系列仍是最大贡献者。 渠道在双11对达能奶粉的进货也非常积极 ，这是潜在需求强劲的一个信号。 “虽然（婴幼儿奶粉）品类增长疲软，但我们的表现优于市场，ESSENSIS熠系列做得非常好，销量/组合销售呈现积极态势。” Esser说。 他又指出，医学营养品也保持增长， 作为传统产品的医院肠内管饲继续增长。同时，达能也正大力投资院外业务，包括在药店销售的口服非处方营养品。 新业务虽然尚未真正规模化，但正加速发展，反响令人振奋。 再来看看脉动所在的饮料与饮用水。第三季度，达能饮用水和饮料业务实现销售收入13.70亿欧元，同比增长3.6%。","image":"https://www.foodinc.com.cn/wp-content/uploads/2026/10/c1ce4011396fd5707b8de31ef9fee156.jpg"},{"title":"Danone delivers a strong Q3 performance","summary":"达能第三季度业绩增长主要得益于高蛋白、肠道健康及医学营养产品在关键全球市场的强劲需求。该业绩表现反映了乳业高端化与功能性产品趋势的延续，对行业从业者具有积极的参考价值。这一趋势表明消费者对高端和功能性乳制品的需求持续增长，为行业产品研发和市场布局提供了方向。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/28/strong-q3-driven-by-nutrition-trends","published_at":"2026-10-28T21:00:58+08:00","published_guessed":false,"fetched_at":"2026-10-28T21:16:37+08:00","language":"en","author":"","tags":["市场数据","品牌动态","质量安全"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/TFBLXX44NZHZXJ43H2ABZDVEP4.jpg?auth=789d53c44e9f407e06b1d9feae8073f368896c7f45d75e02f5d2a41790de038a&smart=true&width=2000&height=1500","score":4.8,"matched":["danone"],"id":"55a6b3475e71ed6f","title_zh":"达能第三季度业绩强劲","summary_source":"llm","summary_kind":"brief","points":["高蛋白及医学营养产品需求强劲","肠道健康品类增长显著","全球市场表现亮眼"],"points_source":"llm","translated":true},{"title":"Nestle USA names top trends for 2027","summary":"雀巢美国预测2027年蛋白质趋势将持续演变，果味风味产品将更受消费者青睐。这一趋势预测为行业产品研发与市场布局提供了前瞻性指引，有助于企业把握未来消费方向。对从业者而言，需关注蛋白质趋势演变和果味产品市场变化，及时调整产品策略以适应未来消费需求。","source_id":"foodbusinessnews","source_name":"Food Business News","source_url":"https://www.foodbusinessnews.net/rss/articles","original_url":"https://www.foodbusinessnews.net/articles/31255-nestle-usa-names-top-trends-for-2027","published_at":"2026-10-28T19:22:15+08:00","published_guessed":false,"fetched_at":"2026-10-28T21:16:38+08:00","language":"en","author":"","tags":["市场数据","政策法规","跨境电商"],"priority":"P1","image":"https://www.foodbusinessnews.net/ext/resources/2026/10/28/nestle-trends-lead.webp?t=1793190418","score":4.8,"matched":["nestle"],"id":"d3bcd784d769e2d7","title_zh":"雀巢美国发布2027年趋势预测","summary_source":"llm","summary_kind":"brief","points":["蛋白质趋势将持续演变","果味风味产品需求上升","2027年趋势预测发布"],"points_source":"llm","translated":true},{"title":"孩子王三季度归母净利润3669.80万元 同比下降44.42%","summary":"孩子王作为母婴零售行业的知名企业，其三季度业绩出现明显下滑，归母净利润同比下降44.42%。这一数据反映出母婴零售市场面临消费疲软和竞争加剧的挑战。对行业从业者而言，孩子王的经营状况警示着市场的不确定性，需要加强成本控制和渠道创新以应对变化。","source_id":"gnews_cn_retail","source_name":"观点网","source_url":"https://news.google.com/rss/search?q=%28%E6%AF%8D%E5%A9%B4%E5%BA%97%20OR%20%E6%AF%8D%E5%A9%B4%E8%BF%9E%E9%94%81%20OR%20%E5%AD%A9%E5%AD%90%E7%8E%8B%20OR%20%E7%88%B1%E5%A9%B4%E5%AE%A4%20OR%20%E6%AF%8D%E5%A9%B4%E6%B8%A0%E9%81%93%29%20%28%E5%A5%B6%E7%B2%89%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%85%B3%E5%BA%97%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.guandian.cn/article/20261028/619654.html","published_at":"2026-10-28T17:56:21+08:00","published_guessed":false,"fetched_at":"2026-10-28T21:17:26+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","跨境电商"],"priority":"P0","score":6.4,"matched":["孩子王"],"id":"9bbc919ac34eed71","title_zh":"孩子王三季度归母净利润3669.80万元 同比下降44.42%","summary_source":"llm","summary_kind":"brief","translated":true,"link_resolved":true,"body":"观点网讯： 孩子王数智科技股份有限公司发布2026年第三季度报告，前三季度公司营业收入75.06亿元，同比增长2.14%；归属于上市公司股东的净利润2.08亿元，同比下降0.40%。 第三季度单季，公司营业收入24.11亿元，同比下降1.08%；归母净利润3669.80万元，同比下降44.42%；扣除非经常性损益的净利润2550.58万元，同比下降37.93%。 盈利指标方面，公司第三季度基本每股收益0.0292元/股，同比下降44.17%；加权平均净资产收益率0.83%，同比减少0.81个百分点。 前三季度，公司扣非净利润1.50亿元，同比下降3.90%；基本每股收益0.1659元/股，同比下降0.06%；加权平均净资产收益率4.81%，同比减少0.20个百分点；经营活动产生的现金流量净额6.95亿元，同比下降36.46%。 报告期末，公司总资产106.13亿元，比上年度末下降1.48%；归属于上市公司股东的所有者权益44.21亿元，比上年度末增长3.93%。 非经常性损益方面，前三季度公司计入当期损益的政府补助2216.90万元，系政府拨付的各项补助金；持有及处置金融资产相关损益4767.54万元，系公司为提高资金使用效率购买低风险理财产品；非流动性资产处置损益1129.69万元，主要系本期处置资产形成的收益。 公告显示，第三季度财务会计报告未经审计，公司无需追溯调整或重述以前年度会计数据。","image":"https://www.guandian.cn/statics/index2022/img/search.png","points":["归属于上市公司股东的净利润2.08亿元，同比下降0.40%","第三季度单季，公司营业收入24.11亿元，同比下降1.08%","归母净利润3669.80万元，同比下降44.42%"],"points_source":"extract"},{"title":"【微奶价】3.26元/公斤！内蒙古第四季度生鲜乳交易参考价确定","summary":"搜狐网报道，内蒙古第四季度生鲜乳交易参考价确定为每公斤3.26元。这一价格变动对婴幼儿奶粉行业从业者有重要影响，意味着原料成本的变化，需关注乳制品供应链成本调整。生鲜乳是婴幼儿奶粉的主要原料，价格波动直接影响生产成本和产品定价策略。从业者需密切关注原料市场动态，优化供应链管理，以应对成本变化带来的挑战。","source_id":"gnews_cn_supply","source_name":"搜狐网","source_url":"https://news.google.com/rss/search?q=(%E5%8E%9F%E5%A5%B6%20OR%20%E7%94%9F%E9%B2%9C%E4%B9%B3%20OR%20%E4%B9%B3%E6%B8%85%20OR%20%E4%B9%B3%E9%93%81%E8%9B%8B%E7%99%BD%20OR%20%E5%A4%A7%E5%8C%85%E7%B2%89%20OR%20%E5%8E%9F%E6%96%99%E5%A5%B6%E7%B2%89)%20(%E4%BB%B7%E6%A0%BC%20OR%20%E6%8B%8D%E5%8D%96%20OR%20%E4%BE%9B%E5%BA%94%20OR%20%E4%BA%A7%E8%83%BD)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.sohu.com/a/1093950304_122014422?scm=10001.325_13-325_13.0.0-0-0-0-0.5_1334","published_at":"2026-10-28T17:35:40+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:32+08:00","language":"zh","author":"","tags":["市场数据","供应链"],"priority":"P0","score":4.8,"matched":["生鲜乳"],"id":"335a5003a6eb2318","title_zh":"【微奶价】3.26元/公斤！内蒙古第四季度生鲜乳交易参考价确定","summary_source":"llm","summary_kind":"brief","translated":true,"link_resolved":true,"body":"10月26日，内蒙古自治区生鲜乳价格协调委员会召开全区第四季度生鲜乳价格协商会议。经第三方机构科学测算、与会委员共同协商，商定2026年第四季度生鲜乳交易参考价为3.26元/公斤。鼓励优质优价，因指标差异等市场因素，可以上下浮动，上浮不设限，下浮不超过3%。 请生鲜乳购销双方以交易参考价为基础，按照质价相符、以质论价、互利共赢原则，协商确定生鲜乳实际收购价格。","image":"https://q8.itc.cn/q_70/images03/20261028/8126a86c193c4886894f9113a714ec59.png","points":["经第三方机构科学测算、与会委员共同协商，商定2026年第四季度生鲜乳交易参考价为3.26元/…","鼓励优质优价，因指标差异等市场因素，可以上下浮动，上浮不设限，下浮不超过3%","请生鲜乳购销双方以交易参考价为基础，按照质价相符、以质论价、互利共赢原则，协商确定生鲜乳实际…"],"points_source":"extract"},{"title":"Danone sales rise as health-focused brands and price increases drive growth","summary":"达能公司报告销售额强劲增长，主要得益于其健康品牌组合和价格提升。这一增长反映了消费者对健康产品的持续需求，以及企业通过价格策略应对市场变化的能力。对于婴幼儿奶粉行业的从业者而言，这意味着健康定位和灵活定价策略的重要性日益凸显，需要密切关注市场动态和消费者偏好变化，及时调整产品策略以适应市场需求。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/28/danone-q3-sales-rise-4-as-health-focused-brands-and-price-increases-drive-growth","published_at":"2026-10-28T17:27:56+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:07+08:00","language":"en","author":"","tags":["市场数据","质量安全","品牌动态"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/7VVKPWGRV5EWDHEPVBPXRP4BUE.jpg?auth=c2327b005da8f896e88fcb8b22ed914d5d574e2f90f22ed02976376c9ca84682&smart=true&width=2120&height=1414","score":4.8,"matched":["danone"],"id":"5af5a2e6379ec805","title_zh":"达能销售额增长 健康品牌和提价推动增长","summary_source":"llm","summary_kind":"brief","points":["达能健康品牌推动增长","提价策略成效显著"],"points_source":"llm","translated":true},{"title":"中印尼企业合建纸尿裤工厂投产在即","summary":"中国与印尼企业合作建设的纸尿裤工厂即将投产，显示两国在婴幼儿用品供应链领域的合作深化。这一事件对跨境母婴行业有重要意义，表明供应链多元化布局有助于降低成本、提升效率。对从业者而言，这意味着更多市场机会和更优化的资源配置选择。按照规划，这条高速产线满负荷运转，年产能最高可达到18亿片纸尿裤。企业长期目标是陆续配齐10条全自动生产线，完成上下游垂直整合。MMIX原本是进口授权产品的大型经销商，这次转型自主生产，是公司最重要的增长引擎。","source_id":"gnews_cn_baby_category","source_name":"每日印尼","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.indonesia-daily.com/page_52664.html","published_at":"2026-10-28T14:56:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:30+08:00","language":"zh","author":"","tags":["供应链","跨境电商","海外动态"],"priority":"P1","score":4.8,"matched":["纸尿裤"],"id":"b15a55d803ecdf48","title_zh":"中印尼企业合建纸尿裤工厂投产在即","summary_source":"llm","summary_kind":"brief","points":["中印尼企业合建纸尿裤工厂","跨境行业重要意义"],"points_source":"llm","translated":true,"link_resolved":true,"body":"印尼上市公司PT Multi Medika Internasional Tbk（MMIX）加速业务转型，正抓紧完工和中国福建恒安集团合资建设的纸尿裤工厂，合资主体为PT Multi Nice Paper Indonesia（MNPI）。 项目选址万丹省唐格朗，占地1公顷，产线设计速度可达每分钟1000片纸尿裤，为印尼当前速度最快的纸尿裤生产线。MMIX公司秘书表示，该项目是企业加码个人护理赛道、打造可持续业务组合的重要布局。这座一体化工厂落地后，将实现主力品牌MIUBaby婴儿纸尿裤本地化生产。 该品牌目前已经在Alfamart、Indomaret等大型连锁商超拿到独家分销渠道，本地化生产将进一步巩固渠道优势。工厂初期主打婴儿纸尿裤，后续会逐步拓展成人纸尿裤、女性卫生巾、湿巾等品类。按照规划，这条高速产线满负荷运转，年产能最高可达到18亿片纸尿裤。企业长期目标是陆续配齐10条全自动生产线，完成上下游垂直整合。通过自产模式，企业可以更好管控生产成本、把控产品品质，显著降低销售成本，增厚净利润空间。 MMIX原本是进口授权产品的大型经销商，这次转型自主生产，是公司最重要的增长引擎。母婴护理板块目标在2026年贡献公司总营收的40%–50%。管理层看好印尼本土市场，随着家长对高品质母婴产品需求提升，期待母婴护理业务保持11%及以上的增速。该合资项目进展持续受到资本市场关注，项目推进消息在印尼交易所发布后，获得市场积极反馈。 依托中方成熟的制造技术，叠加印尼本土成熟零售网络，这家合资工厂有望改变印尼纸尿裤市场格局，也成为中企在印尼快消品本土化投资的典型案例。","image":"https://www.indonesia-daily.com/wp-content/uploads/2026/10/08_________________-2.webp"},{"title":"庖根闻笛丨跨境营养品“翻车”启示录","summary":"跨境营养品市场近年来出现产品质量不过关、虚假宣传等问题，给消费者和行业带来负面影响。这提醒从业者必须重视产品质量和合规性，加强供应链管理，避免类似事件发生。关注行业动态，及时调整策略，是维护市场信誉和长远发展的关键。这一事件反映了跨境营养品市场存在的风险，从业者需提高警惕，加强内部管理，确保产品符合目标市场的法规要求，以维护行业声誉和消费者信任。","source_id":"muyingqianyan","source_name":"母婴前沿","source_url":"https://www.muyingqianyan.com/feed","original_url":"https://www.muyingqianyan.com/123364.html","published_at":"2026-10-28T10:35:50+08:00","published_guessed":false,"fetched_at":"2026-10-28T11:45:19+08:00","language":"zh","author":"前沿, 母婴","tags":["跨境电商","质量安全","品牌动态"],"priority":"P0","score":4.8,"matched":["营养品"],"id":"0bcc13c29cc7fa21","image":"https://www.muyingqianyan.com/wp-content/uploads/2021/07/e6570c2e9d90b442ec5abe68c80669c.png","title_zh":"庖根闻笛丨跨境营养品“翻车”启示录","summary_source":"llm","summary_kind":"brief","points":["跨境营养品市场问题频发","产品质量和合规性受关注","供应链管理需加强"],"points_source":"llm","translated":true},{"title":"宝宝辅食工具必备清单","summary":"虎扑体育发布宝宝辅食工具清单，涵盖各类辅助喂养设备。这类清单为母婴用品销售和推荐提供指导，帮助从业者优化产品组合与营销策略。对跨境母婴行业而言，了解消费者对辅食工具的需求有助于把握市场趋势，开发符合需求的产品和服务。辅食工具是婴幼儿喂养的重要辅助，其市场变化直接反映消费者需求升级，从业者需密切关注此类清单，及时调整产品策略以适应市场变化。","source_id":"gnews_cn_baby_category","source_name":"虎扑体育","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.hupu.com/score-item/common_second/3575610","published_at":"2026-10-28T09:53:53+08:00","published_guessed":false,"fetched_at":"2026-10-28T19:00:30+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":11.2,"matched":["辅食","宝宝"],"id":"4da94d655e11e2e5","title_zh":"宝宝辅食工具必备清单","summary_source":"llm","summary_kind":"brief","points":["列出宝宝辅食工具清单","涉及辅助喂养设备","指导母婴用品销售","优化产品组合与营销"],"points_source":"llm","translated":true,"link_resolved":true},{"title":"中顺洁柔（云浮）纸业年产5.5 万吨湿巾项目环评公示","summary":"纸业网公示了中顺洁柔（云浮）纸业年产5.5万吨湿巾项目的环境影响评价。该项目涉及湿巾生产，对原料供应链和产品质量安全有直接影响。对母婴行业从业者而言，了解相关企业的生产动态有助于把握行业发展趋势，关注供应链变化。湿巾是婴幼儿日常护理的重要用品，其生产企业的动态变化关系到行业供应链的稳定性和产品质量，从业者需持续关注此类信息，确保供应链安全与合规。","source_id":"gnews_cn_baby_category","source_name":"纸业网","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"http://www.paper.com.cn/news/daynews/2026/261028095119527233.htm","published_at":"2026-10-28T09:52:39+08:00","published_guessed":false,"fetched_at":"2026-10-28T13:00:28+08:00","language":"zh","author":"","tags":["政策法规","供应链","质量安全"],"priority":"P1","score":4.8,"matched":["湿巾"],"id":"c2bb9e9434e156b5","title_zh":"中顺洁柔（云浮）纸业年产5.5万吨湿巾项目环评公示","summary_source":"llm","summary_kind":"brief","points":["湿巾生产项目环评公示"],"points_source":"llm","translated":true,"link_resolved":true,"image":"https://www.paper.com.cn/images/cnpaper.png"},{"title":"DairyNZ Outlines Six Government Priorities As Dairy Export Revenues Reach $28.8B - https://en.edairynews.com/","summary":"新西兰乳业出口收入达到 28.8 亿美元，DairyNZ 列出六项政府优先事项。对从业者意味着需关注新西兰乳业的出口表现和政策导向，这类数据反映了奶源国的市场竞争力和发展潜力。对跨境乳企而言，需关注奶源国的市场动态和政策支持，以把握市场机遇和提升自身竞争力。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://en.edairynews.com/dairynz-outlines-six-government-priorities-as-dairy-export-revenues-reach-28-8b/","published_at":"2026-10-28T07:35:07+08:00","published_guessed":false,"fetched_at":"2026-10-28T09:20:25+08:00","language":"en","author":"","tags":["市场数据","海外动态","跨境电商"],"priority":"P0","score":9.6,"matched":["dairy","dairy export"],"id":"a0eebd30f732fb24","link_resolved":true,"body":"The central pillar of DairyNZ’s briefing to political parties is the demand for regulatory durability that respects agricultural investment horizons. Brown pointed out that commercial dairy enterprises make capital allocation decisions—such as commissioning advanced rotary milking sheds, installing environmental riparian corridors, or constructing automated effluent containment infrastructure—that span decades rather than three-year parliamentary cycles. Continuous regulatory revisions, particularly surrounding freshwater management and resource consents, generate operational uncertainty and stall on-farm capital deployment. The industry is advocating for a clear legislative standard: environmental and resource regulations must be evidence-based, scientifically robust, workable under everyday commercial farming conditions, and resilient enough to remain relevant over a 10-year planning window. The organization’s six core priorities focus directly on addressing structural bottlenecks across the pastoral value chain: practical freshwater and Resource Management Act (RMA) reforms that protect natural waterways while allowing productive land use; a fortified national biosecurity system prepared for emergent biological incursions; immigration and vocational settings that attract skilled labor to rural careers; sustained investment in agricultural science paired with expedited access to productivity-enhancing agritech; resilient rural infrastructure alongside workable, non-punitive pathways to lower on-farm greenhouse gas emissions; and science-grounded animal welfare standards that reflect operational realities. From an environmental compliance and farm systems perspective, dairy producers have already demonstrated significant proactive stewardship, investing millions in stream exclusion fencing, constructed wetlands, and precision nutrient management plans. However, industry leadership warns that policy friction arises when centralized mandates become overly complex, impose redundant compliance reporting, or enforce arbitrary restrictions that ignore regional catchment diversity.","image":"https://en.edairynews.com/wp-content/uploads/2026/10/DairyNZ-outlines-six-government-priorities-as-dairy-export-revenues-reach-28.8B.jpg","summary_source":"llm","summary_kind":"brief","title_zh":"新西兰乳业出口收入达288亿美元","translated":true,"points":["新西兰乳业出口收入28.8亿美元","DairyNZ列六项政府优先事项","关注新西兰乳业出口表现","需关注奶源国政策支持"],"points_source":"llm"},{"title":"Arunachal Dairy Sector Gets ITBP Milk Supply Pact - urbanacres.in","summary":"Arunachal Pradesh has signed an agreement with the Indo-Tibetan Border Police (ITBP) to supply locally produced packaged milk and dairy products to the force’s 31st Battalion, creating an assured inst…","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://urbanacres.in/arunachal-dairy-sector-gets-itbp-market-boost-under-new-milk-pact/","published_at":"2026-10-28T07:15:13+08:00","published_guessed":false,"fetched_at":"2026-10-28T09:20:25+08:00","language":"en","author":"","tags":["供应链"],"priority":"P0","score":16.0,"matched":["dairy","milk supply","dairy sector"],"id":"4c3b84aa51171ce0","summary_source":"extract","link_resolved":true,"body":"Arunachal Pradesh has signed an agreement with the Indo-Tibetan Border Police (ITBP) to supply locally produced packaged milk and dairy products to the force’s 31st Battalion, creating an assured institutional market for dairy cooperatives and milk producers in the state. The memorandum of understanding was signed at the civil secretariat in Itanagar on Monday in the presence of state Animal Husbandry, Veterinary and Dairy Development minister Gabriel D Wangsu and senior government and ITBP officials. A milk supply van was also flagged off at the event. The products will be supplied under the Arun Dairy brand. The state government said the arrangement is intended to strengthen the dairy cooperative sector and provide a dependable market for local milk producers. The agreement connects local production with the regular procurement requirements of a large institutional consumer rather than leaving farmers dependent only on fragmented retail demand. Wangsu said dairy development could help increase farmers’ incomes, generate rural employment and promote economic self-reliance. He also said institutional partnerships could give local producers access to assured markets, encourage dairy entrepreneurship and make dairy farming a more viable livelihood. The partnership also places operational emphasis on the supply chain required to move packaged milk and dairy products from local producers to the ITBP battalion. The source report does not specify the volume of milk to be supplied, the contract period, pricing arrangements, the number of participating cooperatives or the locations from which the products will be sourced. ITBP deputy inspector general for the North East Frontier, Abu Sufian, highlighted the importance of linking local dairy production with the force’s institutional requirements. The agreement therefore serves both a procurement function for the battalion and a market-access function for producers, although the available information does not establish how many farmers or cooperatives will benefit initially. Chief minister Pema Khandu welcomed the initiative in a post on X, appreciating the Animal Husbandry, Veterinary and Dairy Development department and the ITBP for joining hands to facilitate the supply of locally produced milk and dairy products.","image":"https://urbanacres.in/wp-content/uploads/2026/10/urban-acres-news-265289.webp"},{"title":"Conveyors and palletizers keep dairy processing lines moving","summary":"输送机和托盘装载机在乳制品加工中扮演关键角色，其市场预计将持续增长。这些设备对加工线的性能有显著影响，能提升产品流转效率、保证产品完整性和卫生标准。对从业者而言，了解这些设备的技术发展趋势，有助于优化生产线布局，提高生产效率和产品质量。","source_id":"dairyfoods","source_name":"Dairy Foods","source_url":"https://www.dairyfoods.com/","original_url":"https://www.dairyfoods.com/articles/99495-conveyors-and-palletizers-keep-dairy-processing-lines-moving","published_at":"","published_guessed":true,"fetched_at":"2026-10-28T04:52:48+08:00","language":"en","author":"","tags":["政策法规","质量安全","供应链"],"priority":"P2","score":4.8,"matched":["dairy"],"id":"e08c2fca4c1cf86e","image":"https://www.dairyfoods.com/ext/resources/2026/10/27/Key.jpg?height=635&t=1793129250&width=1200","body":"Conveyors and palletizers are big businesses. According to India-based Mordor Intelligence, the global conveyor market is expected to surpass $10 billion this year, and is forecast to reach $12.5 billion by 2031, growing at a 4.3% compound annual growth rate (CAGR). Meanwhile, palletizer sales are expected to be $2.6 billion globally this year and grow at a 2.2% CAGR to reach $3.2 billion by 2036, predicts Newark, Del.-based Future Markets Insights. According to Tom Munck, director of engineering at Walla Walla, Wash.-based Key Technology, conveyors have a significant impact on the performance of the entire dairy processing line. “Positioned between major processing steps, they help determine how efficiently product reaches sorters, multi-head weighers, packaging machines and other downstream equipment. Modern conveying systems do much more than move products from Point A to Point B,” he tells Dairy Foods . “They manage product flow by distributing, spreading, aligning and feeding product to downstream processes, while also performing functions such as fines removal, dewatering, scalping and lane diversion.” Three priorities consistently drive conveyor selection in dairy processing: uptime, product integrity and sanitation, he adds. “An unplanned conveyor stoppage can disrupt downstream production and reduce overall line efficiency. At the same time, delicate or coated dairy products can lose value when handling causes breakage, degradation or coating loss. Sanitation is equally critical, as cleaning time directly reduces available production time.” When purchasing a conveyor, Ted Yeigh, NW region manager at Columbia Machine Inc., Vancouver, Wash., stresses a big consideration is to ensure you have flexibility for all package types to be palletized and capacity. “When proposing a conveyor and palletizing solution for a dairy producer, we always start with the capacity of the filler. We will look at the maximum capacity of the filler and add roughly 15% to ensure the system stays in balance and can withstand the occasional temporary line interruption.” Columbia Machine palletizing equipment is designed to accommodate a variety of dairy package types. Image courtesy of Columbia Machine Inc. Munck asserts that dairy processors should start with the product, as opposed to the equipment.","summary_source":"llm","title_zh":"输送机和托盘装载机保障乳制品加工线高效运转","points":["输送机市场预计超10亿美元","托盘装载机市场预计达2.6亿美元","设备对加工线性能有显著影响","提升产品流转效率"],"points_source":"llm","translated":true},{"title":"从“母婴用纸”到“敏感时刻”，可心柔如何寻找保湿纸赛道新增量？","summary":"可心柔通过推出“敏肌适用”保湿纸系列，从原先专注母婴市场转向泛人群和泛场景。品牌凭借在保湿纸领域的九年销售额第一优势，洞察到保湿纸低摩擦、减少肌肤刺激的特性适用于更广泛人群。此举旨在抓住出生人口变化下母婴市场增长放缓的机遇，通过迁移护肤行业的“低刺激、肤感友好”消费逻辑，降低新品类用户接受难度，拓展市场空间。对从业者而言，这提示了在细分品类中寻找差异化增长路径的重要性，以及借鉴成熟消费心智破圈的可能性。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/6/20261028/1869538.shtml","published_at":"2026-10-28T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T11:46:04+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":6.4,"matched":["母婴"],"id":"ee3c7990d5c9f041","image":"https://img251118.xingkongmt.com/53134_7d5dd747-dcd5-4ca8-9fca-77ce468481a0.png","body":"生活用纸的竞争，正在从层数、抽数和价格，延伸到越来越细的使用场景。厨房纸、湿厕纸、棉柔巾各有用途，消费者不再只看一张纸能否完成清洁，也开始关注它用在哪里、接触肌肤时体验如何。 有公开数据表明，成熟纸品竞争激烈的背景下增速放缓，而细分品类却仍在快速增长，说明“专纸专用”正在打开新的市场空间。以可心柔为例，近期官宣全球品牌代言人檀健次，并带来全新的“敏肌适用”系列新品，走出原先母婴用纸的舒适区，迈向泛人群“敏肌人群”以及泛场景“敏感时刻”，这也为卫品行业提供了一个观察样本。 保湿纸品类最早的沃土在母婴市场。这与婴幼儿娇嫩肌肤对反复擦拭不伤肤的需求有关。对于普通消费者，一张纸够不够柔或许只是体验差异;对母婴家庭而言，柔软、低摩擦更容易成为明确的购买理由。 可心柔敏锐地洞察到了这一点，并由此在保湿纸领域积累起优势。公开资料显示，品牌2011年开始布局保湿纸，2013年投入千万级资金自研核心保湿技术并开发多分子分层锁水技术;2017年首次做到保湿纸全网销售额第一;按2017—2025年全网销售额计，品牌已连续九年位居保湿纸品类销售额第一。 不过，随着出生人口的变化，母婴赛道的增长天花板正在显现。2025年我国出生人口为792万，较上年减少162万，单纯依托新生儿增量的增长模式具备局限性。传统纸企的思路多为继续拓展纸种，母婴品牌多为不断扩充SKU，而可心柔正在尝试另一种差异化路径：不急着卖更多东西，而是先把已经经过母婴市场验证的“柔护能力”带给更多人群和场景。 这并非被动应对市场变化的无奈选择，而是提前布局增量市场的主动转向。事实上，保湿纸低摩擦、减少肌肤刺激的产品特性，不只适配婴儿，同样能解决成年人各类肌肤脆弱场景的擦拭痛点。只是要让成年人也觉得自己需要一张保湿纸，“宝宝娇嫩”这套理由显然不够了。 于是，品牌需要找到一种成年人更易共鸣的消费语言——大众在护肤消费里已经建立起来的「肌肤友好、低刺激」选购思维。 首先，这源自开头提到的行业洞察——大家对纸巾的需求正在朝着细分和升级发展，随着“专纸专用”成为趋势，消费者开始按照使用部位和场景区分纸品。 尤其在洁面后擦脸、花粉季反复擦鼻、运动或暴晒后等肌肤脆弱的“敏感时刻”，大家除了关心“能不能擦干净”，还会多一层考量：反复擦拭以后，皮肤会不会受刺激? 这也正是这套“护肤”评价体系能够进入纸品赛道的底层前提——它并不是品牌凭空创造出的概念，而是消费者需求本身正在向“低刺激、肤感友好”方向升级。 第二个原因与教育成本有关——直接复用护肤行业已经成熟的消费逻辑，可以大幅降低新品类的用户接受难度。消费者买洁面、面霜和防晒时，早已习惯根据自己的肤质和肌肤状态做选择：是不是敏感肌?使用了什么原料?做过哪些检测?是否适合当前的皮肤状态? 这套决策逻辑已经非常成熟。因此，可心柔不需要重新发明一种消费者语言，只需要把这套认知迁移到纸品上：既然护肤产品需要适配肤质，每天接触面部的那张纸，为什么不以同样标准挑选? 于是，“敏肌适用”被直接写上包装正面，食品级甘油、积雪草等原料、第三方敏感肌适用认证、反复擦拭测试等信息，共同构成这套产品表达。 可心柔不用从零教育消费者，而是借护肤行业已经成熟的心智直接完成破圈。理解成本更低、购买理由更直接。","points":["推出“敏肌适用”保湿纸系列","连续九年保湿纸销售额第一","迁移护肤行业消费逻辑","拓展泛人群和泛场景市场"],"points_source":"llm","summary_source":"llm","title_zh":"从“母婴用纸”到“敏感时刻”，可心柔如何寻找保湿纸赛道新增量？","translated":true},{"title":"宝宝有这3个表现，可能是进入厌奶期了","summary":"厌奶期是婴幼儿成长中的常见生理阶段，表现为奶量下降、注意力分散、生长发育不受明显影响。家长需科学应对，避免过度焦虑或强迫喂奶。了解厌奶期的典型表现有助于平稳度过，同时需关注宝宝的健康状况，必要时就医排查潜在问题。这一知识对跨境母婴从业者有参考价值，有助于提供更专业的喂养指导。第一个核心表现，就是奶量出现无诱因的明显下降。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/2/20261028/1869541.shtml","published_at":"2026-10-28T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T15:36:12+08:00","language":"zh","author":"","tags":["质量安全","品牌动态"],"priority":"P1","score":4.8,"matched":["宝宝"],"id":"eb3f669e62d951f8","body":"厌奶是宝宝成长过程中非常普遍的生理阶段，多数情况下不会对健康造成明显影响，家长不需要过度焦虑，先通过几个典型表现初步判断，再用科学的方式平稳过渡，就能帮宝宝顺利度过这段时期。 第一个核心表现，就是奶量出现无诱因的明显下降。原本规律的进食节奏突然被打破，单次摄入的奶量比日常正常水平减少三分之一甚至更多，且这种低进食状态会持续一周左右的时间。宝宝不会出现明显的哭闹、拒食、痛苦反应，只是在吃奶时表现得兴趣不高，不会主动发起强烈的觅食信号，整体进食状态从主动渴求变成被动接受，没有任何病理状态下的抗拒和不适表现。 第二个典型表现，是吃奶时注意力极易被分散。随着宝宝感知能力快速发育，对外界环境的好奇心明显提升，周围的轻微声响、光线变化、人员走动，都会立刻打断宝宝的吸吮动作，转头将注意力投向其他方向，很难再回到进食状态。整个吃奶过程的耗时明显拉长，有效吸吮的时间大幅缩短，以往十几分钟就能完成的进食，现在可能需要半小时以上才能勉强完成，且全程宝宝都处于容易分心、东张西望的状态，没有任何身体不适的哭闹信号。 第三个常见表现，是整体生长发育状态不受明显影响。虽然短期奶量有所下降，但宝宝的精神状态、睡眠质量、日常互动反应都维持在正常水平，没有出现精神萎靡、频繁哭闹、体重骤降、尿量明显减少的异常情况。体重增长曲线只是短暂出现平缓趋势，不会出现明显的下滑断层，身体各项基础指标都处于对应月龄的正常参考范围内，没有出现病理状态下的发育停滞信号。 确认宝宝进入厌奶期后，家长首先要调整自身心态，不要因为短期奶量下降就陷入过度焦虑，更不要采用强迫喂奶的方式硬灌，这样反而会让宝宝对进食产生更强的抵触心理，拉长厌奶的持续时间。日常喂养时要尽量选择光线柔和、环境安静的空间，减少外界多余的干扰因素，帮助宝宝集中注意力完成进食。同时可以适当调整喂养节奏，采用少量多餐的模式，不用严格卡固定的喂奶间隔，在宝宝表现出饥饿信号时再进行喂养，避免在宝宝没有进食意愿时强行安排喂奶。 日常可以适当增加宝宝白天的活动量，通过俯趴、互动、被动操等方式消耗体能，促进胃肠蠕动，自然唤起宝宝的饥饿感。同时定期检查宝宝的口腔状态，排除出牙不适、口腔炎症等可能影响进食的小问题，确认没有其他病理性干扰。 只要宝宝的精神状态、尿量、体重增长都维持在正常区间，短暂的奶量波动不会对健康造成伤害，随着宝宝的自然成长，厌奶期会平稳度过。如果宝宝拒奶超过72小时，或者出现精神萎靡、体重明显下降的情况，要及时前往医院儿科就诊，排除潜在的健康问题。","points":["如果宝宝拒奶超过72小时，或者出现精神萎靡、体重明显下降的情况，要及时前往医院儿科就诊，排除…","第一个核心表现，就是奶量出现无诱因的明显下降","只要宝宝的精神状态、尿量、体重增长都维持在正常区间，短暂的奶量波动不会对健康造成伤害，随着宝…"],"points_source":"extract","summary_source":"llm","title_zh":"宝宝有这3个表现，可能是进入厌奶期了","translated":true},{"title":"制售假冒母婴产品8人判刑！品牌方点赞检察护企，加码布局长沙","summary":"8名制售假冒母婴产品者被判刑，凸显了法律对母婴产品安全的保护力度。品牌方对此表示赞赏，并决定加大对长沙市场的投入。这一事件警示行业从业者，合规经营是市场立足的根本，同时长沙作为重要市场，将吸引更多优质品牌资源，促进市场健康发展。华声在线10月27日讯（全媒体记者 王智芳 通讯员 刘丽佳 赵一声）今日，记者从长沙县人民检察院获悉，该院办理一起假冒母婴产品注册商标案，一个生产、分销假冒纸尿裤、湿纸巾的犯罪团伙受到法律惩处。","source_id":"gnews_cn_baby_category","source_name":"华声在线","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://hunan.voc.com.cn/news/202610/34101233.html","published_at":"2026-10-27T21:07:07+08:00","published_guessed":false,"fetched_at":"2026-10-28T12:06:48+08:00","language":"zh","author":"","tags":["政策法规","品牌动态","跨境电商"],"priority":"P1","score":6.4,"matched":["母婴"],"id":"44fb9a978177ed52","title_zh":"制售假冒母婴产品8人判刑！品牌方点赞检察护企，加码布局长沙","summary_source":"llm","summary_kind":"brief","points":["8人制售假冒母婴产品被判刑","品牌方点赞检察护企","加码布局长沙市场"],"points_source":"llm","translated":true,"link_resolved":true,"body":"华声在线10月27日讯（全媒体记者 王智芳 通讯员 刘丽佳 赵一声）今日，记者从长沙县人民检察院获悉，该院办理一起假冒母婴产品注册商标案，一个生产、分销假冒纸尿裤、湿纸巾的犯罪团伙受到法律惩处。案件办结后，品牌方深受鼓舞，近期在长沙新增设立工作室，对当地知识产权保护环境充满信心。 杭州某实业股份有限公司旗下某品牌纸尿裤、儿童湿纸巾是国内母婴市场热销产品。张某甲、何某曾是该品牌合作经销商的员工，熟悉相关产品经销模式。 2024年2月，二人纠集张某乙等人，在未取得品牌授权的情况下私自生产假冒某品牌纸尿裤，以“尾货”名义向下游姚某等人销售，姚某等人再通过私域社交平台对外销售。 这批“尾货”投放市场后，销售人员陆续收到一些顾客的投诉和质疑。姚某无视反馈上来的消费者意见，明知货品系假冒注册商标的商品，仍继续对外销售，涉案金额23万余元。 2024年7月，该团伙又谋划生产假冒品牌湿纸巾，委托韩某、尹某加工近11万包，涉案金额41万余元。假冒产品流入市场，严重损害正品的品牌声誉。 长沙县检人民察院检察官王欧雯介绍，办案团队明确取证重点，引导公安机关固定商标权属材料、微信聊天记录、资金流水、发货凭证等关键证据，同步督促开展涉案财物审计，夯实案件办理的证据基础。 2026年2月，长沙县检人民察院对张某甲等8人依法提起公诉，8名被告人全部自愿认罪认罚。 最终，法院以假冒注册商标罪判处5名被告人有期徒刑二年六个月至一年不等，部分适用缓刑；以销售假冒注册商标的商品罪分别判处2名被告人有期徒刑十一个月、十个月；以非法制造、销售非法制造的注册商标标识罪判处1名被告人有期徒刑一年六个月，缓刑二年。 近日，检察官进行回访时，涉案品牌工作人员表示：“检察机关的有力举措，让我们看到了长沙鼓励品牌创新、保护知识产权的决心，我们最近又在长沙新设了一家工作室。”","image":"https://vod-benshipin-xhncloud.voc.com.cn/208/2026/10/27/952b42a0901d8a3b73bd9eff9ecf5768ca9ac7ca1793105926047.jpeg?pid=46553608"},{"title":"Bel Group overtakes Danone as top dairy company for methane emissions action","summary":"贝氏集团在甲烷排放行动方面超越达能，成为乳制品行业的领头羊。这一变化表明全球乳业对环境问题的重视程度提升，对从业者意味着需要关注并采取行动减少碳排放，以符合可持续发展要求。乳制品行业作为碳排放的重要领域，其领军企业的环保行动将带动行业整体向绿色低碳转型，从业者需积极应对环保要求，提升企业可持续发展能力。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/27/bel-group-overtakes-danone-as-top-dairy-company-for-methane-emissions-action","published_at":"2026-10-27T20:21:55+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:38:52+08:00","language":"en","author":"","tags":["政策法规","质量安全","海外动态"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/QTKHRSDXF5DO3OZUS6NXMPGYEI.jpg?auth=3c8310c9e14053e367f4d4e428b0ba4588064e779b56d5b66eb830cf1c1b0354&smart=true&width=2121&height=1414","score":9.6,"matched":["danone","dairy"],"id":"d8ffa400518e3b6d","title_zh":"贝氏集团超越达能成为乳制品行业甲烷排放行动的领头羊","summary_source":"llm","summary_kind":"brief","points":["成为甲烷排放行动领先者","环保和可持续发展成为行业议题"],"points_source":"llm","translated":true},{"title":"Bel Group overtakes Danone as top dairy company for methane emissions action","summary":"贝氏集团在甲烷排放行动方面超越达能，成为乳业在环保领域的领头羊。这一举措显示了乳制品行业对环境问题的重视，对从业者意味着需关注环保法规变化，并可能需要投入更多资源进行减排技术研发和实施。这一事件对行业具有警示作用，提示从业者需积极应对环保挑战，加强环保技术研发和投入，以适应日益严格的环保法规要求。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/27/bel-group-overtakes-danone-as-top-dairy-company-for-methane-emissions-action","published_at":"2026-10-27T20:21:55+08:00","published_guessed":false,"fetched_at":"2026-10-29T01:07:20+08:00","language":"en","author":"","tags":["品牌动态","政策法规","质量安全"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/QTKHRSDXF5DO3OZUS6NXMPGYEI.jpg?auth=3c8310c9e14053e367f4d4e428b0ba4588064e779b56d5b66eb830cf1c1b0354&smart=true&width=2121&height=1414","score":9.6,"matched":["danone","dairy"],"id":"04d152dbdf128e1e","title_zh":"贝氏集团超越达能成为乳业甲烷排放行动领头羊","summary_source":"llm","summary_kind":"brief","points":["贝氏集团超越达能","乳制品行业关注甲烷排放","环保成为行业重要议题","对跨境乳制品行业有影响"],"points_source":"llm","translated":true},{"title":"【深度】君乐宝与蜜雪集团战略合作升级高端鲜奶走进国民奶茶 - 瑞财经","summary":"君乐宝乳业集团与蜜雪集团签署全面深度战略合作协议，君乐宝旗下高端鲜奶悦鲜活将成为蜜雪集团鲜奶品类核心供应方。双方将在供应链共建、品牌联动、海外拓展等方面展开深度合作。这是继2024年12月双方合资建设“雪王牧场”之后，合作关系的进一步升级。君乐宝已搭建起完整奶业全产业链体系，低温液奶市场占有率在2025年登顶全国第一。蜜雪集团凭借规模领先的门店网络，直面数亿消费者，庞大市场催生对高品质乳制品的持续规模化需求。","source_id":"gnews_cn_brand_fin","source_name":"Google News·乳企财报与资本（中文）","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.rccaijing.com/news-7520781559235540038.html","published_at":"2026-10-27T17:40:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T09:20:05+08:00","language":"zh","author":"","tags":["品牌动态","供应链","跨境电商"],"priority":"P1","score":4.8,"matched":["君乐宝"],"id":"c9576373e11cf458","title_zh":"【深度】君乐宝与蜜雪集团战略合作升级高端鲜奶走进国民奶茶","summary_source":"llm","summary_kind":"brief","points":["君乐宝与蜜雪合作"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月27日，君乐宝乳业集团与蜜雪集团在石家庄签署全面深度战略合作协议，君乐宝旗下高端鲜奶悦鲜活将成为蜜雪集团鲜奶品类核心供应方，双方将在供应链共建、品牌联动、海外拓展等方面展开深度合作。这是继2024年12月双方合资建设“雪王牧场”之后，合作关系的进一步升级。 君乐宝乳业集团与蜜雪集团双方核心管理团队出席活动，蜜雪集团一行参观了君乐宝科学营养研究院、优致牧场及生产工厂，复盘过往合作成果，就长期发展开展座谈交流。 双方合作的基础源于产业能力的高度互补。君乐宝已搭建起完整奶业全产业链体系，截至2026年6月，拥有33座自营牧场、20座生产工厂，奶牛存栏19.8万头，约63%的奶源自给率居国内大型乳企首位，实现全链路自主可控；君乐宝低温液奶市场占有率在2025年登顶全国第一。君乐宝悦鲜活鲜奶2025年跻身中国鲜奶第一品牌，并先后落地中国香港、新加坡市场。 蜜雪集团凭借规模领先的门店网络，直面数亿消费者，庞大市场催生对高品质乳制品的持续规模化需求，同时可将终端消费需求反馈至上游，形成供需双向联动的基础。 “君乐宝的全产业链能力与蜜雪高质平价的产品理念高度契合，这是一次上下游的双向奔赴。”蜜雪集团方面表示，供需直连既释放上游鲜奶产业价值，也为大众茶饮市场带来更丰富的产品可能性。 悦鲜活是君乐宝旗下高端鲜奶品牌，通过中国优质乳工程特优级生乳原料认证，采用INF0.09秒超瞬时杀菌技术，最大程度保留鲜奶中的活性营养与自然鲜甜口感。 得益于双方前期奶源共建，安全优质的鲜奶高效直达终端，蜜雪覆盖全国的庞大门店网络，为君乐宝产品带来全新落地场景，打通家庭消费与茶饮商用两大场景，为低温鲜奶品类拓展全新增长空间。 本次战略合作框架下，君乐宝将扩大供应覆盖，规模化供给蜜雪冰城、幸运咖门店，高端鲜奶悦鲜活进一步渗透国民茶饮渠道。 在供应链合作之外，双方将推进多维度深度合作。研发层面，结合市场需求，聚焦高蛋白产品、冰淇淋原料、风味乳、奶盖、酸奶原料升级等开展联合创新，将乳业技术积淀转化为适配大众的消费产品；品牌端，挖掘联合传播机会，释放双向品牌势能。 “升级后的产品在奶味醇厚感和清爽度上均有明显提升，不少消费者反馈‘能喝得出鲜奶味’‘口感浓郁丝滑’。”蜜雪集团方面表示，鲜奶升级是蜜雪集团围绕“真鲜纯”产品理念、系统性推进全品类原料升级的组成部分，未来将依托君乐宝全产业链实力叠加蜜雪渠道网络，持续拓宽国产鲜奶大众消费市场；放眼海外，以东南亚为重点，探索乳品原料出海、本地化研发与冷链协同。 以本次签约为新起点，双方将探索乳业与茶饮产业合作新模式，释放全链条产业合力，推动高品质鲜奶走向更广市场，为广大消费者带来更多优质选择。","image":"https://ess.leju.com/common/photo/16-1-2U5n3TKJfHJwVtPpQp3lZXZAHZrUe9FCzX2JHsFZgBPDlSA9qY63rU0itRtZ7M3oRfb0LZFNYPkLAQ5j.png"},{"title":"Fonterra: power outages could threaten New Zealand’s $25 billion dairy exports - Dairynews.today","summary":"新西兰乳企Fonterra警告，因电力中断可能威胁该国价值25亿美元的乳制品出口。这一事件凸显了电力供应对奶业出口的潜在影响，对跨境乳制品行业从业者具有重要警示意义。电力稳定性是保障生产连续性和出口安全的关键因素，从业者需关注能源供应风险，制定应急预案。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://dairynews.today/global/news/fonterra_power_outages_could_threaten_new_zealand_s_25_billion_dairy_exports_6288896.html","published_at":"2026-10-27T08:32:06+08:00","published_guessed":false,"fetched_at":"2026-10-27T09:53:32+08:00","language":"en","author":"","tags":["海外动态","质量安全","供应链"],"priority":"P0","score":9.6,"matched":["dairy","fonterra"],"id":"45b35723d3b00c6d","title_zh":"新西兰 Fonterra：停电可能威胁25亿美元乳制品出口","summary_source":"llm","summary_kind":"brief","points":["电力中断威胁乳制品出口","新西兰乳企Fonterra警告","电力供应对奶业出口影响","能源供应风险与应急预案"],"points_source":"llm","translated":true,"image":"https://lh3.googleusercontent.com/J6_coFbogxhRI9iM864NL_liGXvsQp2AupsKei7z0cNNfDvGUmWUy20nuUhkREQyrpY4bEeIBuc=s0-w300-rw","link_resolved":true,"body":"Matt Bolger, Fonterra’s managing director of co-operative affairs, raised the concerns in the latest Mood of the Boardroom survey and corporate review. He described a change in the company’s energy concerns: attention had moved beyond sharp price increases and pressure on operating margins to whether sufficient energy would be available to keep factories running. Fresh milk cannot wait through an extended shutdown, particularly during the spring production peak. Fonterra warned that interruptions lasting several days would destroy product rather than simply postpone its manufacture. New Zealand’s energy system has experienced substantial price volatility alongside tightening supplies. During earlier dry periods, reduced water levels in hydroelectric reservoirs coincided with declining domestic gas output. Falling production from large offshore fields, including Pohokura, contributed to the gas contraction. Wholesale electricity prices rose above $800–900 per megawatt-hour in those conditions. Fonterra’s warning concerns both electricity transmission and generation constraints, as well as the reliability of commercial gas supplies. The co-operative has spent hundreds of millions of dollars replacing coal boilers at major production facilities with industrial electrode boilers and biomass equipment as part of compliance with national emissions-reduction requirements. Those investments reduced its direct emissions. However, the shift towards electric processing equipment has also increased its dependence on a grid facing capacity limitations when demand peaks. Fonterra identified that dependence as a growing operational exposure as its manufacturing sites move away from coal. Bolger said markets with tariffs below 10% account for only about 14% of worldwide dairy consumption accessible to New Zealand exporters on those terms. Against that restricted market access, he stressed the importance of dependable deliveries and meeting customer contracts in Asia, the Americas and the Middle East. Fonterra warned that factory stoppages prompting declarations of force majeure could lead customers to turn to European or American suppliers. It also warned that such disruption could weaken the premiums associated with New Zealand dairy products, built up over decades. Dairy exports earned approximately $25 billion in the 2026 financial year."},{"title":"Fonterra Warns Energy Outages Could Threaten Dairy Processing - en.edairynews.com","summary":"恒天然公司在新西兰奶源新闻网站上发布警告，称能源中断可能对乳制品加工构成威胁。这一事件凸显了能源供应对乳制品行业的依赖性，对依赖稳定电力进行生产加工的从业者而言，能源安全成为影响生产稳定性的关键因素。乳制品加工需要大量电力支持，如挤奶、发酵、包装等环节，任何能源供应的中断都可能造成生产停滞，影响产品质量和供应稳定性。对于跨境乳制品行业从业者来说，关注能源供应的稳定性，并制定应急预案，是保障供应链安全的重要措施之一。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://en.edairynews.com/fonterra-warns-energy-outages-could-threaten-dairy-processing/","published_at":"2026-10-27T06:31:25+08:00","published_guessed":false,"fetched_at":"2026-10-27T09:53:32+08:00","language":"en","author":"","tags":["质量安全","供应链","海外动态"],"priority":"P0","score":9.6,"matched":["dairy","fonterra"],"id":"bbc7c9ea5199dd6c","title_zh":"恒天然警告能源中断可能威胁乳制品加工","summary_source":"llm","summary_kind":"brief","points":["能源中断威胁乳制品加工","依赖稳定电力生产加工","影响产品质量和供应稳定性","需制定应急预案保障供应链安全"],"points_source":"llm","translated":true,"image":"https://lh3.googleusercontent.com/J6_coFbogxhRI9iM864NL_liGXvsQp2AupsKei7z0cNNfDvGUmWUy20nuUhkREQyrpY4bEeIBuc=s0-w300-rw","link_resolved":true,"body":"The vulnerability comes after years of extreme price swings and structural tightening across New Zealand’s energy complex. In previous dry-year scenarios, when hydro storage lake levels fell and domestic natural gas production contracted—accelerated by the sustained decline of major offshore fields like Pohokura—wholesale power prices spiked past $800 to $900 per megawatt-hour. However, the operational risks have become more acute due to the dairy sector’s rapid progress in decarbonization. In compliance with national emissions reduction mandates, Fonterra has invested hundreds of millions of dollars replacing legacy coal-fired boilers across key manufacturing sites with large-scale industrial electrode boilers and biomass systems. While this capital expenditure significantly lowered the cooperative’s direct emissions profile, it concentrated processing operations into heavy reliance on a national transmission and electrical generation grid that faces capacity constraints during peak demand windows. From an international trade and commercial competitiveness perspective, processing disruptions present severe market risks because New Zealand operates within a narrow global access framework. Bolger noted that New Zealand exporters currently enjoy low-tariff access (below 10 percent) to only approximately 14 percent of total global dairy consumption. When trade barriers and protective tariffs limit market entry, international competitiveness depends on uncompromised supply-chain dependability, just-in-time delivery, and strict adherence to commercial customer contracts across Asia, the Americas, and the Middle East. If processing shutdowns or power cuts force supply force majeure declarations, international buyers will seek alternative suppliers in Europe or the United States, eroding brand premiums that New Zealand dairy has spent decades establishing. From an enterprise finance and macroeconomic perspective, the stakes extend far beyond the cooperative’s immediate corporate balance sheet. In fiscal year 2026, dairy export earnings generated roughly $25 billion, with approximately $19.6 billion flowing directly back into the domestic economy through farmgate milk payments, transport networks, rural services, and regional wages—representing nearly 78 cents of every export dollar earned."},{"title":"韩国大米无机砷含量远低于法定标准确保辅食安全","summary":"韩国大米无机砷含量远低于法定标准，为婴幼儿辅食安全提供了有力保障。这一发现对跨境母婴行业具有重要意义，意味着来自韩国的婴幼儿食品具有更高的安全标准，有助于提升消费者信心，增强市场竞争力。对从业者而言，选择符合高标准的进口原料是保障产品安全、赢得市场信任的关键。","source_id":"gnews_cn_baby_category","source_name":"www.famtimes.co.kr","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.famtimes.co.kr/zh/news/articleView.html?idxno=703480","published_at":"2026-10-27T06:21:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T12:06:48+08:00","language":"zh","author":"","tags":["质量安全","市场数据","跨境电商"],"priority":"P1","score":6.4,"matched":["辅食"],"id":"93922ea95db2cadb","title_zh":"韩国大米无机砷含量远低于法定标准确保辅食安全","summary_source":"llm","summary_kind":"brief","points":["韩国大米无机砷含量低于法定标准","确保婴幼儿辅食安全"],"points_source":"llm","translated":true,"link_resolved":true},{"title":"Technology underpins Dutch dairy farm productivity","summary":"荷兰200公顷家庭牧场通过科技手段提升奶牛生产效率，GPS系统确保草地利用率提高10-15%，SmartTag和SmartSight技术帮助监控牛群健康，减少人工干预。荷兰乳农的实践表明，科技是提高奶牛健康和生产效率的关键，对跨境乳制品行业从业者启示是，技术应用能显著提升生产力和产品质量。","source_id":"farmersweekly_nz","source_name":"Farmers Weekly NZ·乳业","source_url":"https://www.farmersweekly.co.nz/tag/dairy/feed/","original_url":"https://www.farmersweekly.co.nz/meeting-the-markets/europe-tracking-tomorrows-food-trends/technology-underpins-dutch-dairy-farm-productivity","published_at":"2026-10-27T05:24:51+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:39:41+08:00","language":"en","author":"Neal Wallace","tags":["质量安全","海外动态"],"priority":"P0","score":12.7,"matched":["dairy","milk production","dairy farm"],"id":"ab46a35dd90c4154","title_zh":"荷兰牧场应用科技提升效率","summary_source":"llm","summary_kind":"brief","points":["科技提升牧场管理效率","平衡奶牛产量与寿命","智能化管理应用广泛","注重奶牛福利与产量平衡"],"points_source":"llm","translated":true,"body":"It is the finer details that really matter to Mathijs Meiser and his partner Florien Bleijenberg. They, along with Meiser’s parents Bennie and Elly, run a 200 hectare family dairy farm in northwestern Netherlands, milking 350 cows three times a day all year round. Last year the herd produced 4 million litres or 11,500kg/milk/cow with 4.5% fat and 3.5% protein. Their motivation is to be as efficient as possible. “We don’t want any losses, anywhere,” Meiser said. The cows are in milk for 328 days. He is confident production could reach 12,000 to 13,000kg/milk/cow, but that would shorten their lives and require higher replacement rates. Cows first calve at 21 months of age, four months earlier than the national average. In her lifetime, Meiser said, a cow will produce 64,000kg/milk, nearly double the Netherlands average of 36,000kg/milk. Technology is essential to keep cows healthy and production high. For example, a GPS system in the farm’s tractor ensures it follows the same tramlines every time it enters a paddock, harvesting grass or making silage. By following the same wheel tracks, pasture yield is 10-15% higher. Using Nedap’s SmartTag collars and SmartSight camera monitoring for lameness, provides peace of mind with a large herd. “We can’t always be in the barn, so it tells us when there is a sick cow or something we need to look at,” Meiser said. Previously he would trim the feet of his whole herd twice a year, but SmartSight technology means he focuses only on those that need it. He said he can make money at the current milk price of NZ92 cents per litre.","image":"https://www.farmersweekly.co.nz/wp-content/uploads/2026/10/Meiser1-scaled.jpg"},{"title":"Synlait’s Longest-Serving Employee Joins Executive Team - Rural News Group","summary":"新西兰Synlait乳业任命服务近18年的员工David Williams为乳品供应与可持续发展总经理，负责两大商业牧场、近200位奶农供应商及可持续发展工作。Williams自2008年加入时公司尚在起步阶段，如今公司经历财务波动，得益于股东Bright Dairy和A2 Milk的再投资及业务重心转移，已实现盈利。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.ruralnewsgroup.co.nz/dairy-news/dairy-general-news/synlait-david-williams-general-manager-milk-supply-sustainability","published_at":"2026-10-27T04:55:55+08:00","published_guessed":false,"fetched_at":"2026-10-27T05:45:29+08:00","language":"en","author":"","tags":["品牌动态","质量安全","供应链"],"priority":"P0","score":4.8,"matched":["synlait"],"id":"2bebd9b763655375","title_zh":"Synlait公司资深员工加入高管团队","summary_source":"llm","summary_kind":"brief","points":["Synlait任命任职时间最长的员工加入高管团队","乳业企业高管变动可能影响供应链运营策略","新西兰乳企人事调整是行业关注焦点"],"points_source":"llm","translated":true,"link_resolved":true,"body":"David Williams has been appointed general manager of milk supply and sustainability, in charge of the team of 28 people which runs Synlait’s two commercial dairy farms, supports its nearly 200 farmer suppliers and leads its sustainability workstreams. Williams jointed Synlait in March 2008 when the Dunsandel company was primarily a dairy farm owner and its first processing plant was still under construction. At that time, he explains, the company had nine dairy farms, was in the process of converting another six for the following season, and the company’s Dunsandel plant was still being kitted out with the first drier due to come online in August 2008. In the 2008-09 season it began processing milk from 60 farms, its own 15 plus another 45 contracted suppliers. “My role back then was everything to do with milk supply. I was it,” he told Dairy News . “Everything to do with all the relationships with farmers and contracting the milk, and all of the aspects relating to milk quality and RMP [Risk Management Programme] and sustainability, and all of the milk collection. “So, I started in March 2008, and there was quite a lot to do before August.” Williams’ elevation to the executive this year comes as the company is coming out of a difficult period, having reported a net loss after tax of $75.4 million for the year to July 31 2026 – but that includes a sharp turnaround of a net loss of $80.6 million for the first half of the financial year, then a net profit of $5.2 million in the second half. Williams says the company’s recent problems have been met by reinvestment by shareholders Bright Dairy and A2 Milk, and by refocusing operations on the Dunsandel plant, with all suppliers now in Canterbury. Williams says Synlait has had its ups and downs, but he has stayed through the tough times because he likes the company, what it stands for, and that it has always attracted “really good people who just want to get on with things”. He adds he also enjoys working with the farmer suppliers, who have also shown their loyalty to the company. “Most of the ones that started in 2008 are still there as well.”","image":"https://www.ruralnewsgroup.co.nz/media/k2/items/cache/6af28f1687854deb8f43f934973b2845_XL.jpg"},{"title":"蒙牛、东鹏饮料声明：终止与姆巴佩全部合作","summary":"东鹏饮料集团与蒙牛乳业于10月27日联合宣布终止与法国足球运动员姆巴佩的所有合作。此举涉及品牌营销与体育赞助领域，对相关企业的品牌形象及市场策略产生直接影响。对于跨境母婴与婴幼儿奶粉行业的从业者而言，需关注品牌与明星合作的风险管理及合规性，此类事件可能引发消费者对产品安全及品牌价值观的审视。","source_id":"jiemian","source_name":"界面新闻","source_url":"https://www.jiemian.com/","original_url":"https://www.jiemian.com/article/15246149.html","published_at":"2026-10-27T00:00:00+08:00","published_guessed":true,"fetched_at":"2026-10-27T11:28:09+08:00","language":"zh","author":"","tags":["品牌动态","政策法规","跨境电商"],"priority":"P1","score":4.8,"matched":["蒙牛"],"id":"4b9e58b63c0ee289","image":"https://img.jiemian.com/101/original/20261027/52e1e8631086f6917de70fb0db952ffe.png","summary_source":"llm","title_zh":"蒙牛、东鹏饮料声明：终止与姆巴佩全部合作","summary_kind":"brief","points":["终止姆巴佩所有合作","涉及品牌营销与体育赞助","影响品牌形象与市场策略"],"points_source":"llm","translated":true},{"title":"蒙牛：终止与基利安·姆巴佩合作","summary":"蒙牛乳业于10月27日发布声明，宣布终止与法国足球运动员姆巴佩的合作关系。该事件反映出企业在品牌代言选择上的谨慎态度，尤其关注代言人可能引发的社会争议。对于行业从业者，需认识到品牌合作需兼顾市场反响与风险控制，避免潜在的品牌危机。体育明星合作虽能提升关注度，但也可能因个人行为影响品牌声誉。","source_id":"jiemian","source_name":"界面新闻","source_url":"https://www.jiemian.com/","original_url":"https://www.jiemian.com/article/15246105.html","published_at":"2026-10-27T00:00:00+08:00","published_guessed":true,"fetched_at":"2026-10-27T11:28:09+08:00","language":"zh","author":"","tags":["品牌动态","政策法规","质量安全"],"priority":"P1","score":4.8,"matched":["蒙牛"],"id":"24e3fc4acd70e3f6","image":"https://img.jiemian.com/101/original/20261027/1284197b057ab4562cd62568c4f5a48d.png","title_zh":"蒙牛：终止与基利安·姆巴佩合作","summary_source":"llm","summary_kind":"brief","points":["关注品牌代言风险","避免潜在品牌危机"],"points_source":"llm","translated":true},{"title":"选奶粉只看价格和产地？新手爸妈更该关注这几点","summary":"在选择奶粉时，新手爸妈不应仅关注价格和产地，而应更加关注配方、注册信息、可追溯性等指标。新国标的实施提升了国产奶粉的整体品质，家长应通过查看注册信息、配方和可追溯性来选择合适的奶粉。国奶养育工程等项目也为家庭提供了补贴，减轻了养育负担。对于从业者而言，应加强消费者教育，引导家长理性选择奶粉，提升品牌信誉和消费者满意度。在新国标实施、国产奶粉整体品质提升的背景下，这套判断标准或许需要更新了。","source_id":"qinbei","source_name":"亲贝网","source_url":"https://www.qinbei.com/","original_url":"https://www.qinbei.com/6/20261027/1869531.shtml","published_at":"2026-10-27T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-27T16:49:30+08:00","language":"zh","author":"","tags":["政策法规","质量安全","跨境电商"],"priority":"P1","score":9.6,"matched":["奶粉","价格"],"id":"0d6287f632a0d705","body":"给宝宝选奶粉，是很多新手爸妈最纠结的事之一。货架上一罐奶粉的价格从一百多元到四五百元不等，\"越贵越好\"\"进口更放心\"的说法也一直流传。但价格和产地真的能等同于品质吗?在新国标实施、国产奶粉整体品质提升的背景下，这套判断标准或许需要更新了。 先看价格。一罐奶粉的终端售价，包含原料成本、生产加工、品牌营销、渠道流通等多个环节。也就是说，价格高低并不直接等于配方优劣或品质高低，其中相当一部分是品牌溢价和渠道成本。理解这一点，才能理性看待市面上从一百多到四五百元不等的价格区间。 再看产地。近年来，国产婴幼儿配方奶粉在配方研发和质量管理上持续投入。2021年，国家卫生健康委发布婴幼儿配方食品系列新国家标准(GB 10765-2021、GB 10766-2021、GB 10767-2021)，对蛋白质、脂肪、碳水化合物、维生素和矿物质等营养素指标作出了更严格的规定。能否通过新国标注册，已经成为衡量一款配方奶粉是否合规、配方是否科学的重要门槛。新国标的实施，也被业内视为国产奶粉行业的一次重要洗牌。 那么，家长选奶时可以关注哪些更实在的指标?第一，看注册信息。正规的婴幼儿配方乳粉都会标注\"国食注字\"编号，这是国家市场监管总局的注册批号，可在官网查询核实。第二，看配方与适用月龄，选择符合宝宝月龄段的产品。第三，看可追溯性，罐底通常印有追溯码，扫码可以查看生产批次、质检报告等信息。 把这些标准放到一个具体的公益项目上看，会更直观。由北京联慈健康公益基金会主办的\"国奶养育工程\"，已运行五年，直接受益群众达数百万人，累计减轻养育负担数十亿元，得到国家四部委发文支持，方向与《国民营养计划(2017-2030年)》《\"健康中国2030\"规划纲要》及优化生育政策一致。 项目覆盖的品牌包括人之初爱嘉贝比、贝因美恬乐宝、鸣翠安旭贝儿、明一美慧宝、向阳湖、贝诗慧等，均为新国标注册产品。这些奶粉与市售产品同品牌、同配方、同生产线，品质标准完全一致。换句话说，补贴降低的是家庭的购买价格，而不是产品的品质标准。 项目采用双轨制运作：公益资助轨道面向所有有需求的0-3岁婴幼儿家庭，以远低于市场价的方式提供新国标国产配方奶粉;慈善捐赠轨道则为特定困难家庭免费捐赠优质国产奶粉。核心政策是：0-3岁婴幼儿家庭不限户籍、不查收入、不限几胎，每月可申领6罐，补贴后每罐98元。国奶补贴与育儿补贴互不影响，可同时领取。 在验证环节，家长可以自己动手核实：一看罐身的\"国食注字\"编号，二扫罐底的追溯码，三到国家市场监管总局官网输入编号查询。这套可查验的机制，让每一罐奶粉都有据可查。 目前，项目已在海南、四川、山西、广东、江苏、福建、铜仁、达州、广西、湖南等多地推进，各地卫健委均有发文支持。以广东南雄为例，项目2021年5月启动，截至2025年已覆盖数千个婴幼儿家庭，捐赠和资助奶粉折合资金上千万元，从侧面印证了项目在基层的落地能力。 对关注奶粉品质和价格的家长来说，比起在价格和产地上反复纠结，学会看注册信息、看配方、看可追溯性，才是更靠谱的选奶方式。","points":["不应仅关注价格和产地","应关注配方、注册信息、可追溯性","新国标提升了国产奶粉品质","国奶养育工程减轻了养育负担"],"points_source":"llm","summary_source":"llm","title_zh":"选奶粉只看价格和产地？新手爸妈更该关注这几点","translated":true},{"title":"Why dairy drinks are well placed to capitalise on the benefit stacking trend","summary":"乳制品饮料行业正迎来利益叠加趋势，这一趋势为乳制品饮料提供了良好的发展机遇。利益叠加指的是产品同时具备多种健康或功能性卖点，满足消费者多元化需求。这一趋势对乳制品饮料行业从业者具有重要意义，意味着需要不断创新产品，提升健康价值，以满足市场变化。乳制品饮料因其天然的营养成分，在健康趋势中具有天然优势，适合利用利益叠加策略进行市场推广。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/26/why-dairy-drinks-are-well-placed-to-capitalise-on-the-benefit-stacking-trend","published_at":"2026-10-26T23:04:46+08:00","published_guessed":false,"fetched_at":"2026-10-26T23:14:58+08:00","language":"en","author":"","tags":["行业动态"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/FWDOXRFOXBCR5GRAEOEJZZDYDQ.jpg?auth=7b19defc7a9bafb97836e9a64c45007aa5c70d3ead53c6240a0810c0aa5ca698&smart=true&width=2121&height=1414","score":4.8,"matched":["dairy"],"id":"46e14d9411949dab","title_zh":"乳制品饮料在利益叠加趋势中占据优势","summary_source":"llm","summary_kind":"brief","translated":true},{"title":"Global Milk Supply Tests Iowa Dairy Expansion - Dairynews.today","summary":"全球牛奶供应情况正在测试爱荷华州奶牛场的扩张计划。这一动态反映了全球乳制品供应链的调整和优化。对跨境母婴行业从业者而言，这意味着需关注全球奶源供应变化，评估其对原料采购成本和稳定性的影响。爱荷华州作为美国重要奶牛养殖区，其扩张可能影响全球乳制品市场格局，进而影响婴幼儿奶粉原料的供应情况。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://dairynews.today/news/global_milk_supply_tests_iowa_dairy_expansion_5397558.html","published_at":"2026-10-26T20:04:06+08:00","published_guessed":false,"fetched_at":"2026-10-26T22:39:54+08:00","language":"en","author":"","tags":["供应链","海外动态"],"priority":"P0","score":11.2,"matched":["dairy","milk supply"],"id":"57895078b88b73dc","title_zh":"全球牛奶供应测试爱荷华州奶牛场扩张","summary_source":"llm","summary_kind":"brief","points":["全球牛奶供应测试爱荷华州奶牛场扩张","反映全球乳制品供应链调整","对原料采购成本有影响","需关注奶源供应变化"],"points_source":"llm","translated":true,"link_resolved":true,"body":"An analysis in the Ornua Global Dairy Market Report says worldwide milk output is expected to increase by 2.2% in 2026, before settling at about 1.0% growth in 2027. Production in major exporting regions has continued to replenish global commodity inventories despite drought in parts of Northern Europe earlier in the season. US milk production was up 1.7% through late summer, supported by higher milk-solids output and continued investment at farm level. New Zealand recorded a 2.4% increase in volume and a 3.4% rise in total solids. South American production also advanced, with Uruguay’s milk deliveries 12% higher year to date. The report describes commodity prices as facing pressure from weaker international import demand, cautious domestic consumers and wider inflationary conditions. Spot skimmed-milk-powder and wholesale-cheese prices were seasonally steady in early autumn, but the analysis said a major rally before the fourth quarter would be unlikely. Join the 2nd MENA Dairy Congress on January 24–25 in Al Ain, UAE — a key meeting point for dairy industry leaders, producers, investors, experts, and technology providers from across the MENA region and beyond. Discover new market opportunities, exchange expertise, build valuable business connections, and discuss the future of the dairy industry in one of the region’s most dynamic markets. Register here: https://menadc.dairynews.today Iowa now ranks among the ten largest US dairy-producing states, with a milking herd of roughly 245,000 cows. At the same time, more than $13bn in new investment has been committed across the US dairy-processing sector. Modern cheese facilities, particularly in the Upper Midwest, are expanding the region’s ability to process additional local milk even as export demand softens. Farm operators are balancing income from beef-on-dairy calves against the need to maintain future milking capacity. Strong feeder-cattle prices have encouraged the use of beef genetics in commercial dairy herds, generating additional receipts from day-old crossbred calves. The report says that prolonged emphasis on terminal beef crosses has contributed to historically low national inventories of dairy replacement heifers. Limited availability and higher purchase costs have made decisions on crossbreeding rates and female retention more consequential for herd management."},{"title":"beef on dairy breeding | Global milk supply surge tests Iowa dairy expansion","summary":"全球乳制品供应增长对爱荷华州乳业扩张构成考验。国际进口需求疲软、国内消费价格敏感及宏观经济通胀导致大宗商品价格承压。爱荷华州作为美国十大乳制品生产州之一，面临全球贸易逆风与区域加工投资增长的交织。乳制品行业从业者需关注国际市场动态与国内政策导向，以应对价格波动和供应链变化带来的挑战。","source_id":"gnews_en_nz_dairy","source_name":"https://en.edairynews.com/","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://en.edairynews.com/global-milk-supply-surge-tests-iowa-dairy-expansion/","published_at":"2026-10-26T19:35:25+08:00","published_guessed":false,"fetched_at":"2026-10-28T22:45:50+08:00","language":"en","author":"","tags":["政策法规","市场数据","质量安全"],"priority":"P0","score":11.2,"matched":["dairy","milk supply"],"id":"590cd97f72de710e","title_zh":"全球牛奶供应激增考验爱荷华州乳业扩张","summary_source":"llm","summary_kind":"brief","points":["全球牛奶供应激增","爱荷华州乳业扩张考验"],"points_source":"llm","translated":true,"link_resolved":true,"body":"While physical availability expands, global commodity pricing faces sustained headwinds from cooling international import demand, domestic consumer price sensitivity, and broad macroeconomic inflation. Although spot skim milk powder and wholesale cheese values demonstrated seasonal stability through early autumn, substantial price rallies heading into the fourth quarter remain unlikely. For Iowa—which has ascended into the ranks of the top ten dairy-producing states with a milking herd of approximately 245, 000 cows—global trade headwinds intersect with massive regional processing investments. Over $13 billion in new capital commitments across the wider United States dairy processing landscape, particularly in modern cheese plants across the Upper Midwest, provides a critical regional buffer that can absorb expanding local liquid milk pools even as global export off-take slows. From an animal science and herd genetics standpoint, commercial farm operators face complex management tradeoffs between short-term livestock revenues and replacement pipeline security. Continued strength in feeder cattle prices has driven extensive adoption of beef-on-dairy crossbreeding programs across commercial herds, delivering lucrative supplemental cash receipts for day-old crossbred calves. However, prolonged prioritization of terminal beef crosses has caused national dairy replacement heifer inventories to contract to historic lows. With dairy heifer availability severely constrained and replacement purchase costs elevated, farm managers must carefully balance terminal crossbreeding ratios against female herd retention needs to maintain milking string capacity and avoid involuntary herd liquidation. From an enterprise finance and operational budgeting perspective, managing farmgate margins requires shifting operational focus from gross liquid volume toward milk component density. Under Federal Milk Marketing Order multiple component pricing formulas, butterfat and protein yield dictates the vast majority of gross farm income, with regional cheese vats paying substantial premiums for high-solids milk. While moderating corn and soybean meal prices provide welcome ration-cost relief, non-feed operating expenditures—including diesel fuel, agricultural machinery maintenance, labor wages, and bulk milk hauling assessments—remain elevated.","image":"https://en.edairynews.com/wp-content/uploads/2026/10/Global-milk-supply-surge-tests-Iowa-dairy-expansion.jpg"},{"title":"Nestle making progress in North America","summary":"雀巢在美国和加拿大的业务正在加速发展。这一进展表明雀巢在北美市场的竞争力正在增强，对行业从业者意味着需要关注北美市场的动态，了解竞争对手的策略，以制定有效的市场进入和扩张计划。北美市场对乳制品行业的重要性日益凸显，企业需要加强市场调研，把握市场机遇。","source_id":"foodbusinessnews","source_name":"Food Business News","source_url":"https://www.foodbusinessnews.net/rss/articles","original_url":"https://www.foodbusinessnews.net/articles/31239-nestle-making-progress-in-north-america","published_at":"2026-10-26T19:24:02+08:00","published_guessed":false,"fetched_at":"2026-10-26T23:14:59+08:00","language":"en","author":"","tags":["市场数据","跨境电商","海外动态"],"priority":"P1","image":"https://www.foodbusinessnews.net/ext/resources/2026/07/29/AdobeStock_1765775810_Editorial_Use_Only.webp?t=1785328009","score":4.8,"matched":["nestle"],"id":"7ef9da1e7ae288bb","title_zh":"雀巢在北美取得进展","summary_source":"llm","summary_kind":"brief","points":["北美市场业务加速","市场进入和扩张计划"],"points_source":"llm","translated":true},{"title":"纸尿裤风波中“躺赢” 帮宝适最新季度在中国销售额涨50%","summary":"在纸尿裤市场风波中，帮宝适凭借其品牌优势，最新季度在中国市场销售额逆势上涨50%。这一成绩反映出品牌实力对市场变化的应对能力，对母婴行业从业者启示是，品牌建设与市场策略是企业应对风险的关键。","source_id":"gnews_cn_baby_category","source_name":"每日经济新闻","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.nbd.com.cn/articles/2026-10-26/4617677.html","published_at":"2026-10-26T18:08:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T12:06:48+08:00","language":"zh","author":"","tags":["品牌动态","政策法规","跨境电商"],"priority":"P1","score":12.8,"matched":["纸尿裤","帮宝适","销售额"],"id":"a042cc945bacd464","title_zh":"纸尿裤风波中“躺赢” 帮宝适最新季度在中国销售额涨50%","summary_source":"llm","summary_kind":"brief","points":["帮宝适中国区销售额涨50%"],"points_source":"llm","translated":true,"link_resolved":true,"body":"如需转载请与《每日经济新闻》报社联系。 未经《每日经济新闻》报社授权，严禁转载或镜像，违者必究。 特别提醒 ：如果我们使用了您的图片，请作者与 本站联系 索取稿酬。如您不希望作品出现在本站，可联系我们要求撤下您的作品。 广告热线 北京: 010-57613265， 上海: 021-61283008， 广州: 020-84201861， 深圳: 0755-83520159， 成都: 028-86512112 互联网新闻信息服务许可证：51120190017 网站备案号：蜀ICP备19004508号-3 川公网安备 51019002002026号 新闻职业道德监督热线：400 889 0008 邮箱：zbb@nbd.com.cn","image":"https://static.nbd.com.cn/images/nbd_v5/item.png"},{"title":"Across the Nutraverse: Omega-3 supply chains, Nestlé’s healthy longevity play, and SAMe in EU","summary":"秘鲁因鱼类资源减少和气候影响取消2026年第二季度沙丁鱼捕捞季，导致全球鱼油供应紧张，成本上升，尤其在中国需求激增的背景下。这一事件凸显了Omega-3供应链的脆弱性，对婴幼儿奶粉行业影响显著，提醒从业者需关注原料供应稳定性，探索替代来源或加强供应链风险管理。","source_id":"nutraingredients","source_name":"NutraIngredients","source_url":"https://www.nutraingredients.com/arc/outboundfeeds/rss/","original_url":"https://www.nutraingredients.com/Article/2026/10/26/this-weeks-nutraverse-omega-3-supply-chains-nestles-healthy-longevity-play-and-same-in-eu","published_at":"2026-10-26T17:14:20+08:00","published_guessed":false,"fetched_at":"2026-10-26T17:56:38+08:00","language":"en","author":"Stephen Daniells","tags":["供应链","品牌动态","海外动态"],"priority":"P1","image":"https://www.nutraingredients.com/resizer/v2/SPNNRNIXT5BN7BKJF3BNNUDS7Y.png?auth=2aa94a8506bd2468fea0803e8f61cbb187a76c463477a5290cb66d9963f4edb0&smart=true&width=824&height=465","score":4.8,"matched":["nestlé"],"id":"98f6d203b6c38fd0","title_zh":"营养宇宙：Omega-3供应链、雀巢健康长寿战略及欧盟SAMe","summary_source":"llm","summary_kind":"brief","points":["秘鲁沙丁鱼捕捞季取消","全球鱼油供应紧张","中国Omega-3需求激增","供应链风险管理重要性"],"points_source":"llm","translated":true,"body":"Peru has cancelled its second 2026 anchovy fishing season after scientific assessments by the Peruvian Marine Institute (IMARPE) found declining biomass, an unusually high proportion of juvenile fish, and warm-water conditions associated with El Niño. IMARPE estimated a biomass of approximately 5.12 million tons—27.9% lower than that recorded in the summer of 2026 and 22.8% lower than the average winter-spring period since 1996. In addition, juvenile specimens represent a significant proportion of the biomass—79% by number and 65% by weight—plus reproductive activity is lower than normal, although spawning episodes indicate that the anchovy is making an effort to reproduce. “This decision is based on scientific evidence and our responsibility to protect the anchovy,” said Jesús Barrientos, vice minister of fisheries and aquaculture. “The high number of juveniles and current sea conditions require us to act prudently to preserve the resource’s capacity for renewal. We cannot make decisions thinking only about the short term; we must also safeguard fishing opportunities for the coming years,” Why it matters : Peru is a critical source of fish oil, and reduced anchovy harvests will tighten supply and increase raw material costs. The news event underscores growing climate-related risks to marine ingredient supply chains and the need to accelerate alternative omega-3 sources such as algae oils and fermentation-derived lipids. Demand for fish oil and omega-3s is increasing, with increased pressure on the supply chain coming from China. A new report from the China Chamber of Commerce for Import & Export of Medicines and Health Products found that fish oil was the fastest-growing dietary supplement import category in China during the first half of 2026. Fish oil imports increased more than 60% year-over-year to approximately US$384 million. Growth was driven largely by imports from Peru, which increased nearly 183%, while fish oil also posted strong growth on Chinese e-commerce platforms. “The most striking change came from Peru, where the value of imports surged from US$62m in the first half of 2025 to US$175m — a year-on-year increase of 182.80%,” the report wrote."},{"title":"忽然一周｜孩子王旗下丝域美国门店已试营业；盛夏光年完成近5000万A轮融资；雅培分拆全球营养品业务；雀巢、润本、jELLYCAT发布最新财报 - 母婴行业观察","summary":"孩子王旗下丝域美国门店试营业，拓展跨境渠道；盛夏光年获近5000万A轮融资，推动行业发展；雅培分拆全球营养品业务，聚焦核心市场；雀巢、润本、jELLYCAT发布财报，反映市场动态。对从业者意味着，跨境渠道拓展和融资环境改善带来机遇，需关注品牌战略调整和市场表现，把握行业发展趋势。","source_id":"gnews_cn_policy","source_name":"Google News·配方注册与监管（中文）","source_url":"https://news.google.com/rss/search?q=%E5%A9%B4%E5%B9%BC%E5%84%BF%E9%85%8D%E6%96%B9%E4%B9%B3%E7%B2%89%20(%E6%B3%A8%E5%86%8C%20OR%20%E5%9B%BD%E6%A0%87%20OR%20%E6%96%B0%E8%A7%84%20OR%20%E7%9B%91%E7%AE%A1%20OR%20%E6%8A%BD%E6%A3%80)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"http://www.myguancha.com/post/27881.html","published_at":"2026-10-26T11:22:00+08:00","published_guessed":false,"fetched_at":"2026-10-26T13:19:00+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P0","score":19.2,"matched":["雀巢","雅培","母婴","财报","融资"],"id":"cc3043adb5f61746","title_zh":"孩子王旗下丝域美国门店已试营业；盛夏光年完成近5000万A轮融资；雅培分拆全球营养品业务；雀巢、润本、jELLYCAT发布最新财报","summary_source":"llm","points":["丝域美国门店试营业","盛夏光年获近5000万A轮融资","雅培分拆全球营养品业务","雀巢等发布财报显示市场动态"],"points_source":"llm","translated":true,"link_resolved":true,"body":"本周，母婴行业业务重构与场景细分同步提速，存量竞争下的战略调整更聚焦专业能力与细分市场。 资本与品牌层面，雅培分拆全球营养品业务，多个品牌将进入独立平台；美赞臣中国以系统化方案重构儿童营养品类逻辑。渠道端，双11母婴竞争升温，定制纸尿裤、全龄营养等细分新品密集落地，品牌场景化布局持续加码。 数据与政策层面，乳制品线下延续下行，雀巢大中华区逆势保持增长；政策端，工信部启动消费名品征集，妇幼产品获重点支持，细分品类迎来政策利好。 10月16日，国家市场监督管理总局食品审评中心发布新一批的婴幼儿配方乳粉产品配方注册批件（决定书）邮寄信息，涉及美力源乳业的9款产品。 10月12日、13日，国家市场监督管理总局食品审评中心发布新一批的特殊医学用途配方食品批件（决定书）邮寄信息，涉及冬泽特医、辰欣药业等企业共17款产品。其中有一款婴儿特医食品。 母观说：批件的流向，就是企业战略重心的流向。婴配粉赛道在收缩，特医在扩容，这个趋势已经很清楚了。更值得关注的是国产特医的占比在持续提升，尤其是婴儿特医食品，这个领域过去长期被外资把持，国产每拿下一款批件，都是在啃硬骨头。门槛高、周期长，能持续拿到批件的企业，说明研发投入是真金白银砸进去了，一旦跑通，壁垒也远比婴配粉高。 10月21日，全球营养健康与医疗巨头雅培官宣了一个大动作：将全球营养品业务拆分为一家独立的上市公司。雅培在营养健康领域已有不错的积累，旗下已有Similac（婴配粉品牌）、PediaSure（儿童营养补充剂品牌）、Ensure等全球知名品牌。雅培多年老将Daniel Salvadori将出任新公司的首席执行官。 母观说：这是典型的巨头“聚焦”动作，把承压板块分出去，让核心业务轻装上阵。营养品在雅培四大板块里体量不小，但增长乏力，单独拆出来独立上市，反而能给它独立的估值和决策空间。全球巨头在周期里做这种取舍并不罕见，关键是新公司拿到自主权之后，能不能跑出比“大公司的一个部门”更快的节奏。 10月19日，美赞臣中国发布“AuxoKids科学成长营养系统”，用“1+T+N”三层结构，把儿童营养从“一罐奶粉打天下”拆成配方基底、精细营养支持、场景化解决方案三个层级。“1”——美赞臣多国专利认证的独家长短链益生元组合聚葡萄糖（PDX）和低聚半乳糖（GOS）搭建配方基底；“T”——多种生物活性肽，实现营养精细化；“N”——围绕不同成长阶段与生活场景延伸出的多样化营养方案。美赞臣中国透露，核心儿童奶粉将全面应用这套系统，青少年新系列也在规划中，方向是成长+运动。 母观说：单品逻辑在3岁以后的市场正在失效，这几乎是行业共识。美赞臣正视了一个事实：儿童营养需求分层分场景，一罐奶粉包打天下的逻辑正在失效。方向是对的，但难点在落地：系统化方案对渠道的推介能力要求很高，需要门店愿意推、导购讲得清、消费者听得懂。能不能把“系统”真正落到货架上，考验的是渠道协同的深度。 10月20日，国内母婴设计师护理品牌重庆盛夏光年护理用品有限公司宣布完成5000万元A轮融资，本轮投资方为重庆弘晖渝邑私募股权投资基金合伙企业（有限合伙）。本轮资金将重点用于品牌建设、渠道建设与深化产品研发。 母观说：纸尿裤这个品类，价格战已经打到没什么空间了。资本在这个时候加注一个设计师品牌，说明市场开始重新审视“品牌辨识度”的价值。盛夏光年靠设计和品牌感切出了一块自己的位置。拿到钱之后，能不能把全场景护理的故事讲成实实在在的复购，才是决定这条路能走多远的关键。 10月20日，两只兔子发布3款AI智能硬件：求知3 AI安全座椅、Ori Ring灵犀智能指环和FreeAir AI免手扶吸奶器，分别瞄准儿童出行、女性健康和哺育场景。据悉，两只兔子今年上半年GMV同比增长200%，全国入驻门店超过1800家。目前业务规模约3亿元。其计划于今年年底开展C轮融资、2028年冲刺港交所IPO。两只兔子杭州富阳超级智慧工厂项目已完成建设，计划于今年11月启动产线。（智东西） 母观说：母婴硬件的竞争正在换挡，从拼功能、拼价格，转向拼智能、拼体验。两只兔子一口气发三款AI硬件，覆盖出行、健康、哺育，试图用“平台化”的方式卡住母婴场景的多个入口。这个打法的好处是想象空间大，难点是每一条产品线都需要独立的产品力支撑。资本给了弹药，市场会给答案。"},{"title":"帮宝适、Babycare、inne同登TOP20：双11母婴没有黑马，只有硬通货","summary":"帮宝适、Babycare、inne等品牌在双11期间均位列母婴行业TOP20，显示母婴市场竞争格局已逐渐稳定。这一现象对从业者意味着，市场领导者的地位需要持续巩固，品牌需专注于提升自身竞争力，而非期待黑马出现。纸尿裤大盘增长放缓，品牌以全价格带为底盘、发力高端线，牢牢守住头部席位。inne、健敏思、迪巧三个营养品品牌同时进入TOP20，背后却走出三条截然不同的增长路径。","source_id":"gnews_cn_baby_category","source_name":"母婴行业观察","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"http://www.myguancha.com/post/27880.html","published_at":"2026-10-26T11:17:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T12:06:48+08:00","language":"zh","author":"","tags":["市场数据","品牌动态","跨境电商"],"priority":"P1","score":16.0,"matched":["帮宝适","babycare","母婴"],"id":"7e3ec17cdb7e63ad","title_zh":"帮宝适、Babycare、inne同登TOP20：双11母婴没有黑马，只有硬通货","summary_source":"llm","summary_kind":"brief","points":["帮宝适、Babycare、inne双11登顶TOP20","母婴市场竞争格局稳定","品牌需持续提升竞争力"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月20日晚8点到12点，天猫母婴亲子4小时成交榜出炉：帮宝适第一，FILAKIDS、Babycare、全棉时代、inne、丸丫紧随其后。再往下，安踏儿童、好孩子、好奇、巴拉巴拉、泰兰尼斯、BeBeBus、爱他美等悉数在列，榜单里几乎找不到靠短期流量爆发的品牌。 帮宝适登顶，并不意外。纸尿裤大盘增长放缓，品牌以全价格带为底盘、发力高端线，牢牢守住头部席位。这个品类的竞争，早已跳出“更薄、吸收更快”的参数比拼，竞争核心被收拢到一点：能不能缩短消费者的决策犹豫时间。好奇多年攒下的品牌认知、Babycare的多品类布局，本质上都在回答同一个问题。 Babycare第三，是这份榜单里最能说明“一个品牌能走多宽”的样本。从婴儿背带起家，如今尿裤、喂养、洗护、出行、玩具全面铺开，开门红四小时冲进前三，靠的不是单品爆发，而是同一批用户、同一套信任，在多个品类里反复变现。这种信任迁移，单一爆品品牌短期内很难复制。 全棉时代第四，路径不同但逻辑相通：从棉柔巾起家，把“全棉、安全、品质”的心智延伸到母婴护理、婴童服饰、孕产用品，依托统一材质心智，完成跨品类复用。 榜单里童装童鞋占据四席，FILA KIDS第二，安踏儿童第八，巴拉巴拉和泰兰尼斯依次上榜，但相比数量，背后的结构变化更值得关注。 FILAKIDS冲到全品类第二，不单单是童装卖得好。成人线积累的网球基因、科技面料、运动时尚定位，被完整平移到儿童线。安踏儿童同理，成人市场的研发体系、供应链议价能力、品牌势能，迁移到童装品类时，效率远高于从零孵化一个童装品牌。 巴拉巴拉仍是童装市占率第一，规模底盘稳固。但它面对的对手不再是传统童装品牌，而是携成人科技资产、品牌势能降维入局的运动巨头。泰兰尼斯则走另一条路，不拼品类覆盖，只做“专业学步”这一件事，靠窄切口站稳童鞋赛道。 童装童鞋的竞争逻辑正在切换：从“拼款式、拼价格、拼覆盖”的泛化竞争，转向“拼专业身份、拼场景不可替代性”的精准竞争。运动品牌赢在科技背书，泰兰尼斯赢在垂直心智，泛品类玩家的护城河正在被两头夹击。 inne、健敏思、迪巧三个营养品品牌同时进入TOP20，背后却走出三条截然不同的增长路径。 inne 的突围，踩准的是“分龄精准”替代“通用补充”：钙镁锌按低龄/学龄拆分，DHA切全脑与分时补脑，护眼单独成线，益生菌盯消化场景。它把儿童营养拆成多个具体场景，用较精简的SKU逐个击穿。 健敏思则更贴近敏宝与复合刚需家庭，把过敏原规避、多效配方做成差异化，这与inne形成了清晰的品类错位，一个主打“分龄营养场景”，把不同年龄段的具体需求做深；一个主打“体质安全底线”，帮焦虑的敏宝家庭排雷。两条路径互不干扰，却共同切走了传统基础营养品流失的用户。 迪巧代表第三种路线：常年稳居进口钙赛道头部，不靠短期流量种草，依托渠道深耕、剂型迭代持续积累用户信任。母婴营养品赛道，慢增长并非短板，扎实的信任底盘足以支撑品牌穿越周期。 丸丫、好孩子、BeBeBus、Hagaday齐齐杀入TOP20，这不仅是推车、安全座椅、腰凳等高客单品类的胜利，更是赛道“马太效应”的极致放大。丸丫稳坐推车头部，BeBeBus领跑安全座椅，好孩子靠多品类矩阵稳住大盘，头部玩家正在疯狂瓜分大盘。 这背后，是一个非常现实的消费心理：在出行大件上，家长的信任防线极高，且几乎没有容错率。品牌一旦成为用户心中的默认选择，后来者想要突围，必须花费更长周期去搭建信任。"},{"title":"有婴幼儿食用银鳕鱼后血汞异常！重要提醒→","summary":"消费者权益保护组织联合专业机构调查发现，有婴幼儿食用银鳕鱼后出现血汞异常情况。专家指出，市面上售卖的各类“鳕鱼”产品并非特指单一物种或某类鱼，消费者需注意区分。这一事件提醒从业者需关注婴幼儿食品的原料安全，加强产品溯源管理，确保产品质量符合国家标准。","source_id":"cfsn","source_name":"中国食品安全报","source_url":"http://www.cfsn.cn/","original_url":"https://www.cfsn.cn/news/detail/340/370507.html","published_at":"","published_guessed":true,"fetched_at":"2026-10-26T11:16:22+08:00","language":"zh","author":"","tags":["质量安全","政策法规"],"priority":"P1","score":6.4,"matched":["婴幼儿"],"id":"f0b6c433f724e899","image":"https://cfsn-2024upload.oss-cn-beijing.aliyuncs.com/imgs/20260603/2026060315225717889.png","body":"最近，“鳕鱼”是社交媒体上的热门关键词。有消费者权益保护组织联合专业机构调查发现，市面上冷冻的“鳕鱼”主要有三种，价格相差十几甚至二十倍，其中，最贵的是“银鳕鱼”。 专家介绍，市面上售卖的各类“鳕鱼”产品，并非特指单一物种或某类鱼。其中，“银鳕鱼”通常包括犬牙鱼、裸盖鱼等，它们并非生物学定义上的鳕鱼，只是行业形成的商业俗称。价格高昂的原因除了营养价值和口感突出，也是因为产量稀少。 但定位“高端”的银鳕鱼，最近因为有低龄儿童食用后汞含量超标的消息，受到关注和质疑。 鳕鱼专家、大连海洋大学水产与生命学院退休教授姜志强表示，银鳕鱼作为深海大型鱼类，处于食物链顶端，会从小鱼身上摄取汞等重金属，并富集在体内。很小的孩子应慎重食用，大一些的孩子可以适当地少吃一点。 北京营养师协会理事顾中一也表示，银鳕鱼不饱和脂肪酸含量高，但也更容易富集重金属。考虑到对于汞的风险管理，如果要给孩子吃，建议控制摄入量。 专家表示，目前针对银鳕鱼体内的汞含量还缺乏更加系统的调查研究。需要注意的是，即使是同一种鱼，生活环境和生长年份不同，体内的汞含量也有差异，安全性无法一概而论。 因此，在适量食用的基础上，不同年龄、体质的人也可以根据需求选择不同类型的“鳕鱼”： 另外，要想更好地保留鳕鱼的营养，最好采用清蒸的烹饪方式。尽量不要煎炸，如果实在想煎，最好靠鱼自身的油脂简单烹饪，同时注意油温不要过高。","summary_source":"llm","title_zh":"有婴幼儿食用银鳕鱼后血汞异常！重要提醒→","translated":true,"points":["婴幼儿食用银鳕鱼后血汞异常","市面上“鳕鱼”产品并非特指单一物种","消费者需注意区分","事件提醒婴幼儿食品原料安全"],"points_source":"llm","summary_kind":"brief"},{"title":"蒙牛悄悄养了三年的特医品牌，终于亮牌了？ - 母婴行业观察","summary":"蒙牛推出特医品牌特一亿诺，专注于婴幼儿罕见病、过敏及成人组件类特医食品，布局差异化市场。该品牌背靠蒙牛全产业链，但面临国外品牌竞争和特医食品监管挑战。对行业从业者意味着需关注特医食品市场发展趋势，重视差异化竞争和全产业链布局。跨境乳企可关注国内特医食品市场潜力，探索细分领域机会。品牌成立于2023年10月，完成主体注册后始终保持低调，直到2026年8月至9月才陆续集中亮相系列产品。","source_id":"gnews_cn_special_med","source_name":"Google News·特医食品（中文）","source_url":"https://news.google.com/rss/search?q=%28%E7%89%B9%E5%8C%BB%E9%A3%9F%E5%93%81%20OR%20%E7%89%B9%E6%AE%8A%E5%8C%BB%E5%AD%A6%E7%94%A8%E9%80%94%E9%85%8D%E6%96%B9%E9%A3%9F%E5%93%81%20OR%20%E6%B0%A8%E5%9F%BA%E9%85%B8%E9%85%8D%E6%96%B9%20OR%20%E6%B7%B1%E5%BA%A6%E6%B0%B4%E8%A7%A3%29%20%E5%A9%B4%E5%B9%BC%E5%84%BF&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"http://www.myguancha.com/post/27873.html","published_at":"2026-10-26T10:18:00+08:00","published_guessed":false,"fetched_at":"2026-10-26T13:09:53+08:00","language":"zh","author":"","tags":["质量安全","市场数据","供应链"],"priority":"P0","score":9.6,"matched":["蒙牛","母婴"],"id":"10a30c0366e99130","title_zh":"蒙牛悄悄养了三年的特医品牌，终于亮牌了？","summary_source":"llm","translated":true,"link_resolved":true,"body":"伴随着宁敏瑞、萱康安两款特医产品拿到“双首证”，蒙牛孵化的独立特医品牌“特一亿诺”闯入大众视野。 这是一家怎样的企业？同样是做特医，蒙牛和其他乳企布局差异性在哪？本文将逐一拆解，以看清当下国产特医市场现状。 特一亿诺全称上海特一亿诺健康科技有限公司，由蒙牛控股，是完全独立运营的特医子公司。 品牌成立于2023年10月，完成主体注册后始终保持低调，直到2026年8月至9月才陆续集中亮相系列产品。 正式切入市场之后，特一亿诺没有扎堆入局内卷化赛道，没有跟风挤入竞争已经十分激烈的普通早产、无乳糖特配粉赛道，而是 瞄准国内过去供给不足的婴幼儿罕见代谢病、重度食物蛋白过敏、成人术后重症营养支持等刚需细分市场 。 截至2026年9月，特一亿诺已经拿到三款国家注册特医产品，覆盖婴幼儿到成人的不同临床需求。 具体来看，瑞葆安®，针对0-12月龄苯丙酮尿症婴儿，属于罕见病宝宝必需的“生命口粮”；宁敏瑞®，面向0-12月龄重度食物蛋白过敏婴儿，是国产首批新国标婴儿氨基酸配方产品；萱康安®，面向18岁以上需要谷氨酰胺补充的术后、重症康复人群，填补国内该组件配方的国产空白。 在产业布局上，特一亿诺构建了“自研+自有工厂+自主销售”全闭环产业链体系，内蒙古特康瑞工厂为特医专厂专线运营，只生产特殊医学用途配方食品，是国产少数拥有专属特医生产工厂的品牌。 根据灼识咨询公开数据，2024年国内特医食品市场规模为232亿元，预计2029年可以达到531亿元，2024至2029年复合增长率18%。整个市场渗透率仅3%，对比美国市场超40%的渗透率，国内行业整体还处在发展早期阶段。 截至2026年6月，国内累计获批特医食品342款， 外资品牌在部分高壁垒细分品类依旧保持优势，达能纽迪希亚、雀巢等企业依靠较早入局 ，积累大量临床学术资源，国产企业注册产品数量持续提升，但多数集中在婴儿特医板块，成人组件类产品数量偏少。 在这样的行业环境里， 特一亿诺展现出自身差异化 ：背靠蒙牛的产业、资金、供应链实力，同时作为独立特医公司，不受普通快消奶粉业务的束缚；产品上同时布局婴幼儿罕见病、过敏，再加成人组件类特医，打通了“婴儿+成人”两端，这在国产新玩家中并不多见。 但即便如此，但特一亿诺想要站稳脚跟，依然面临不少难题。一方面，国外特医品牌深耕市场多年，在医院渠道、医生认可、大众口碑上积累了深厚优势，用户根深蒂固更信任进口品牌；另一方面，特医食品属于严格监管的特殊食品，不允许大肆广告宣传，只能依靠医院、营养师、专业圈层推广，品牌普及速度慢。同时，特医产品研发投入大、审批周期长，想要持续丰富产品、扩大市场，对品牌的资金和技术都是长期考验。 总的来看，手握多款稀缺持证产品、又背靠蒙牛全产业链支撑的特一亿诺，正站在国产特医起势的节点上，后续动作值得持续关注。 版权声明： 转载母婴行业观察的原创文章，需注明文章来源以及作者名称。公众号转载请联系开白小助手（微信号：zhangxiaoxian1015）。违规转载法律必究。 扫描二维码，第一时间获取母婴行业的资讯和动态。 从此和母婴行业观察建立直接联系。","summary_kind":"none","needs_summary":true,"points":["蒙牛推出特医品牌特一亿诺","面临国外品牌竞争","需关注特医食品趋势"],"points_source":"llm"},{"title":"雀巢Q3营收超1800亿元！婴儿奶粉稳步调整，宠物护理接棒高增长 - 母婴行业观察","summary":"雀巢2026年第三季度财报显示，集团单季销售额达228亿瑞士法郎，折合人民币约1849亿元，有机增长率4.0%，实际内部增长率2.8%，为2021年以来最佳表现。大中华区连续两个季度回暖，新兴市场有机增长6.8%。宠物护理业务有机增长5.3%，成为增长最快的板块之一。婴儿奶粉业务处于稳步修复阶段，对整体增长形成一定拖累。整体来看，雀巢三季度成效不错，所有大区与全球直管业务的实际内部增长全部转正，新兴市场有机增长6.8%、RIG4.3%；","source_id":"gnews_cn_brands","source_name":"Google News·奶粉品牌动态（中文）","source_url":"https://news.google.com/rss/search?q=(%E9%9B%80%E5%B7%A2%20OR%20%E8%BE%BE%E8%83%BD%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E4%BC%8A%E5%88%A9%20OR%20%E6%BE%B3%E4%BC%98)%20(%E5%A5%B6%E7%B2%89%20OR%20%E5%A9%B4%E9%85%8D)%20-%E8%82%A1%E7%A5%A8&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"http://www.myguancha.com/post/27872.html","published_at":"2026-10-26T10:15:00+08:00","published_guessed":false,"fetched_at":"2026-10-26T13:09:34+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","供应链"],"priority":"P1","score":27.2,"matched":["奶粉","婴儿","雀巢","母婴","营收"],"id":"75412232309dfb6d","title_zh":"雀巢Q3营收超1800亿元！婴儿奶粉稳步调整，宠物护理接棒高增长","summary_source":"llm","translated":true,"link_resolved":true,"body":"近日，雀巢发布2026年第三季度及前9个月财报： 三季度集团单季销售额228亿瑞士法郎（折合人民币约1849亿元） ，有机增长率4.0%，其中实际内部增长率（RIG）达2.8%，为2021年以来最好表现，高于分析师预期的3.4%。 这份成绩单，被视为新任首席执行官费耐睿上任一年来的阶段性成果。其中，大中华区连续两个季度的回暖，成为这份答卷里最值得关注的看点。 整体来看，雀巢三季度成效不错，所有大区与全球直管业务的实际内部增长全部转正，新兴市场有机增长6.8%、RIG4.3%；发达市场有机增长2.2%、RIG1.9%。渠道方面，电商有机增长15.3%，占集团总销售额21.6%。 分板块看，雀巢旗下 宠物护理 有机增长5.3%、RIG4.3%，新兴市场宠物护理业务今年至今有机销售额增长约10%， 是增长最快的板块之一 ；食品与零食有机增长5.0%；咖啡有机增长3.4%； 营养业务有机增长0.3%，其中医学营养连续第六个季度提速 ，表现亮眼； 婴儿奶粉业务则处于稳步修复阶段 ，对集团整体有机增长形成一定拖累，相关影响正在逐步收窄。 最受关注的是中国市场 ：大中华区三季度有机增长4.2%，其中RIG3.7%、定价贡献0.5%， 连续第二个季度实现增长 ，一方面源于2025年同期渠道库存调整带来的低基数，另一方面来自核心业务持续改善。雀巢管理层表示，外部市场环境“依然充满挑战”，但包含中国在内的新兴市场，是其重点加码的宠物护理的增长平台。 9月，集团与Yellow Wood Partners达成协议，拟以10亿美元（约8亿瑞郎）出售大众维生素矿物质补充剂（VMS）业务，含自然之宝等7大品牌，预计2027年上半年完成交割。7月，雀巢宣布与Platinum Equity合资设立Peranel，各持50%股权，运营水业务及高端饮料业务，该业务前9个月销售额28亿瑞郎，有机增长7.5%。4月，蓝瓶咖啡资产完成出售。 随着出生人口下行，0-3岁婴幼儿规模持续萎缩， 婴配粉增长早已见顶。乳企不再局限于婴幼儿配方奶粉单一赛道，企业纷纷向外拓展成长空间 。 贝因美借国资入场布局AI智能母婴、女性私护、康养消费等关联赛道；澳优加码运动营养、职场修复、抗衰老；飞鹤布局全生命周期产品与乳原料；伊利全面布局控糖、骨骼、免疫等功能赛道并加码乳原料深加工；蒙牛押注运动营养、特医食品子品牌。 综上来看， 雀巢“聚焦优势、剥离非核心”的战略路径清晰，婴配业务仍处修复阶段，但调整方向明确，宠物与新兴市场正成为新的增长支点。 当婴儿生意见顶，谁能把增量赛道做成新的增长曲线，谁才能熬过周期。雀巢维持全年指引，自由现金流预计超90亿瑞士法郎。对这家百年乳企而言，下一季度的真正考验在于：这份由销量撑起的增长，能否在剥离与聚焦的转型中持续兑现。 版权声明： 转载母婴行业观察的原创文章，需注明文章来源以及作者名称。公众号转载请联系开白小助手（微信号：zhangxiaoxian1015）。违规转载法律必究。 扫描二维码，第一时间获取母婴行业的资讯和动态。 从此和母婴行业观察建立直接联系。","summary_kind":"none","needs_summary":true,"points":["雀巢Q3营收达228亿瑞士法郎","宠物护理业务有机增长5.3%","新兴市场有机增长6.8%","婴儿奶粉业务稳步修复"],"points_source":"llm"},{"title":"雀巢Q3营收超1800亿元！婴儿奶粉稳步调整，宠物护理接棒高增长 - 母婴行业观察","summary":"雀巢2026年第三季度集团单季销售额228亿瑞士法郎，折合人民币约1849亿元，有机增长率4.0%，实际内部增长率达2.8%，为2021年以来最好表现。大中华区连续两个季度回暖，电商有机增长15.3%。宠物护理业务有机增长5.3%，成为增长最快的板块之一。婴儿奶粉业务处于稳步修复阶段。对从业者而言，这反映了行业结构调整，新兴市场和宠物护理成为新的增长点。","source_id":"gnews_cn_brand_news","source_name":"Google News·奶粉品牌动向（中文）","source_url":"https://news.google.com/rss/search?q=%E5%A5%B6%E7%B2%89%20%28%E9%A3%9E%E9%B9%A4%20OR%20%E4%BC%8A%E5%88%A9%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E8%BE%BE%E8%83%BD%20OR%20%E9%9B%80%E5%B7%A2%20OR%20%E7%BE%8E%E8%B5%9E%E8%87%A3%20OR%20%E6%83%A0%E6%B0%8F%20OR%20%E9%9B%85%E5%9F%B9%20OR%20%E6%BE%B3%E4%BC%98%20OR%20%E8%B4%9D%E5%9B%A0%E7%BE%8E%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"http://www.myguancha.com/post/27872.html","published_at":"2026-10-26T10:15:00+08:00","published_guessed":false,"fetched_at":"2026-10-26T14:04:13+08:00","language":"zh","author":"","tags":["市场数据","品牌动态"],"priority":"P0","score":27.2,"matched":["奶粉","婴儿","雀巢","母婴","营收"],"id":"c368a27765d63696","title_zh":"雀巢Q3营收超1800亿元婴儿奶粉稳步调整","summary_source":"llm","summary_kind":"brief","points":["雀巢Q3营收超1800亿元","婴儿奶粉业务稳步调整","宠物护理业务接棒实现高增长"],"points_source":"llm","translated":true,"link_resolved":true,"body":"近日，雀巢发布2026年第三季度及前9个月财报： 三季度集团单季销售额228亿瑞士法郎（折合人民币约1849亿元） ，有机增长率4.0%，其中实际内部增长率（RIG）达2.8%，为2021年以来最好表现，高于分析师预期的3.4%。 这份成绩单，被视为新任首席执行官费耐睿上任一年来的阶段性成果。其中，大中华区连续两个季度的回暖，成为这份答卷里最值得关注的看点。 整体来看，雀巢三季度成效不错，所有大区与全球直管业务的实际内部增长全部转正，新兴市场有机增长6.8%、RIG4.3%；发达市场有机增长2.2%、RIG1.9%。渠道方面，电商有机增长15.3%，占集团总销售额21.6%。 分板块看，雀巢旗下 宠物护理 有机增长5.3%、RIG4.3%，新兴市场宠物护理业务今年至今有机销售额增长约10%， 是增长最快的板块之一 ；食品与零食有机增长5.0%；咖啡有机增长3.4%； 营养业务有机增长0.3%，其中医学营养连续第六个季度提速 ，表现亮眼； 婴儿奶粉业务则处于稳步修复阶段 ，对集团整体有机增长形成一定拖累，相关影响正在逐步收窄。 最受关注的是中国市场 ：大中华区三季度有机增长4.2%，其中RIG3.7%、定价贡献0.5%， 连续第二个季度实现增长 ，一方面源于2025年同期渠道库存调整带来的低基数，另一方面来自核心业务持续改善。雀巢管理层表示，外部市场环境“依然充满挑战”，但包含中国在内的新兴市场，是其重点加码的宠物护理的增长平台。 9月，集团与Yellow Wood Partners达成协议，拟以10亿美元（约8亿瑞郎）出售大众维生素矿物质补充剂（VMS）业务，含自然之宝等7大品牌，预计2027年上半年完成交割。7月，雀巢宣布与Platinum Equity合资设立Peranel，各持50%股权，运营水业务及高端饮料业务，该业务前9个月销售额28亿瑞郎，有机增长7.5%。4月，蓝瓶咖啡资产完成出售。 随着出生人口下行，0-3岁婴幼儿规模持续萎缩， 婴配粉增长早已见顶。乳企不再局限于婴幼儿配方奶粉单一赛道，企业纷纷向外拓展成长空间 。 贝因美借国资入场布局AI智能母婴、女性私护、康养消费等关联赛道；澳优加码运动营养、职场修复、抗衰老；飞鹤布局全生命周期产品与乳原料；伊利全面布局控糖、骨骼、免疫等功能赛道并加码乳原料深加工；蒙牛押注运动营养、特医食品子品牌。 综上来看， 雀巢“聚焦优势、剥离非核心”的战略路径清晰，婴配业务仍处修复阶段，但调整方向明确，宠物与新兴市场正成为新的增长支点。 当婴儿生意见顶，谁能把增量赛道做成新的增长曲线，谁才能熬过周期。雀巢维持全年指引，自由现金流预计超90亿瑞士法郎。对这家百年乳企而言，下一季度的真正考验在于：这份由销量撑起的增长，能否在剥离与聚焦的转型中持续兑现。 版权声明： 转载母婴行业观察的原创文章，需注明文章来源以及作者名称。公众号转载请联系开白小助手（微信号：zhangxiaoxian1015）。违规转载法律必究。 扫描二维码，第一时间获取母婴行业的资讯和动态。 从此和母婴行业观察建立直接联系。"},{"title":"周末装婴儿车加露营装备，汉兰达和RAV4荣放谁更装得下？","summary":"汽车之家报道，探讨汉兰达和RAV4荣放装载婴儿车和露营装备的能力对比。对母婴行业从业者而言，了解不同车型装载空间有助于为消费者提供更全面的购车建议，满足家庭出行需求。这类信息对推荐适合家庭使用的车型有参考价值，需结合消费者实际需求进行推荐。","source_id":"gnews_cn_baby_category","source_name":"汽车之家","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://chejiahao.autohome.com.cn/info/26733799","published_at":"2026-10-26T10:07:49+08:00","published_guessed":false,"fetched_at":"2026-10-29T00:39:20+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":11.2,"matched":["婴儿","婴儿车"],"id":"2a35c859b2789beb","link_resolved":true,"image":"https://www2.autoimg.cn/chejiahaodfs/g34/M09/3C/2C/autohomecar__ChxpV2res0qAbcvEAAK19eA48eI966.jpg","summary_source":"llm","summary_kind":"brief","title_zh":"周末装婴儿车加露营装备，汉兰达和RAV4荣放谁更装得下？","translated":true,"points":["汉兰达和RAV4荣放装载对比","关注家庭用车需求","车型选择参考依据"],"points_source":"llm"},{"title":"Fonterra warns energy outages threaten $25b dairy exports - B2B News","summary":"恒天然警告，能源中断可能威胁其25亿美元的乳制品出口业务。这一警告凸显了能源供应对新西兰乳制品出口的重要性。对跨境母婴行业从业者而言，这意味着需关注全球能源市场动态，评估其对乳制品生产和出口的影响。能源供应的不稳定性可能增加生产成本，影响产品供应稳定性，进而影响婴幼儿奶粉行业的供应链安全。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://b2bnews.co.nz/news/fonterra-warns-energy-outages-threaten-25b-dairy-exports/","published_at":"2026-10-26T09:39:39+08:00","published_guessed":false,"fetched_at":"2026-10-26T22:39:54+08:00","language":"en","author":"","tags":["供应链","海外动态"],"priority":"P0","score":9.6,"matched":["dairy","fonterra"],"id":"e7769953ccf88f89","title_zh":"恒天然警告能源中断威胁25亿美元乳制品出口","summary_source":"llm","summary_kind":"brief","points":["恒天然警告能源中断威胁25亿美元乳制品出口","凸显能源供应对新西兰乳制品出口的重要性","影响乳制品生产和出口","需关注能源市场动态"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Fonterra has moved its energy complaint from the cost line to the continuity line. In this year’s Mood of the Boardroom, managing director co-operative affairs Matt Bolger warns that prolonged energy outages could threaten dairy processing . Coming from the company behind $25 billion in FY2026 export earnings , that is not a household-bill gripe. It is a supply-chain risk sitting under New Zealand’s largest export sector. The shift in language matters. In August 2024, when hydro lakes ran low and gas tightened, wholesale prices doubled over three weeks to exceed $900/MWh . BusinessDesk reported prices trading above $800/MWh, up from roughly $150/MWh . Fonterra’s then-COO Anna Palairet said at the time the co-op was “confident that energy remains available to process milk” , but that the situation was adding significant cost “as we cannot simply pause operations.” That last line is the whole story. Milk does not wait. A factory that loses power at peak season is not deferring production, it is losing it. In 2024 the concern was margin. In 2026 Fonterra is openly questioning availability. Bolger’s broader pitch is about growth: strong US demand for New Zealand dairy protein, rising capital and IT spend, and a $1 billion investment in South Island value-add ingredients . Those premium ingredient customers pay for reliability. A multinational food company that misses a production run because a New Zealand supplier could not keep its plant running will remember. That risk is sharper because the country’s trade position is narrow. Bolger estimates New Zealand has access to only around 14% of global dairy consumption at tariffs below 10% . When you cannot win on market access, you win on dependability. Lose that and the premium goes with it. And with $19.6 billion of the $25 billion flowing back into the domestic economy, roughly 78 cents in every export dollar, the exposure is not just Fonterra’s. This is not a company asking someone else to fix its problems. Fonterra’s FY25 annual report showed it retired its last coal boiler in November 2024 , committed $150 million to electrify North Island sites including a $64 million electrode boiler at Whareroa, and spent $104 million in FY25 on energy security and decarbonisation out of $635 million in essential capex. Here is the irony business readers should notice.","image":"https://b2bnews.co.nz/wp-content/uploads/2026/10/fonterras-energy-warning-turns-power-outages-into-an-export-risk.webp"},{"title":"Fonterra warns prolonged energy outages could threaten dairy processing - NZ Herald","summary":"恒天然警告，长期能源中断可能威胁乳制品加工业务。这一警告反映了能源供应对乳制品加工企业的直接影响。对跨境母婴行业从业者而言，这意味着需关注全球能源市场动态，评估其对乳制品生产和加工的影响。能源供应的不稳定性可能增加生产成本，影响产品供应稳定性，进而影响婴幼儿奶粉行业的供应链安全。长期能源中断可能对乳制品加工企业造成严重损失，影响产品质量和供应稳定性。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.nzherald.co.nz/business/business-reports/mood-of-the-boardroom/fonterra-warns-prolonged-energy-outages-could-threaten-dairy-processing/premium/GPZX7YVUUZGC7MQDSJQBO4H4RY/","published_at":"2026-10-26T05:01:28+08:00","published_guessed":false,"fetched_at":"2026-10-26T22:39:54+08:00","language":"en","author":"","tags":["供应链"],"priority":"P0","score":9.6,"matched":["dairy","fonterra"],"id":"1b0f3df2b13313bb","title_zh":"恒天然警告长期能源中断可能威胁乳制品加工","summary_source":"llm","summary_kind":"brief","points":["恒天然警告长期能源中断威胁乳制品加工","反映能源供应对乳制品加工的直接影响","影响乳制品生产和加工","需关注能源市场动态"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Fonterra’s growth ambitions are at full throttle as premium-paying markets like the United States demand New Zealand’s highly-reputed dairy protein, but at home, the big exporter fears the brakes are on in the economy. As the country’s biggest company readies to increase capital and IT expenditure and forecasts revenue and profit growth, its managing director co-operative affairs Matt Bolger says national labour productivity is stubbornly slow to rise, technology uptake ambition is small and energy supply resilience a real concern. Matt Bolger, Fonterra's managing director, co-operative affairs. Photo / Stephen Barker All this while New Zealand struggles for more access to high-value export markets to provide greater diversification at a time of major geopolitical uncertainty. Fonterra can cite $25 billion in export earnings for the 2026 financial year, with $19.6b of this returned to the economy, and a $1b investment recently announced in the production of more South Island value-add ingredients. However, it also offers another stark statistic. Bolger estimates New Zealand has access to only around 14% of global dairy consumption at tariffs below 10%. “Trade access is extremely important to us and we applaud any work done by ministers and officials to open up more access. We get that it’s hard and that there are a lot of things going the other way. “We need to maintain the access we have and keep dairy access on the table – that’s a really important thing.” New Zealand’s need to invest in energy supply is also top of mind. With coal use banned after 2037 and the natural gas supply dwindling faster than expected, Fonterra, as a perishable product processor, is particularly vulnerable if energy supply is threatened. “If we can’t run factories for a day or a week, that has enormous implications because you can’t stop the product flowing. The potential for having energy outages that last any time is very bad, but if they last more than a few hours, that has huge implications for us and our customers, and ultimately farmers and the wider economy.” Fonterra no longer uses coal to fire its North Island manufacturing plants and is investing substantially and quickly to decarbonise and convert to biomass and wood pellet energy for its boilers, Bolger says.","image":"https://www.nzherald.co.nz/resizer/v2/O6SKFWC7HBAQNFBWHA4YE73DAM.jpg?auth=20150af73a2c019e26b96c5b2ce4241eb1464b557b0c71c6ae8367a18be02be0&width=1200&height=675&quality=70&focal=769%2C623&smart=false"},{"title":"Ingredients for Dairy Processors","summary":"文章探讨乳制品加工原料的设计、内容管理系统、主机托管及网页开发，涉及乳业生产技术。对乳业从业者而言，了解原料加工技术有助于优化生产流程，提升产品质量，适应市场变化。这是提升乳业竞争力的关键，从业者需关注技术革新对生产效率和质量控制的积极影响，以应对市场需求的不断变化。","source_id":"dairyfoods","source_name":"Dairy Foods","source_url":"https://www.dairyfoods.com/","original_url":"https://www.dairyfoods.com/topics/2633-ingredients-for-dairy-processors","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T21:43:29+08:00","language":"en","author":"","tags":["政策法规","质量安全","供应链"],"priority":"P2","score":4.8,"matched":["dairy"],"id":"16963b05dfac8b9b","summary_source":"llm","image":"https://www.dairyfoods.com/ext/resources/2025/01/16/07-ingredients-topic-DF.webp?t=1737063068","summary_kind":"brief","title_zh":"乳制品加工原料","translated":true,"points":["涉及乳业生产技术"],"points_source":"llm"},{"title":"The case for dairy in the UPF debate and ‘food as health’ approaches","summary":"随着慢性病和儿童健康问题日益受到关注，‘食物即健康’理念作为预防手段受到更多关注。乳制品因其营养特性，在平衡膳食与健康的关系中具有潜在价值，对婴幼儿奶粉和母婴健康领域具有重要意义。这一趋势要求从业者关注乳制品的营养价值，并将其作为产品开发的重要方向，以满足市场对健康食品的需求。","source_id":"dairyfoods","source_name":"Dairy Foods","source_url":"https://www.dairyfoods.com/","original_url":"https://www.dairyfoods.com/articles/99457-the-case-for-dairy-in-the-upf-debate-and-food-as-health-approaches","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T21:21:30+08:00","language":"en","author":"","tags":["质量安全","品牌动态","政策法规"],"priority":"P2","score":4.8,"matched":["dairy"],"id":"0d064391b8800596","summary_source":"llm","title_zh":"关于UPF（超加工食品）辩论中乳制品的立场及‘食物即健康’理念","translated":true,"body":"As concerns about chronic disease and children’s health grow, interest in “Food as Health” is increasing as a preventative strategy. \"Food as Health\" emphasizes the connection between what people eat and how those choices impact long-term health and overall well-being. Amid this environment, ultra-processed foods (UPFs) have also drawn attention, often becoming an easy target for criticism. Consumers may use the term “ultra-processed” to describe foods they believe contain unnecessary ingredients or lack nutritional value. However, processing encompasses a wide range of techniques serving many beneficial purposes including pasteurization, fermentation, and methods that extend shelf life, improve food safety, support distribution, and increase nutritional value. For dairy processors, this environment presents an opportunity to educate consumers, legislators, and other stakeholders about the nutritional value of dairy foods and the benefits of processing practices. Informed policymaking can help advance the shared goal of improving diet quality without reducing access to affordable foods that provide essential nutrients. Most foods undergo some degree of processing to enhance safety, preserve nutrients, and make nutrient-rich options more convenient and accessible. These benefits deserve equal consideration alongside concerns related to products of lower nutritional quality. Examples such as whole-grain cereals, canned beans, frozen vegetables, and yogurt show that processing itself is not what determines nutritional quality. Assessing a food’s healthfulness requires examining its nutrient composition, its role within eating patterns, and the needs of those consuming it. For dairy, pasteurization protects milk from harmful bacteria while maintaining nutrient integrity. Fermentation , which transforms milk into yogurt, kefir, and many cheeses, introduces beneficial changes that support digestion and gut health, while enhancing flavor and texture. Processing can also aid reformulation to reduce added sugars or sodium and to fortify products with beneficial nutrients. Many processors are now innovating around higher-protein and lower-lactose offerings that improve functionality and accessibility. Yet these advancements are often overlooked when UPF classifications focus on the degree of processing rather than nutrient density.","image":"https://www.dairyfoods.com/ext/resources/2026/10/13/Equipment-at-the-Milk-Factory.png?height=635&t=1791914914&width=1200","points":["乳制品在平衡膳食与健康中具价值","UPF辩论关注慢性病预防","‘食物即健康’理念受关注","乳制品健康属性需被重视"],"points_source":"llm","summary_kind":"brief"},{"title":"Preparing water systems for dairy growth in 2026","summary":"乳制品需求持续增长，为满足不断扩大的生产需求，加工商需提前规划供水系统以应对未来挑战。这一变化对婴幼儿奶粉及母婴行业从业者意味着，需关注水资源管理和供应链稳定性，以保障生产持续性和成本控制。供水系统的规划将直接影响生产效率和产品质量，是行业可持续发展的关键因素。","source_id":"dairyfoods","source_name":"Dairy Foods","source_url":"https://www.dairyfoods.com/","original_url":"https://www.dairyfoods.com/articles/99207-preparing-water-systems-for-dairy-growth-in-2026","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T21:21:30+08:00","language":"en","author":"","tags":["供应链","质量安全","跨境电商"],"priority":"P2","score":4.8,"matched":["dairy"],"id":"348993024e9a8ec5","summary_source":"llm","title_zh":"为2026年乳制品增长准备供水系统","translated":true,"body":"Demand for dairy products continues to grow, creating new opportunities for processers to expand production and meet evolving consumer preferences. According to McKinsey's 2026 dairy industry survey, protein-rich products are a major growth driver, with 88% of U.S. dairy executives identifying protein as one of the most influential demand trends. As processors invest to capture that growth, one question becomes increasingly important: can the facility’s infrastructure keep pace? Water is essential to every stage of dairy production, from processing and cleaning to wastewater treatment and regulatory compliance. As production increases, water systems face greater demands. Higher volumes generate more wastewater, while new products and processes can introduce additional treatment requirements. Infrastructure that once supported operations efficiently can become a barrier to future growth. At the same time, regulations continue to evolve. Proposed groundwater protection requirements in California, for example, could place stricter controls on wastewater management and land application practices. For many dairy processors, managing compliance, treatment performance, and planning for future capacity requires more time and expertise than is available in-house. That is why more processors are taking a strategic approach to water management. By partnering with experienced water specialists, dairy facilities can modernize infrastructure, improve operational performance, and create capacity for growth—allowing plant teams to stay focused on what they do best: producing high-quality dairy products. Water supports every stage of dairy production, from processing and cleaning to sanitation and wastewater treatment. As production increases, water systems must keep pace. Higher volumes can generate more wastewater, while new products and processes often introduce additional treatment requirements. Many facilities address these challenges as they emerge, adding equipment or upgrading systems to meet immediate needs. While effective in the short term, this approach can make it difficult to see how water, wastewater, and production systems interact across the facility. Adopting a more integrated view of water management helps processors identify constraints before they affect operations, improve efficiency, and plan for future growth.","image":"https://www.dairyfoods.com/ext/resources/images/sponsoredcontent/Xylem/BVF_Reactor_Xylem.jpg?height=635&t=1783610484&width=1200","points":["乳制品需求持续增长","加工商需规划供水系统","应对未来生产挑战","基础设施规划需被重视"],"points_source":"llm","summary_kind":"brief"},{"title":"The future of infant formula safety is about understanding more, not testing more","summary":"沙门氏菌和克洛杆菌仍是婴儿配方奶粉和低水分食品的关键关注点。未来安全策略应侧重于深入理解产品成分与生产过程，而非单纯增加检测数量。这类事件对从业者意味着需关注行业安全标准，加强产品研发与质量控制，以应对潜在风险，保障消费者健康。这一转变要求行业从被动检测转向主动预防，通过技术创新和管理优化提升产品安全性。对从业者而言，需加大对产品成分和生产工艺的研究投入，建立更完善的质量管理体系，以应对日益严格的行业安全标准。","source_id":"dairyfoods","source_name":"Dairy Foods","source_url":"https://www.dairyfoods.com/","original_url":"https://www.dairyfoods.com/articles/99459-the-future-of-infant-formula-safety-is-about-understanding-more-not-testing-more","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T21:21:30+08:00","language":"en","author":"","tags":["政策法规","质量安全","海外动态"],"priority":"P2","score":12.8,"matched":["infant formula","infant"],"id":"437da0128f5c5537","summary_source":"llm","title_zh":"婴儿配方奶粉安全的未来在于更深入的理解而非更多检测","translated":true,"body":"Salmonella and Cronobacter remain essential priorities in infant formula and low-moisture foods. At the same time, recent events involving cereulide-producing B. cereus and C. botulinum demonstrate that the industry has to be prepared for risks and contamination pathways beyond the organisms traditionally at the center of our programs. For manufacturers, events like these bring about difficult questions about how and where a hazard entered the supply chain, whether it could have been identified sooner, and what additional controls may be needed to prevent it from happening again. They also understandably raise concerns among parents and caregivers who rely on infant formula and want confidence in its safety. As ingredients, supply chains, manufacturing processes, and our scientific understanding continue to evolve, our goal should be to build resilient food safety programs that allow for reliable routine detection and strong controls around both established and emerging hazards. The hallmarks of a resilient food safety program are asking not just “what organism are we looking for?” but also “where could that risk come from, and how early can we identify it?” Diagnostics capabilities are rapidly evolving to enable this approach, helping us move from simply detecting what’s there to understanding what that result means in the context of the whole system. Historically, many food safety programs have been built around testing the finished product and confirming that it is safe. While this remains a critical final step, stronger, more resilient programs are looking upstream at what’s being brought in through ingredients, how those ingredients are produced, and what suppliers are telling them. They are probing their process controls and how effectively they work. They are examining the environment for patterns and conditions that may signal where risk is developing. While routine measurements, whether that is pathogen detection or enumeration of organisms like Bacillus cereus , give us an important view of what might be happening in the process, the value comes from what we do with that information. Cereulide, for example, is a heat-stable toxin produced by certain strains of B. cereus , which means that monitoring the organism and detecting the toxin answer different questions about risk.","image":"https://www.dairyfoods.com/ext/resources/2026/10/13/Infant-Formula-Adobe-Stock.jpeg?height=635&t=1791908140&width=1200","summary_kind":"brief","points":["关注沙门氏菌和克洛杆菌","安全策略侧重深入理解","需加强产品研发与质量控制"],"points_source":"llm"},{"title":"Probiotic Infant Formula Market Forecast to Reach US$5.80 - openPR.com","summary":"益生菌婴儿奶粉市场预计将增长至5.8亿美元。这一市场发展趋势对从业者意味着需关注益生菌产品的市场潜力，考虑产品线拓展。益生菌婴儿奶粉市场的增长反映了消费者对婴幼儿健康产品的需求增加，为从业者提供了新的市场机遇。应密切关注这一细分市场的动态，适时调整产品策略，以满足市场需求，抢占市场先机。","source_id":"gnews_en_reg","source_name":"Google News·formula regulation（英文）","source_url":"https://news.google.com/rss/search?q=%22infant%20formula%22%20%28FDA%20OR%20EFSA%20OR%20FSANZ%20OR%20regulation%20OR%20standard%20OR%20ban%29&hl=en-US&gl=US&ceid=US:en","original_url":"https://www.openpr.com/news/4671846/probiotic-infant-formula-market-forecast-to-reach-us-5-80","published_at":"2026-10-25T21:19:06+08:00","published_guessed":false,"fetched_at":"2026-10-26T12:23:47+08:00","language":"en","author":"","tags":["市场数据","质量安全","跨境电商"],"priority":"P0","score":12.8,"matched":["infant formula","infant"],"id":"5c10093a841d4050","title_zh":"益生菌婴儿奶粉市场预测将达5.8亿美元","summary_source":"llm","points":["市场增长预测","益生菌产品线拓展"],"points_source":"llm","translated":true,"link_resolved":true,"image":"https://cdn.open-pr.com/L/a/La25546839_g.jpg","summary_kind":"brief"},{"title":"妙可蓝多发展路径趋同蒙牛？深度解析两家乳企战略布局相似度与差异化竞争格局 - 36Kr","summary":"36Kr深度解析了妙可蓝多与蒙牛的战略布局，指出两者在发展路径上存在趋同现象。文章探讨了双方在竞争格局中的相似之处与差异化策略，为乳业从业者提供了战略参考。2026年前三季度，妙可蓝多实现营收48.66亿元，同比增长22.97%，归属于上市公司股东的净利润2.12亿元，同比增长20.37%。营收和利润显著提升，扣非净利润同比增长28.15%，高于营收和归母净利润增速，表明利润增长主要来源于主营业务的内生改善。","source_id":"gnews_cn_brand_fin","source_name":"Google News·乳企财报与资本（中文）","source_url":"https://news.google.com/rss/search?q=(%E4%BC%8A%E5%88%A9%20OR%20%E8%92%99%E7%89%9B%20OR%20%E9%A3%9E%E9%B9%A4%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E5%85%89%E6%98%8E%E5%AD%95%E4%B8%9A)%20(%E8%B4%A2%E6%8A%A5%20OR%20%E8%90%A5%E6%94%B6%20OR%20%E5%B8%82%E5%8D%A0%E7%8E%87%20OR%20%E4%B8%9A%E7%BB%A9)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://eu.36kr.com/zh/p/4041419254682500","published_at":"2026-10-25T18:08:00+08:00","published_guessed":false,"fetched_at":"2026-10-26T11:45:03+08:00","language":"zh","author":"","tags":["品牌动态","市场数据"],"priority":"P1","score":4.8,"matched":["蒙牛"],"id":"ef28624856495f0b","title_zh":"妙可蓝多发展路径趋同蒙牛？深度解析两家乳企战略布局相似度与差异化竞争格局","summary_source":"llm","points":["妙可蓝多与蒙牛战略布局趋同","探讨竞争格局相似与差异化","为乳业从业者提供战略参考","揭示行业竞争新动态"],"translated":true,"link_resolved":true,"body":"妙可蓝多，和蒙牛越来越像？ 摩根商研所 2026-10-26 09:08 妙可蓝多，放弃多元化？ 2026年前三季度，妙可蓝多实现营收48.66亿元，同比增长22.97%，归属于上市公司股东的净利润2.12亿元，同比增长20.37%。 这是妙可蓝多创始人时代的最后一份成绩单。今年9月，妙可蓝多61岁创始人柴琇辞职，不再担任公司及子公司任何职务。 营收和利润显著提升，扣非净利润同比增长28.15%，高于营收和归母净利润增速，表明利润增长主要来源于主营业务的内生改善。 天眼查APP显示，截至2026年10月21日收盘，妙可蓝多总市值为95.74亿元。 2026年上半年，妙可蓝多奶酪业务收入占总收入比重达到88.06%，与去年同期相比不降反升。 2026年上半年妙可蓝多销售费用同比大增42.93%，其中广告促销费用增幅高达58.54%，远超营收增速。 很多专业人士给妙可蓝多支招，大多也围绕这两个方面。诸如如何进行品类创新，如何摆脱依赖等等。 前三季度业绩公告显示，盈利水平增长得益于两点： 1.核心奶酪业务占比进一步提升、业务结构不断优化。2.供应链效率提升和经营策略优化亦推动成本下降。 今年上半年，妙可蓝多拿下FIFA美加墨世界杯全球官方奶酪身份，签约梅西、姆巴佩、亚马尔三大球星代言。 财报显示，今年上半年销售费用率也从上年同期的17%左右升至19.3%，在乳业板块中属于“逆势上升”的少数派。 到了十月份，妙可蓝多又相继官宣独家冠名马拉松赛事和热播综艺，营销力度没有减弱的迹象。 妙可蓝多是蒙牛在奶酪赛道最重要的一张名片，把资源集中在这个品类上，符合控股股东的战略利益。","image":"https://img.36krcdn.com/hsossms/20261025/v2_83834be2ed814d858b2305ed6658c919@1743780481@ai_oswg736899oswg1053oswg495_img_png~tplv-1marlgjv7f-ai-v3:600:400:600:400:q70.jpg","points_source":"llm"},{"title":"伊利成功收购新西兰第二大乳业合作社Westland 开启“让世界共享健康”的新格局","summary":"伊利完成对新西兰第二大乳业合作社Westland的收购，标志着其在亚洲乳业的地位得到进一步巩固。这一举措不仅增强了伊利在原料供应链上的全球布局，也为中国乳企在海外市场的拓展提供了新的范例。对于跨境母婴行业的从业者而言，伊利此举意味着更稳定、高质量的婴幼儿奶粉原料供应可能成为趋势，同时，也反映出中国乳企正通过国际化战略提升自身竞争力。","source_id":"yili","source_name":"伊利","source_url":"https://www.yili.com/","original_url":"https://www.yili.com/global/oceania/1167","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:16:14+08:00","language":"zh","author":"","tags":["品牌动态","供应链","跨境电商"],"priority":"P1","score":8.0,"matched":["伊利","收购"],"id":"89924c8f884a2a73","summary_source":"llm","title_zh":"伊利收购新西兰Westland乳业合作社","translated":true,"body":"8月1日，伊利集团在新西兰奥克兰举办交割仪式，宣布旗下全资子公司香港金港商贸控股有限公司正式完成对新西兰第二大乳业合作社Westland的收购。在潘刚董事长构建“全球健康生态圈”理念的引领下，伊利的国际化布局再获重大突破，巩固了伊利亚洲乳业龙头的地位，加速提升伊利在全球乳业的影响力。 南北纬40-50°被称为世界两大“黄金奶源带”。从北半球广袤无垠的内蒙古草原，走出了亚洲第一的伊利集团；在南半球新西兰的西海岸，伊利寻找到优秀且潜力无限的Westland。 Westland是新西兰第二大乳业合作社，旗下多款产品享有较高国际知名度，畅销全球40多个国家。伊利集团于今年3月18日发布公告称收购新西兰Westland乳业100%股权。此后，在参与Westland股东磋商路演的过程中，伊利向Westland的股东们展示了自身良好的企业形象和带领Westland走向更强大未来的企业实力。7月4日，近96%的奶农股东参与了对伊利收购要约的投票，其中赞成票达93.79%。在获得奶农股东投票通过后，这项交易也相继获得新西兰海外投资办公室和新西兰高等法院的审批通过。 成功收购Westland，伊利构建起了一座横跨太平洋的“乳业桥梁”，将使伊利进一步提高整合全球优质资源的能力，为全球消费者提供更高品质的产品，满足消费者多元化需求。 （从左至右）新中贸易协会执行董事Jeff Shepherd、新西兰贸易发展局代表Mike Arand、中国驻新西兰大使馆经济商务参赞黄岳峰、伊利集团执行总裁张剑秋、伊利集团助理总裁孙东宏、Westland前董事长Pete Morrison登台参与交割仪式 伊利在国际化的进程中开拓了一条让世界共享健康的“乳业丝路”。这条“乳业丝路”让全球乳业的优质资源加速流动，让越来越多的消费者享受到伊利的高品质产品。 近年来，伊利积极响应国家“一带一路”倡议，不断拓展海外业务，在国际化方面取得颇多成果。在亚洲，伊利的产品正全面进入东南亚市场，还成功收购了泰国本土最大的冰淇淋企业Chomthana。与Chomthana完成交割后，伊利全面发挥战略协同效应，整合期一个月内，帮助Chomthana实现30%以上的产能提升。在欧洲，伊利已完成欧洲创新中心的升级，并与欧洲生命科学领域的顶尖学府瓦赫宁根大学建立合作实验室。在美洲，伊利主导实施“中美食品智慧谷”，与众多美国一流高校和研究机构展开合作。在大洋洲，伊利投入30亿人民币建设全球最大的一体化乳业基地之一——大洋洲乳业生产基地，并与新西兰林肯大学签署战略合作协议，成立大洋洲研发中心。 新西兰是伊利全球化布局的重要组成部分，大洋洲乳业生产基地运营5年多以来，与本地社区、员工、奶农及供应商，建立了良好的关系。今年6月，大洋洲乳业获得新中贸易协会颁发的跨境投资奖，这是伊利海外布局获得国际认可的表现。 伊利致力于成为全球最值得信赖的健康食品提供者。此次成功收购Westland，是品质、技术、资源、市场的完美结合，也是伊利加速“乳业丝路”产业融合的重要里程碑，开启了让世界共享健康的崭新格局。随着“乳业丝路”的延展，伊利在实现自身企业愿景的同时，将为全球乳业的共同繁荣贡献一份中国力量。","points":["收购新西兰乳业合作社","巩固亚洲乳业地位","提升中国乳企竞争力"],"points_source":"llm","summary_kind":"brief"},{"title":"伊利新西兰黄油新产线投产 为中国乳企海外最大黄油工厂","summary":"伊利旗下新西兰威士兰乳业的新产线正式投产，年产能达到4.2万吨，成为中国乳企在海外建设的最大黄油工厂。这一产线的投产不仅提升了伊利在黄油品类上的市场供应能力，也为中国消费者提供了更多元化的乳制品选择。对于跨境母婴行业的从业者来说，这意味着伊利在婴幼儿配方奶粉原料供应上的能力进一步增强，有助于满足市场对高品质黄油的需求。7月19日，伊利集团旗下新西兰威士兰乳业霍基蒂卡工厂焕新升级暨牧恩黄油（Westgold）新产线投产仪式在厂区内举行。","source_id":"yili","source_name":"伊利","source_url":"https://www.yili.com/","original_url":"https://www.yili.com/global/oceania/1166","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:16:14+08:00","language":"zh","author":"","tags":["品牌动态","质量安全","市场数据"],"priority":"P1","score":4.8,"matched":["伊利"],"id":"1e89ca8714e7a549","summary_source":"llm","title_zh":"伊利新西兰威士兰乳业新产线投产","translated":true,"body":"7月19日，伊利集团旗下新西兰威士兰乳业霍基蒂卡工厂焕新升级暨牧恩黄油（Westgold）新产线投产仪式在厂区内举行。新产线投产后，优质草饲黄油年产能实现翻倍，达到4.2万吨，成为新西兰西海岸最大黄油工厂，也是中国乳企在海外建设的最大黄油工厂。 新西兰贸易兼农业部部长达明·奥康纳出席投产仪式，伊利集团董事长兼总裁潘刚通过远程视频对新产线投产表示祝贺。伊利威士兰乳业驻地董事菅时清、伊利威士兰乳业首席执行官理查德·怀斯，以及威士兰乳业员工共同参加了投产仪式。 新产线投产，恰逢伊利并购威士兰乳业三周年，标志着在伊利集团协同支持下，威士兰乳业再次开启了新的发展篇章。 启动仪式上，达明·奥康纳表示：“伊利投资建设全新产线，将进一步推动西海岸乳业发展，帮助新西兰优质黄油走向全球。” 潘刚对新产线投产表示祝贺：“加入伊利集团以来，威士兰乳业赢得了越来越多消费者的认可。未来，威士兰乳业将为消费者、社会、员工创造更大价值。” 为满足全球消费者对高品质黄油的需求，伊利于2021年3月24日启动“Goldrush”项目，对位于新西兰西海岸的霍基蒂卡工厂进行全面升级。依托伊利强大的资金、技术、资源支持，项目建设有序推进，并顺利实现投产，产能达到预期规划。牧恩黄油不再仅是烘焙大师的专享，还将走向更多普通消费者的餐桌。 新西兰是世界主要的黄油生产国之一，在全球黄油市场具有举足轻重的地位。牧恩黄油的历史可以追溯到1893年，采用新西兰西海岸南阿尔卑斯山牧场的天然草饲奶源，坚持使用当地传统加工工艺，出产的黄油营养丰富、口感浓郁、色泽金黄，成为众多消费者的舌尖挚爱。 理查德·怀斯表示：“霍基蒂卡工厂焕新升级后，采用了世界一流的生产设备，同时，我们仍会延续传统制作工艺，让牧恩黄油始终代表新西兰黄油的最高品质。” 三年前，伊利成功收购新西兰第二大乳企威士兰乳业，从北半球的内蒙古大草原到南半球的新西兰西海岸，构建起一座横跨太平洋的“乳业桥梁”。伊利将威士兰乳业纳入全球运营体系，给予全面赋能，产量与收入实现双提升。今年上半年，威士兰乳业实现了最亮眼的业绩增长。 依托伊利全球网络，牧恩黄油已在中国、美国、日本、澳大利亚、新西兰等20多个国家和地区上市。同时，由威士兰乳业生产的伊利专业乳品——环球甄选黄油、环球甄选稀奶油也已在国内全面上市。对于威士兰乳业的美好未来，理查德·怀斯充满期待：“在伊利集团的支持下，威士兰乳业的发展让每一位员工和合作伙伴都感到振奋，我们对未来发展充满信心。”","points":["投产海外黄油新产线","年产能达4.2万吨","中国乳企最大黄油工厂","增强原料供应能力"],"points_source":"llm","summary_kind":"brief"},{"title":"伊利与奇安信达成战略合作，共筑中国乳业AI+新标杆","summary":"伊利与奇安信签署战略合作协议，双方将合作建设网络安全体系及AI安全赋能，共同打造中国乳业的AI+新标杆。这一合作将推动乳业在数字化、智能化转型方面迈出重要步伐，提升行业整体的安全防护水平。对于跨境母婴行业的从业者而言，伊利与科技企业的合作预示着乳制品生产、管理和营销将更加智能化，有助于提升产品品质和市场竞争力。8月18日，在位于内蒙古呼和浩特的伊利现代智慧健康谷，伊利集团与奇安信集团正式签署战略合作协议。","source_id":"yili","source_name":"伊利","source_url":"https://www.yili.com/","original_url":"https://www.yili.com/news/company/5279","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:16:14+08:00","language":"zh","author":"","tags":["品牌动态"],"priority":"P1","score":4.8,"matched":["伊利"],"id":"04af2f2e8f381b83","summary_source":"llm","title_zh":"伊利与奇安信达成战略合作，共筑中国乳业AI+新标杆","translated":true,"body":"8月18日，在位于内蒙古呼和浩特的伊利现代智慧健康谷，伊利集团与奇安信集团正式签署战略合作协议。双方将依托各自在乳业数智化升级与网络安全领域的领先优势，围绕网络安全体系建设、安全运营及AI安全赋能等方面展开深度合作，共同打造乳品行业“AI+安全”融合新标杆。 在伊利集团董事长兼总裁潘刚与奇安信集团董事长齐向东的共同见证下，伊利集团副总裁王晓刚、奇安信集团副总裁刘冬云代表双方签署战略合作协议。伊利集团执行总裁王维、奇安信集团助理总裁李京新出席签约仪式。 伊利集团董事长兼总裁潘刚（后排右二）与奇安信集团董事长齐向东（后排左二）共同见证双方签署战略合作协议 伊利位居全球乳业五强，连续十二年蝉联亚洲乳业第一，也是中国规模最大、产品品类最全的乳制品企业。作为中国乳业龙头，伊利全面推进“AI+乳业”的深度实践，将数智力量贯穿从牧场、工厂到消费端的全产业链，致力于为消费者打造一杯高品质的“真AI牛奶”。随着AI应用场景的激增，覆盖终端、网络、云平台及数据的全链条安全防护需求也日益凸显。 奇安信是中国企业级网络安全市场的领军者，专注于网络空间安全市场，向政府、企业用户提供新一代企业级网络安全产品和服务，在人员规模、收入规模和产品覆盖度上均位居行业第一。 此次合作，伊利将依托奇安信在安全垂域大模型、AI安全网关等领域的技术储备，共建覆盖全业务场景的AI智能化安全防护体系。双方将协同构建一体化的综合网络安全防护体系与常态化安全运营机制，针对网络攻击、数据异常等安全事件建立协同研判与分级处置的闭环模式，确保核心业务稳定运行。 同时，结合乳业全链条业务特性，双方将联合开展智能制造、数智化工厂等前沿场景中的专项技术攻关，确保业务创新与安全防护同步规划、同步建设。在海外业务拓展方面，双方也将共同推进跨境数据合规体系与隐私保护体系建设，为伊利全球化的稳健发展提供安全保障。 乳业关乎民生，此次伊利与奇安信的战略携手，不仅是伊利提升自身数智化水平的关键举措，也将安全能力深度嵌入乳业全流程，为行业数智化升级打造可参考的典范样本，引领中国乳业高质量、可持续发展。","points":["与奇安信战略合作","建设网络安全体系","推动乳业智能化转型","提升行业安全水平"],"points_source":"llm","summary_kind":"brief"},{"title":"海外大奖首设伊利创新奖 “全面价值领先”引发热议","summary":"伊利集团在“新中贸易协会中国商业大奖”颁奖典礼上荣获“伊利集团-中新贸易创新卓越奖”，这是海外大奖首次设立伊利创新奖。这一荣誉不仅彰显了伊利在创新领域的领先地位，也引发了对“全面价值领先”理念的广泛讨论。对于跨境母婴行业的从业者而言，伊利获得创新奖项意味着其在产品研发、市场策略和品牌建设等方面的成功，为行业树立了新的标杆，同时也反映出消费者对高品质、创新乳制品的日益增长的需求。","source_id":"yili","source_name":"伊利","source_url":"https://www.yili.com/","original_url":"https://www.yili.com/global/oceania/1169","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:16:14+08:00","language":"zh","author":"","tags":["品牌动态","海外动态"],"priority":"P1","score":4.8,"matched":["伊利"],"id":"fced27e2fa5916dc","summary_source":"llm","title_zh":"海外大奖首设伊利创新奖 “全面价值领先”引发热议","translated":true,"body":"近日，《中国-新西兰自由贸易协定升级议定书》正式生效，中新两国全面战略伙伴关系再上新台阶之际，两年一度的“新中贸易协会中国商业大奖”颁奖典礼在线上成功举办。“伊利集团-中新贸易创新卓越奖”正式揭晓。这是“新中贸易协会中国商业大奖”历史上，首次以中国乳企品牌进行奖项命名。 今年，新中贸易协会全新设立创新卓越奖，旨在表彰在中新双边贸易领域锐意创新、追求卓越的优秀企业。长期以来，伊利集团坚持“不创新，无未来”理念，实施创新驱动战略，构建全球智慧链，受到国际社会广泛认可。2019年，伊利大洋洲乳业曾以参赛企业身份，成功获得“新中贸易协会中国商业投资大奖”。今年，新中贸易协会特别邀请伊利担任评委和颁奖嘉宾，对众多参赛企业的创新成果进行评分。 新中贸易协会主席马丁·汤姆森（Martin Thomson），中国驻新西兰大使王小龙，新西兰贸易和出口增长部长兼农业部长达米恩·奥康纳（Hon Damien O'connor）等嘉宾出席线上颁奖仪式。 新中贸易协会成立于1981 年，致力于促进和加强中新两国的贸易和投资关系，搭建交流合作平台。协会成员来自进出口、制造、投资等各领域，以及提供相关服务的机构。 新中贸易协会主席马丁·汤姆森表示：“很高兴邀请伊利集团加入中新商业大奖评选和颁奖活动。伊利在创新领域处于全球领导地位，持续关注创新，我们很荣幸伊利在首次创立的创新类别奖中担任重要角色。” 他还表示：“通过对大洋洲乳业和威士兰乳业的投资，伊利集团为中新两国的经济发展和繁荣做出了非常积极和重要的贡献。同时，伊利致力于为新西兰当地社区创造福祉，令人赞叹。我对伊利在创新、可持续发展和社会责任领域取得的非凡成就表示祝贺。” “我看到近期伊利打造了中国食品行业首家获得认证的零碳工厂，成功支持和参与北京冬奥会和冬残奥会，并通过威士兰乳业和大洋洲乳业的合作推出面向全球市场的新品，这些都是伊利在创新领域和应对全球贸易重大挑战方面取得成就的缩影。我们期待和伊利一道，共同支持和推动中新贸易发展”。 为落实“一带一路”倡议，作为全球乳业五强、亚洲乳业第一的中国乳企，伊利不断加快国际发展步伐，以全球视角开展产业链创新合作。2014年，伊利在新西兰投资建设了全球最大的一体化乳业基地——大洋洲生产基地，刷新中新两国投资规模纪录。伊利还与新西兰林肯大学签署战略合作协议，成立大洋洲创新中心。2019年，伊利成功收购新西兰第二大乳企威士兰后，合作领域再次延伸。目前，伊利在当地的合作伙伴包括奶源供应商、创新科研机构、第三方服务机构等众多产业链上下游及国际行业合作伙伴。 在伊利集团董事长兼总裁潘刚提出的“全面价值领先”目标指引下，伊利以“全球化思维、本土化经营”的运作方式，携手新西兰产业链合作伙伴开展深度合作，为中新乳业全方位合作搭建桥梁，助力区域经贸合作健康发展。在进行产业运营的同时，伊利高度重视社会责任履行和当地社区融入，参与新西兰乳业“后备人才”培养计划、“粉红丝带”全球乳腺癌防治活动、“生命计划”筹款等公益活动，支持新西兰校园体育活动，开展保护野生三文鱼、湿地植树等环境保护行动。 目前，伊利已在亚洲、欧洲、美洲、大洋洲等乳业发达地区构建了一张覆盖全球资源体系、全球创新体系、全球市场体系的骨干大网，在全球拥有15个创新中心、74个生产基地，产品已在60多个国家和地区上市。在“全面价值领先”目标的指引下，伊利将携手全球合作伙伴共拓健康事业，用营养健康滋养生命活力，加快实现“让世界共享健康”梦想。","points":["荣获海外创新奖项","彰显创新领先地位","引发行业价值讨论"],"points_source":"llm","summary_kind":"brief"},{"title":"伊利印尼乳业生产基地投产 刷新中国乳业在东南亚投资纪录","summary":"伊利印尼乳业生产基地一期项目投产，标志着中国乳业在东南亚的投资规模达到新高度。这一举措不仅扩大了伊利在东南亚的市场份额，也促进了中国乳业的技术输出和品牌国际化。对从业者而言，这意味着需关注东南亚市场的乳制品消费趋势，把握区域市场机遇。12月10日，伊利集团在东南亚的首个自建工厂——伊利印尼乳业生产基地（以下简称“伊利印尼乳业”）举行一期项目投产仪式，标志着伊利“全球织网”再创新的里程碑。","source_id":"yili","source_name":"伊利","source_url":"https://www.yili.com/","original_url":"https://www.yili.com/global/asia/1158","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:16:14+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":4.8,"matched":["伊利"],"id":"6ddce1b04d6ff7e2","summary_source":"llm","title_zh":"伊利印尼乳业生产基地投产 刷新中国乳业在东南亚投资纪录","translated":true,"body":"12月10日，伊利集团在东南亚的首个自建工厂——伊利印尼乳业生产基地（以下简称“伊利印尼乳业”）举行一期项目投产仪式，标志着伊利“全球织网”再创新的里程碑。一期项目投资8.67亿元人民币，一、二期全部建成后可日产冰淇淋400万支，成为印尼单体规模最大的冰淇淋工厂，也是迄今为止中国乳企在东南亚建设的最大生产基地，刷新中国乳企在东南亚投资规模纪录。 印尼工业部部长阿古斯出席项目投产仪式并为生产基地揭牌，伊利集团董事长兼总裁潘刚发表视频致辞。勿加泗地区署长阿玛特、工业部工业司司长普度、投资部投资管控司司长伊玛木、西爪哇省政府劳动和移民局局长陶菲克、印尼食品饮料协会主席阿迪，勿加泗地区有关部门代表，中国国际贸易促进委员会、中国国际商会驻印度尼西亚代表处代表朱莹敏、印尼中国商会总会主席张朝阳等出席投产仪式。 阿古斯对伊利印尼乳业克服疫情挑战，顺利投产表示祝贺。阿古斯表示：“感谢潘刚先生，感谢伊利在印尼打造如此高规格的生产基地。伊利印尼乳业生产的Joyday冰淇淋将满足印尼人民对乳制品，尤其是优质冰淇淋产品日益增长的需求。我们也感谢伊利积极参与印尼学校儿童疫苗接种计划，帮助印尼政府应对疫情做出的重要贡献。” 潘刚在视频致辞中表示：“正是消费者的选择与信赖，坚定了伊利在印尼长期投资、发展的信心。伊利始终坚持高标准引领铸品质、可持续发展利长远、本土化经营惠民生，更好地服务印尼消费者，助力印尼经济社会的稳健发展。” 活动现场，伊利与印尼疫苗中心达成合作，伊利将为印尼国家疫苗接种中心建设提供支持，助力抗击疫情。 揭牌仪式后，现场嘉宾参观了伊利印尼乳业，对产业基地建设给予高度评价：“生产车间处处体现出伊利对于品质的追求。”在产品品尝区，在场嘉宾品尝了Joyday冰淇淋。阿古斯品尝后说：“Joyday冰淇淋，每一口都有惊喜！” 当前，消费需求日益个性化、多样化、差异化，如何精准判断并予以快速满足，是每个企业做大做强的必修课。在前不久，伊利集团正式发布“全面价值领先”目标，“消费者价值领先”位于四大价值领先战略目标的首要位置。 长期以来做消费者“真爱粉丝”的执着追求，推动伊利品质在国际市场获得越来越多的认可与信赖。伊利Joyday冰淇淋在印尼推出仅3年时间，印尼各地超市、便利店已随处可见Joyday的身影。 “Joyday甜美的味道、冰爽的口感，可以让我释放压力，产生愉悦的心情，每种口味我都很喜欢！”，一位热衷Joyday冰淇淋的雅加达市民说。 印尼当地媒体也报道称，伊利产品营养健康的品质、丰富独特的口味、充满活力的产品形象，深受印尼消费者的喜爱。 TanLih Ming是Joyday冰淇淋的万隆经销商，得知伊利印尼乳业正式投产运营，TanLihMing非常兴奋，他表示：“相信本地工厂投产以后，会有更多适合印尼市场的新品推出，Joyday冰淇淋会越来越受印尼消费者的喜爱。我们期待与伊利长期共同发展，让Joyday品牌在印尼市场做到最好。” 为了更好服务东南亚消费者，打造最优产品品质，伊利印尼乳业依托伊利集团全球领先的创新体系、生产体系和质量管理体系，打造更加智能、创新、开放、绿色、本土化的现代化工厂，全面带动产业链可持续发展。 同时，伊利印尼乳业作为伊利“全球织网”的重要支点，将与伊利泰国生产基地构成辐射东南亚的“双中心”，为东南亚消费者提供更多元化的产品选择。 “一带一路”建设为中国企业走出去搭建了广阔平台，中国乳企也积极探索着“全球化思维、本土化经营”的发展之路。","points":["扩大伊利在东南亚市场份额","促进中国乳业技术输出","把握区域市场机遇"],"points_source":"llm","summary_kind":"brief"},{"title":"The a2 Milk Company Advances Global Leadership in Beta-Casein Science with New Research Presented at NUTRITION 2026","summary":"a2 Milk公司在NUTRITION 2026年会上发布新研究，强化A1蛋白免费牛奶的证据基础。研究涵盖婴儿生长安全、蛋白质利用、消化耐受和肠脑轴，由普渡大学和诺瓦东南大学独立研究员主导。这一进展对跨境母婴行业意味着需关注β-酪蛋白科学进展，评估其对产品研发和市场定位的影响。","source_id":"a2milk_news","source_name":"a2 Milk·新闻","source_url":"https://thea2milkcompany.com/","original_url":"https://thea2milkcompany.com/latest-company-news/the-a2-milk-company-advances-global-leadership-in-beta-casein-science-with-new-research-presented-at-nutrition-2026","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:05:18+08:00","language":"en","author":"","tags":["品牌动态"],"priority":"P1","score":6.4,"matched":["a2","casein"],"id":"74e375cee88e4c4b","summary_source":"llm","title_zh":"a2 牛奶公司在 NUTRITION 2026 发布新研究，巩固 β-酪蛋白研究领先地位","translated":true,"body":"New research presented at NUTRITION 2026 strengthens the evidence base for A1 protein free milk The a2 Milk Company presented new clinical and preclinical research at NUTRITION 2026 , the American Society for Nutrition's annual meeting. The studies spanned infant growth and safety, protein utilisation, digestive tolerance and the gut-brain axis, and included company-funded research led independently by investigators at Purdue University and Nova Southeastern University - building on more than two decades of A1- and A2-type beta-casein science. Read the full release here: https://www.globenewswire.com/news-release/2026/07/28/3334410/0/en/the-a2-milk-company-advances-global-leadership-in-beta-casein-science-with-new-research-presented-at-nutrition-2026.html","points":["a2 Milk发布新研究","强化A1蛋白免费牛奶证据","研究涵盖婴儿生长安全等","由普渡大学等主导"],"points_source":"llm"},{"title":"Danone celebrates 200 years of evian® and opens a new chapter focused on resource preservation, industrial excellence, and innovation","summary":"达能庆祝evian®诞生200周年，宣布将聚焦资源保护、工业卓越与创新。此举体现达能对可持续发展战略的长期承诺，对母婴行业具有借鉴意义，提示企业需将环保与创新融入发展，以适应未来市场趋势。可持续发展是行业未来发展的必然方向，从业者需积极学习达能的经验，推动企业绿色转型。","source_id":"danone_news","source_name":"达能·新闻","source_url":"https://www.danone.com/media.html","original_url":"https://www.danone.com/newsroom/press-releases/evian-200-years.html","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:05:17+08:00","language":"en","author":"","tags":["政策法规","质量安全","品牌动态"],"priority":"P1","score":4.8,"matched":["danone"],"id":"631449e4965138c7","summary_source":"llm","title_zh":"依云 200 周年：达能开启水资源保护、工业能力与创新的新篇章","translated":true,"body":"Press release 5 min time reading Danone celebrates 200 years of evian® and opens a new chapter focused on resource preservation, industrial excellence, and innovation Corporate news","image":"https://smartmedia.digital4danone.com/is/image/danonecs/cover-pr-evian-200y?qlt=82&ts=1775146943999&dpr=off","summary_kind":"brief","points":["达能聚焦可持续发展"],"points_source":"llm"},{"title":"Danone positions Steenvoorde as a leading European medical nutrition site and inaugurates its largest production line in France","summary":"达能宣布将斯泰恩福尔德定位为欧洲领先医疗营养中心，并启用法国最大生产线。这一战略布局显示达能对医疗营养市场的重视，对跨境母婴行业从业者意味着需关注欧洲市场动态，把握医疗营养细分领域的发展机遇。医疗营养市场是婴幼儿奶粉行业的重要增长点，从业者需积极布局。欧洲市场是跨境母婴行业的重要战场，从业者需关注相关动态。","source_id":"danone_news","source_name":"达能·新闻","source_url":"https://www.danone.com/media.html","original_url":"https://www.danone.com/newsroom/press-releases/new-production-line-in-steenvoorde.html","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:05:17+08:00","language":"en","author":"","tags":["跨境电商","海外动态"],"priority":"P1","score":4.8,"matched":["danone"],"id":"1a4a28053cc48d8b","summary_source":"llm","title_zh":"达能将 Steenvoorde 基地打造为欧洲领先的医学营养工厂，在法国启用最大生产线","translated":true,"body":"Press release 3 min time reading Danone positions Steenvoorde as a leading European medical nutrition site and inaugurates its largest production line in France Corporate news","image":"https://smartmedia.digital4danone.com/is/image/danonecs/Biotech%20Open%20Platform-09034?qlt=82&ts=1790319673477&fit=wrap&dpr=off","summary_kind":"brief","points":["达能布局医疗营养市场","欧洲领先中心定位","启用法国最大生产线"],"points_source":"llm"},{"title":"Danone to acquire MADE Group, expanding its presence in the fast-growing healthy nutrition space in Asia Pacific","summary":"达能宣布收购MADE Group，以拓展亚太地区快速增长的健康营养市场。这一战略举措显示达能对亚太市场健康营养领域的重视，对跨境母婴行业从业者意味着需关注亚太市场动态，把握健康营养细分领域的发展机遇。亚太市场健康营养领域增长迅速，成为行业新的增长点，从业者需深入研究市场特点，制定针对性的市场策略。","source_id":"danone_news","source_name":"达能·新闻","source_url":"https://www.danone.com/media.html","original_url":"https://www.danone.com/newsroom/press-releases/made-acquisition.html","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:05:17+08:00","language":"en","author":"","tags":["市场数据","跨境电商","品牌动态"],"priority":"P1","score":4.8,"matched":["danone"],"id":"10da3538190563a1","summary_source":"llm","title_zh":"达能收购 MADE Group，加码亚太健康营养市场","translated":true,"body":"Press release 7 min time reading Danone to acquire MADE Group, expanding its presence in the fast-growing healthy nutrition space in Asia Pacific Corporate news","image":"https://smartmedia.digital4danone.com/is/image/danonecs/cocobella-header?qlt=82&ts=1782075688107&dpr=off","summary_kind":"brief","points":["达能收购MADE Group","拓展亚太健康营养市场","显示达能对亚太市场的重视","需关注亚太市场动态"],"points_source":"llm"},{"title":"中国首个功能酸奶出海，蒙牛冠益乳全球化战略再下一局","summary":"蒙牛冠益乳旗下200g低温酸奶即将登陆港澳和新加坡市场，标志着其国际化战略迈出关键一步。这一举措对行业全球化布局有示范意义。从业者需关注国际市场动态，探索跨境发展机遇。作为创立20载，获批“健字号”已达16年之久的功能酸奶领军品牌，冠益乳此举在表面上看，是将蒙牛出海的业务板块扩展到低温酸奶，标志着其国际化战略迈出关键一步；","source_id":"foodaily","source_name":"Foodaily 每日食品","source_url":"https://www.foodaily.com/","original_url":"https://www.foodaily.com/articles/42477","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:05:12+08:00","language":"zh","author":"","tags":["品牌动态","海外动态"],"priority":"P1","score":4.8,"matched":["蒙牛"],"id":"eddc6f9a94261511","summary_source":"llm","title_zh":"中国首个功能酸奶出海，蒙牛冠益乳全球化战略再下一局","translated":true,"body":"最近，Foodaily关注到，冠益乳旗下200g低温酸奶即将登陆港澳和新加坡市场。 作为创立20载，获批“健字号”已达16年之久的功能酸奶领军品牌，冠益乳此举在表面上看，是将蒙牛出海的业务板块扩展到低温酸奶，标志着其国际化战略迈出关键一步；在更深层意义上，我们也在思考，它能否为中国乳制品出海打下一个样板？ Foodaily注意到，过去数年，蒙牛旗下已有多个子品牌出海，此次冠益乳加入出海军团，蒙牛都做了哪些准备？面对法规环境迥异的新市场，冠益乳如何彰显多年积累起的品质实力？此次出海对蒙牛和中国乳业，又意味着什么？ 众所周知，低温酸奶要保持益生菌活性，现有工艺条件下货架期通常仅为21-28天，配送半径有限。冷链与时间制约，使得低温酸奶出海面临着比常温品类更大的挑战。 Foodaily了解到，冠益乳出海产品依托日臻完善的高速货运线路与绿色通关体系，运输到港澳，再加上分货环节，大概在3天左右完成，产品的剩余保质期完全支持当地零售。 香港、澳门、新加坡，区位优势明显，商业发达，来自各地的低温乳制品种类繁多。想要在这里站稳脚跟，就必须具备足够差异化的产品卖点。 在香港，主流渠道冷柜里常见主打新鲜的本地酸奶、进口的希腊酸奶和冰岛酸奶，功能指向则以运动营养、体重管理为主，聚焦“肠道健康+免疫力提升”的并不多见。 冠益乳本次出海酸奶保留了国内健字号酸奶的同源配方、双功能内核。其独有的功能特质，恰是港澳新乳品市场上的稀缺概念。当地居民浓厚的健康饮食意识与强消费能力，也为冠益乳扎根提供了沃土。 Foodaily同时注意到，由于内地与港澳、新加坡的食品法规体系迥异，冠益乳此次出海产品的包装及健康宣称表述，将全部遵循当地法规做适配处理。 冠益乳此次出海，复用了蒙牛其他品牌之前开拓的销售网点，如香港的7-Eleven，澳门的新苗和来来，新加坡的NTUC FairPrice，均是各地渗透最广、冷链最成熟、即饮酸奶动销最快的渠道。 比如新加坡“国民信任品牌”NTUC FairPrice，拥有230余家门店，类型覆盖超市、量贩店、加油站点、便利店，能链接到各类型消费者，目前已成为内地乳企进军新加坡的必选渠道。 最后一点，如前所述，蒙牛旗下多个品牌在数年前进入港澳和新加坡，为冠益乳出海积累了宝贵经验。 包括对当地法规的理解、入关路径的优化、选择合适的渠道，以及早期的市场教育。从可以查到的诸多当地媒体报道中，也能够看到蒙牛品牌力在民众心中逐年提升。 冠益乳出海，为蒙牛运作多年的出海战略增添了浓墨一笔。而当我们站在整个低温酸奶赛道上注视它，又是怎样的一幅图景呢？","image":"https://cdn.img.foodaily.com/images/articles/2026/10/23/1792726206_nKbGUvsDM0psGoHa.jpg","points":["蒙牛冠益乳酸奶出海","登陆港澳和新加坡市场","国际化战略迈出关键一步"],"points_source":"llm","summary_kind":"brief"},{"title":"不讲奶源，这家乳企如何活到现在？","summary":"调查显示82.7%消费者购买乳品时会研究配料表，对成分敏感。这一趋势对乳企提出更高要求，需透明化产品信息，强化原料供应链管理，满足消费者对安全健康的需求，以增强市场竞争力。母婴行业从业者需关注消费偏好变化，优化产品策略。据《BMC Public Health》2023年发表的一项调研，82.7%的受访者会在购买乳制品时，研究一下配料表。单瓶售价高达48元的“冰博克”则是其中第一款被真正“卖好”的产品。","source_id":"foodaily","source_name":"Foodaily 每日食品","source_url":"https://www.foodaily.com/","original_url":"https://www.foodaily.com/articles/42474","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:05:12+08:00","language":"zh","author":"","tags":["供应链"],"priority":"P1","score":4.8,"matched":["奶源"],"id":"32f40fbb500f4733","summary_source":"llm","title_zh":"不讲奶源，这家乳企如何活到现在？","translated":true,"body":"这些年，买牛奶成了一门技术活儿。据《BMC Public Health》2023年发表的一项调研，82.7%的受访者会在购买乳制品时，研究一下配料表。 而在中国，消费者对乳品成分的敏感导火索是2008年的三聚氰胺事件。这场风波让消费者不再迷信广告，转而关注产品本身。 为了重新赢得消费者信任，乳企纷纷在奶源上下功夫。传统巨头加码牧场，引进“牛中贵族”娟姗牛支撑营养指标，新兴品牌则争夺叙事权：朝日唯品讲循环农场与土壤有机，认养一头牛用自建牧场、私域认养、“听音乐、做SPA”的拟人化故事，将养殖方式变成差异卖点。 在奶源叙事的另一端，一个名为提纯乳的品类开始兴起。单瓶售价高达48元的“冰博克”则是其中第一款被真正“卖好”的产品。它背后的必如，也是一个反常规的乳企样本： 自 2015年成立， 必如 在传统货架上几乎“查无此人”，远离商超与新零售，却活到了今天 。 过去20年，高端液奶擅长讲“奶源故事”。A2讲奶牛基因，有机讲牧场认证。逻辑一样：从奶源出发，用稀缺性撑溢价。 价格体系最先松动。以沃尔玛自有品牌“沃集鲜”为例，其有机A2鲜牛奶，1升仅售12.9元；部分有机A2鲜牛奶和高端纯牛奶打折频繁，降价幅度在30%—50%之间。消费者逐渐发现，同样是一升装，售价30元以上的高端奶与10元左右的平价奶，味道和营养差距并没有价格差距那么大。 但是牛奶本质上是农产品，决定其风味与营养的蛋白质、乳脂含量有生理天花板。据密歇根州立大学资料，奶牛日粮蛋白质每提高1%，牛奶蛋白质大约只增加0.02%；“牛中贵族”娟姗牛，原奶乳蛋白达到3.8g/100mL，就算十分努力了。 下游要高蛋白，上游却不能稳定给出，2008年的三聚氰胺事件，正是这种失衡的产物。蛋白含量一直是原奶收购的核心指标，但当时国内奶牛养殖以散户为主，原奶蛋白普遍在2.95%的收购红线上下挣扎。为了跨过这道红线，一些散户与奶站开始“各显神通”：轻则在挤奶前对奶牛短时间断水限水，重则用高蛋白精料“揠苗助长”强行催高指标，压榨奶牛生理极限。同时，规则漏洞被无限放大，原先的凯氏定氮法并不直接测算蛋白质本身，而是通过测量总氮量来推算蛋白含量。含氮量高达66%的三聚氰胺，成了个别奶站蒙混过关的“捷径”，这场人祸最终重创了中国乳业。 而真正从根源终结“唯蛋白”内卷的，是一种全新的“做奶”方式： 必如冰博克所使用的膜过滤工艺 。 简单来说，膜过滤就像一个极其精密的“筛子”：通过物理过筛，在低温下精准截留蛋白质与脂肪，让水和乳糖等小分子自由透过。无需在配料表里添加任何人工成分，就能将牛奶蛋白轻松浓缩至4.0g/100ml以上，顺便滤掉体细胞、杂质与部分微生物。 这项工艺最早应用于水处理和制药，近年才在乳品中大面积使用。2009年一项公开专利记载：1000升蛋白质含量3.4%的脱脂乳，经超滤可得到700升蛋白质含量5%的浓缩乳。 这意味着，牛奶好不好喝、蛋白够不够高，不再单由奶牛决定， 乳企自己就 可量化、可控制。 “养好奶”和“做浓奶”被拆成了两件事，三聚氰胺式的基础漏洞被堵住了。 踩中高营养与清洁标签的提纯乳（超滤奶），正在美国这一先行市场逆势爆发。如今，全球消费者正在对虚无缥缈的营销叙事脱敏——大家不再满足于包装袋上花哨的概念，而是回归最朴素的理性和体感： 高蛋白质、真营养以及舌尖上骗不了人的好味道，才是决定购买与复购的硬品质。 Circana数据显示，尽管超滤奶目前仅占美国牛奶总销售额的约7%，却贡献了14.8%的销售额增长与5.5%的销量增长。 不过，再好的技术只有落进具体场景，才会创造价值。在必如掌握这一技术并加码膜过滤产线时，下游新需求的裂缝还在扩大。 2018年，必如走访咖啡馆，发现咖啡师在“手搓”提纯乳——先将普通牛奶冷冻，再缓慢解冻，只取最先流出的浓缩部分。整个过程至少8小时，损耗大，浓度还难稳定。","image":"https://cdn.img.foodaily.com/images/articles/2026/10/22/1792605432_HcrF5DV4AUb42MT3.png","points":["消费者关注配料表","乳企需透明化信息"],"points_source":"llm","summary_kind":"brief"},{"title":"四部门联合调查组发布婴幼儿纸尿裤甲酰胺 问题核查情况通报","summary":"联合调查组对168家婴幼儿纸尿裤企业抽检，未检出甲酰胺，但发现部分检测机构存在检测问题。调查结果证实无健康危害，但强调检测需严谨。从业者需关注权威检测结果，加强产品检测合规性，同时警惕不实信息对行业的负面影响。联合调查组对国内168家婴幼儿纸尿裤生产企业（含代工企业）进行全面抽检，包含180个品牌368批次纸尿裤成品样品，委托中国疾病预防控制中心、中国质量检验检测科学研究院等权威机构进行检测，未检出甲酰胺。","source_id":"samr_cn","source_name":"市场监管总局","source_url":"https://www.samr.gov.cn/","original_url":"https://www.samr.gov.cn/xw/mtjj/art/2026/art_15ceb2418b0945919c42271aa772fff9.html","published_at":"","published_guessed":true,"fetched_at":"2026-10-25T12:05:12+08:00","language":"zh","author":"","tags":["质量安全","品牌动态"],"priority":"P1","score":9.6,"matched":["婴幼儿","通报"],"id":"795b7be99cdde7a3","summary_source":"llm","title_zh":"四部门联合调查组发布婴幼儿纸尿裤甲酰胺 问题核查情况通报","translated":true,"body":"国家市场监督管理总局10月15日通报，针对近段时间舆情反映的婴幼儿纸尿裤甲酰胺问题，市场监管总局、工业和信息化部、国家卫生健康委、国家疾控局成立联合调查组，坚持实事求是，认真核实线索，全面深入开展调查工作。 联合调查组对国内168家婴幼儿纸尿裤生产企业（含代工企业）进行全面抽检，包含180个品牌368批次纸尿裤成品样品，委托中国疾病预防控制中心、中国质量检验检测科学研究院等权威机构进行检测，未检出甲酰胺。受检企业均符合消毒产品生产卫生规范要求，未发现生产工艺及原材料中存在添加或含有甲酰胺的情况。经调查核实，舆情涉及的宣称在婴幼儿纸尿裤中检出甲酰胺的多家检测主体，存在定性原则不明确、未开展空白样和平行样检测、检测过程及判定依据不严谨、删除原始数据等问题，无法得出检出甲酰胺的结论。 与此同时，联合调查组委托国家卫生健康委临床检验中心、中国疾病预防控制中心、中国医科大学附属第一医院、北京协和医院等单位院士、专家多次论证和验证形成血液样本甲酰胺检测方法，并用该方法对舆情关注的某机构检测的血液样本进行复检，未检出甲酰胺。根据目前调查和检测结果，未发现婴幼儿纸尿裤带来的甲酰胺相关健康危害。 婴幼儿纸尿裤甲酰胺检测是严肃、专业的检验检测活动，甲酰胺相关健康危害更需要审慎客观地开展研究。有关部门将继续加强婴幼儿用品监管，欢迎社会各界积极参与，共同营造安全放心的消费环境。","points":["部分检测机构问题"],"points_source":"llm"},{"title":"纸尿裤风波之下承接竞品客流，这一知名纸尿裤品牌三季度销售额涨近50%","summary":"在纸尿裤行业风波中，某知名品牌通过承接竞争对手流失的客流，实现三季度销售额大幅增长近50%。这一增长反映出消费者对可靠品牌的持续需求。对行业从业者而言，这意味着市场机会与竞争加剧并存，需关注品牌信誉与市场应变能力，把握消费者对稳定品牌的信任心理，及时调整经营策略以应对市场变化。当地时间10月22日，全球最大的日化企业宝洁发布2027财年第一季度（即2026年7月至9月）业绩。","source_id":"gnews_cn_baby_category","source_name":"每日经济新闻","source_url":"https://news.google.com/rss/search?q=%28%E7%BA%B8%E5%B0%BF%E8%A3%A4%20OR%20%E8%BE%85%E9%A3%9F%20OR%20%E5%A5%B6%E7%93%B6%20OR%20%E6%B9%BF%E5%B7%BE%20OR%20%E6%AF%8D%E5%A9%B4%E7%94%A8%E5%93%81%20OR%20%E7%AB%A5%E8%A3%85%20OR%20%E5%A9%B4%E5%84%BF%E8%BD%A6%29%20when%3A30d&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.nbd.com.cn/articles/2026-10-24/4616072.html","published_at":"2026-10-24T13:33:00+08:00","published_guessed":false,"fetched_at":"2026-10-28T12:06:48+08:00","language":"zh","author":"","tags":["品牌动态","市场数据","跨境电商"],"priority":"P1","score":8.0,"matched":["纸尿裤","销售额"],"id":"b62a9f20c62a29cd","title_zh":"纸尿裤风波之下承接竞品客流，这一知名纸尿裤品牌三季度销售额涨近50%","summary_source":"llm","summary_kind":"brief","points":["品牌承接竞品客流","三季度销售额增近50%","反映消费者对可靠品牌需求","提示市场机会与竞争加剧"],"points_source":"llm","translated":true,"link_resolved":true,"body":"当地时间10月22日，全球最大的日化企业宝洁发布2027财年第一季度（即2026年7月至9月）业绩。该季度宝洁全球实现销售额233亿美元（约合人民币1554亿元），同比增长4%。 在当天举行的业绩说明会上，宝洁CFO（首席财务官） Andre Schulten表示：“大中华区有机销售额增长8%，在依然充满挑战的消费环境中继续保持强劲增长。 帮宝适与SK-II引领了这一增长，其中帮宝适增长近50%。 ” 《每日经济新闻》记者注意到，作为国内主流纸尿裤品牌的帮宝适，其增长主要来自行业“黑天鹅”事件带来的被动获益。今年6月，国内掀起纸尿裤甲酰胺疑云， 帮宝适品牌未被点名，成为不少焦虑宝妈的选择，得以加速增长。 “受到市场竞争格局的影响，消费者大量尝试帮宝适产品。”Andre Schulten说。 不过，随着近日调查结果公布，国内全部168家婴幼儿纸尿裤生产企业的产品均未检出甲酰胺，涉事品牌正在尝试挽回声誉和份额，帮宝适短期的高增长能否持续，还有待观察。 “本季度中国帮宝适销售额增长接近50%，这主要得益于短期内的竞争态势变化。”Andre Schulten表示。 今年6月，好奇、Babycare、碧芭宝贝三个品牌被指存在有毒物质甲酰胺。10月15日，市场监管总局等四部门联合调查组发布通报，无论是对国内全部168家婴幼儿纸尿裤生产企业的全面抽检，还是对涉事博主检测剩余样品、封存血液样本的复检，均未检出甲酰胺。 而在调查期间，帮宝适成为被动的获益者，它通过承接上述品牌流失的客户，实现加速增长。 Andre Schulten表示：“我们在中国的婴儿护理品类增速一直保持在20%左右，而今年第一财季的增长率已接近50%。这显然受到市场竞争格局的影响，（纸尿裤甲酰胺风波）促使消费者大量尝试帮宝适产品。中国团队在应对这个试用热潮方面，表现非常出色，并且能够持续留住这些用户。” 记者注意到，随着近期调查结果公布，中国纸尿裤行业正在经历一场信任重建。头部品牌集体把品控从后台推到前台，如开放参观产线、展开全链路常态化检测、公示溯源信息、设立公众检测监督基金及专家监督等，行业发展即将回归正轨。 最近，多个品牌数月来积攒的销售需求也得到释放：10月20日晚，天猫“双11”正式开售2个多小时，Babycare店铺销售额破亿元，冲至天猫母婴亲子行业店铺TOP1。抖音电商数据显示，“双11”首日，好奇纸尿裤GMV（商品交易总额）同比增长超100%，多个品牌直播间位列婴童纸尿裤榜单前列。 因此，竞品的触底反弹，来势汹汹，也意味着帮宝适的高增长未必可持续。或许是意识到这一点，Andre Schulten补充道：“该事件对大中华区业绩的增长贡献大约是3个百分点。如果剔除这部分影响，中国市场的增长率为5%，与往常一样是中等个位数水平。” “中国业务已连续六个季度保持强劲增长。究其原因，我认为，在新冠疫情之后，中国团队率先意识到其所在市场的格局已发生根本性变化——从强劲的消费需求转向市场萎缩。业务各环节均向数字化与社交化方向转型，零售商互动模式也发生显著改变，传统的分销体系已不再适用。”Andre Schulten如此评价。 他说，中国团队全面调整了商业生态中的每个环节，彻底重构分销网络，构建以社交为核心的营销体系，打造能够驾驭社交销售渠道、线上零售商及线下实体运营的执行机制，同时强化线下实体业务的执行力，并加强创新引擎的建设。 “综合来看，这些因素共同造就了一支装备精良、表现卓越的团队，该团队已连续六个季度实现销售增长，目前第一财季销售额增长率已达8%，产品销量增长率为5%。”具体到品牌和品类，Andre Schulten分析道，中国的SK-II品牌销售额增长了13%，衣物护理品类增长5%，女性护理品类增长9%，护发品类也在上升。","image":"https://static.nbd.com.cn/images/nbd_v5/item.png"},{"title":"美赞臣安全吗？奶源、生产、质检多维度客观解析 - 新京报","summary":"新京报从奶源、生产及质检多维度解析美赞臣安全性，为消费者提供客观参考。对从业者而言，需关注奶源与生产环节的严格把控，以提升产品安全性和市场竞争力。我国从2016年开始实施婴幼儿配方乳粉产品配方注册制度，按照《婴幼儿配方乳粉产品配方注册管理办法》要求，所有在境内生产、销售以及进口的婴配乳粉，配方都要经过国家市场监督管理总局的审评注册。","source_id":"gnews_cn_policy","source_name":"Google News·配方注册与监管（中文）","source_url":"https://news.google.com/rss/search?q=%E5%A9%B4%E5%B9%BC%E5%84%BF%E9%85%8D%E6%96%B9%E4%B9%B3%E7%B2%89%20(%E6%B3%A8%E5%86%8C%20OR%20%E5%9B%BD%E6%A0%87%20OR%20%E6%96%B0%E8%A7%84%20OR%20%E7%9B%91%E7%AE%A1%20OR%20%E6%8A%BD%E6%A3%80)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.bjnews.com.cn/detail/1792814291129302.html","published_at":"2026-10-24T11:58:00+08:00","published_guessed":false,"fetched_at":"2026-10-26T08:24:46+08:00","language":"zh","author":"","tags":["供应链","政策法规"],"priority":"P0","score":4.8,"matched":["奶源"],"id":"284e3697647d4e15","title_zh":"美赞臣安全吗？奶源、生产、质检多维度客观解析","summary_source":"llm","translated":true,"link_resolved":true,"body":"早前家长选购婴幼儿配方奶粉时，核心关注的是“这款奶粉能不能适配我家孩子”“营养全不全面”这类问题。如今除了这些传统考量外，更多家长开始担忧更核心的问题：奶粉本身安不安全？质检有没有达标？这类担忧并非没有依据。婴幼儿配方奶粉是0-36月龄婴儿母乳不足时的核心营养补充来源，品质关系到孩子的生长发育与健康，因此婴配乳粉也是国内所有食品品类中监管等级最高的品类。我国从2016年开始实施婴幼儿配方乳粉产品配方注册制度，按照《婴幼儿配方乳粉产品配方注册管理办法》要求，所有在境内生产、销售以及进口的婴配乳粉，配方都要经过国家市场监督管理总局的审评注册。申请企业必须具备对应婴配乳粉的研发、生产、检验能力，符合粉状婴幼儿配方食品良好生产规范（GMP）要求，落地危害分析与关键控制点（HACCP）体系，且要对出厂产品按照法律法规与食品安全国家标准要求逐批检验。 面对市面上品类繁多的奶粉品牌，家长选购时具体要核对哪些内容？结合国家市场监督管理总局发布的“四要两不要”消费提示，选购时可参考以下标准： 美赞臣作为拥有百年历史的国际品牌，是很多家长选奶时的优先考虑项，但在最终决定前，大家难免会好奇美赞臣的品质到底怎么样、质检是否达标。以下将从奶源地、供应链体系、生产管控、检测标准、近期质检表现、个体适用性提醒六个维度展开客观分析。 美赞臣全系列产品均采用100%进口优质奶源，从供应商资质审核、原材料采购检验，到出口国与入境国的双重海关检测，全流程层层把关。以蓝臻系列为例，其奶源来自荷兰，生产基地也设在荷兰，为原罐原装进口产品。 一罐婴配奶粉包含乳糖、乳清蛋白、DHA、维生素等二三十种原料，背后涉及数十家上游供应商，原料端的稳定性是产品品质持续可靠的核心基础。美赞臣搭建了严苛且长期稳定的全球供应链体系，旗下旗舰产品蓝臻婴幼儿配方奶粉中，超过半数的核心原料供应商合作时长超过20年。每一批原料进入美赞臣中国供应链体系，都要经过成分安全筛查、品质稳定性验证、营养成分有效性测试、配方适配性校验等一系列严格审查，不达标的原料一律不予准入。和行业内不少受成本波动影响频繁更换供应商的企业不同，美赞臣长期维持核心原料供应合作关系，既避免了供应商更迭带来的品质波动风险，也通过长期深度绑定推动供应商同步提升品质标准。成本管控与供应稳定是行业面临的矛盾，能维持10年以上核心原料供应合作的企业较少，这份长期稳定的供应链能力，背后是百年品牌的综合实力与品质优先的价值导向支撑。 美赞臣在中国与荷兰的两大工厂执行统一的质量标准，其广州生产基地在设立初期就按照制药行业的GMP标准做厂房设计与质量管理，覆盖微生物控制、员工生产行为规范、环境监控等多个环节。管理机制上，美赞臣设置独立的质量管理系统，该部门不隶属于生产板块，仅对产品质量负责，实行“质量一票否决制”。2019年起，美赞臣中国通过HACCP2.0项目落地食品安全体系（FSSC22000），执行13项新的食品安全标准。在食品安全主体责任落实层面，2024年10月在北京举办的、由国家市场监督管理总局食品协调司指导、中国标准出版社主办的食品安全总监落实企业食品安全主体责任经验交流会上，发布了首批25个“企业落实食品安全主体责任创新实践典型案例”，美赞臣中国凭借全链路食品安全管理体系入选，是广东省内获此荣誉的企业代表。其广州生产基地通过落实“一责、两员、三管控”机制（落实食品安全主体责任，配备食品安全总监和食品安全员，执行日管控、周排查、月调度风险管控），对照《食品安全风险管控清单》持续优化风险防控条目，推动生产端风险防控精细化，相关实践已经作为行业创新经验推广。 美赞臣从原材料进厂到成品出厂，要经过多道检测工序，检测项目覆盖营养成分含量、微生物指标、重金属含量等多个维度，只有符合相关标准与规定的产品才会流入市场。以蓝臻为例，消费者可以通过防伪追溯平台查询每罐奶粉在荷兰生产基地的生产时间、欧盟出具的标准质检报告书编号、中国入境货物检验检疫证明原文、产品从荷兰到中国境内的全链路物流信息等内容。 从公开的抽检信息来看，美赞臣产品近年的多次监督抽检结果均为合格，旗下旗舰产品蓝臻的质检表现尤其突出，依托贯穿研发、生产到出厂的全维度检测体系，持续保持稳定的高品质水准。国内监管层面，美赞臣蓝臻已经顺利通过婴幼儿配方奶粉新国标注册，在国家市场监督管理总局组织的全国性抽检中多次获评合格，各项指标均符合国家安全标准。2025年5月，深圳市市场监督管理局大鹏监管局联合惠氏、美赞臣开展婴幼儿配方奶粉专项检查行动，美赞臣旗下包括蓝臻在内的全品类产品均符合监管规范要求。国际层面，2025年3月美国FDA与消费者组织发布的《婴儿配方奶粉中砷、铅、PFAS、BPA、丙烯酰胺检测报告》中，美赞臣Enfamil系列5款产品均未检出相关毒物，其全球统一的制药级质控标准得到权威验证。","image":"https://media.bjnews.com.cn/column/2025/09/18/5632803906217124542.jpg","points":["新京报解析美赞臣奶源、生产、质检","为消费者提供客观参考","需关注奶源与生产环节严格把控","提升产品安全性与市场竞争力"],"points_source":"llm"},{"title":"美赞臣安全吗？奶源、生产、质检多维度客观解析 - 新京报","summary":"美赞臣采用100%进口优质奶源，供应链体系稳定，生产管控严格，检测标准高。其蓝臻系列奶源来自荷兰，生产基地也在荷兰。对从业者而言，需关注国际品牌的质量安全标准及供应链稳定性。我国从2016年开始实施婴幼儿配方乳粉产品配方注册制度，按照《婴幼儿配方乳粉产品配方注册管理办法》要求，所有在境内生产、销售以及进口的婴配乳粉，配方都要经过国家市场监督管理总局的审评注册。","source_id":"gnews_cn_brand_news","source_name":"Google News·奶粉品牌动向（中文）","source_url":"https://news.google.com/rss/search?q=%E5%A5%B6%E7%B2%89%20%28%E9%A3%9E%E9%B9%A4%20OR%20%E4%BC%8A%E5%88%A9%20OR%20%E5%90%9B%E4%B9%90%E5%AE%9D%20OR%20%E8%BE%BE%E8%83%BD%20OR%20%E9%9B%80%E5%B7%A2%20OR%20%E7%BE%8E%E8%B5%9E%E8%87%A3%20OR%20%E6%83%A0%E6%B0%8F%20OR%20%E9%9B%85%E5%9F%B9%20OR%20%E6%BE%B3%E4%BC%98%20OR%20%E8%B4%9D%E5%9B%A0%E7%BE%8E%29&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://m.bjnews.com.cn/detail/1792814291129302.html","published_at":"2026-10-24T11:58:00+08:00","published_guessed":false,"fetched_at":"2026-10-27T21:08:06+08:00","language":"zh","author":"","tags":["质量安全","品牌动态","供应链"],"priority":"P0","score":4.8,"matched":["奶源"],"id":"a1a4b5ea7f299470","title_zh":"美赞臣奶粉安全性多维度解析","summary_source":"llm","summary_kind":"brief","translated":true,"link_resolved":true,"points":["解析美赞臣奶粉安全性","了解质量控制水平"],"points_source":"llm","body":"早前家长选购婴幼儿配方奶粉时，核心关注的是“这款奶粉能不能适配我家孩子”“营养全不全面”这类问题。如今除了这些传统考量外，更多家长开始担忧更核心的问题：奶粉本身安不安全？质检有没有达标？这类担忧并非没有依据。婴幼儿配方奶粉是0-36月龄婴儿母乳不足时的核心营养补充来源，品质关系到孩子的生长发育与健康，因此婴配乳粉也是国内所有食品品类中监管等级最高的品类。我国从2016年开始实施婴幼儿配方乳粉产品配方注册制度，按照《婴幼儿配方乳粉产品配方注册管理办法》要求，所有在境内生产、销售以及进口的婴配乳粉，配方都要经过国家市场监督管理总局的审评注册。申请企业必须具备对应婴配乳粉的研发、生产、检验能力，符合粉状婴幼儿配方食品良好生产规范（GMP）要求，落地危害分析与关键控制点（HACCP）体系，且要对出厂产品按照法律法规与食品安全国家标准要求逐批检验。 面对市面上品类繁多的奶粉品牌，家长选购时具体要核对哪些内容？结合国家市场监督管理总局发布的“四要两不要”消费提示，选购时可参考以下标准： 美赞臣作为拥有百年历史的国际品牌，是很多家长选奶时的优先考虑项，但在最终决定前，大家难免会好奇美赞臣的品质到底怎么样、质检是否达标。以下将从奶源地、供应链体系、生产管控、检测标准、近期质检表现、个体适用性提醒六个维度展开客观分析。 美赞臣全系列产品均采用100%进口优质奶源，从供应商资质审核、原材料采购检验，到出口国与入境国的双重海关检测，全流程层层把关。以蓝臻系列为例，其奶源来自荷兰，生产基地也设在荷兰，为原罐原装进口产品。 一罐婴配奶粉包含乳糖、乳清蛋白、DHA、维生素等二三十种原料，背后涉及数十家上游供应商，原料端的稳定性是产品品质持续可靠的核心基础。美赞臣搭建了严苛且长期稳定的全球供应链体系，旗下旗舰产品蓝臻婴幼儿配方奶粉中，超过半数的核心原料供应商合作时长超过20年。每一批原料进入美赞臣中国供应链体系，都要经过成分安全筛查、品质稳定性验证、营养成分有效性测试、配方适配性校验等一系列严格审查，不达标的原料一律不予准入。和行业内不少受成本波动影响频繁更换供应商的企业不同，美赞臣长期维持核心原料供应合作关系，既避免了供应商更迭带来的品质波动风险，也通过长期深度绑定推动供应商同步提升品质标准。成本管控与供应稳定是行业面临的矛盾，能维持10年以上核心原料供应合作的企业较少，这份长期稳定的供应链能力，背后是百年品牌的综合实力与品质优先的价值导向支撑。 美赞臣在中国与荷兰的两大工厂执行统一的质量标准，其广州生产基地在设立初期就按照制药行业的GMP标准做厂房设计与质量管理，覆盖微生物控制、员工生产行为规范、环境监控等多个环节。管理机制上，美赞臣设置独立的质量管理系统，该部门不隶属于生产板块，仅对产品质量负责，实行“质量一票否决制”。2019年起，美赞臣中国通过HACCP2.0项目落地食品安全体系（FSSC22000），执行13项新的食品安全标准。在食品安全主体责任落实层面，2024年10月在北京举办的、由国家市场监督管理总局食品协调司指导、中国标准出版社主办的食品安全总监落实企业食品安全主体责任经验交流会上，发布了首批25个“企业落实食品安全主体责任创新实践典型案例”，美赞臣中国凭借全链路食品安全管理体系入选，是广东省内获此荣誉的企业代表。其广州生产基地通过落实“一责、两员、三管控”机制（落实食品安全主体责任，配备食品安全总监和食品安全员，执行日管控、周排查、月调度风险管控），对照《食品安全风险管控清单》持续优化风险防控条目，推动生产端风险防控精细化，相关实践已经作为行业创新经验推广。 美赞臣从原材料进厂到成品出厂，要经过多道检测工序，检测项目覆盖营养成分含量、微生物指标、重金属含量等多个维度，只有符合相关标准与规定的产品才会流入市场。以蓝臻为例，消费者可以通过防伪追溯平台查询每罐奶粉在荷兰生产基地的生产时间、欧盟出具的标准质检报告书编号、中国入境货物检验检疫证明原文、产品从荷兰到中国境内的全链路物流信息等内容。 从公开的抽检信息来看，美赞臣产品近年的多次监督抽检结果均为合格，旗下旗舰产品蓝臻的质检表现尤其突出，依托贯穿研发、生产到出厂的全维度检测体系，持续保持稳定的高品质水准。国内监管层面，美赞臣蓝臻已经顺利通过婴幼儿配方奶粉新国标注册，在国家市场监督管理总局组织的全国性抽检中多次获评合格，各项指标均符合国家安全标准。2025年5月，深圳市市场监督管理局大鹏监管局联合惠氏、美赞臣开展婴幼儿配方奶粉专项检查行动，美赞臣旗下包括蓝臻在内的全品类产品均符合监管规范要求。国际层面，2025年3月美国FDA与消费者组织发布的《婴儿配方奶粉中砷、铅、PFAS、BPA、丙烯酰胺检测报告》中，美赞臣Enfamil系列5款产品均未检出相关毒物，其全球统一的制药级质控标准得到权威验证。 这是所有家长都需要明确的核心认知：“合格”与“适合”是两个不同的概念。合格指的是产品在营养成分、安全性指标、标签标识等方面达到了国家法律法规的强制要求，是产品上市销售的最低门槛。适合指的是宝宝的个体消化系统、过敏体质、味觉偏好等与该配方适配，属于个性化体验，无法用“合格”的标准统一判定。家长选奶后可以从以下几个方面观察适配性： 接受程度：宝宝是否愿意接受该奶粉的口味。如果出现以上不适应的症状，即便这款奶粉属于“抽检合格”的大品牌产品，也要暂停食用并咨询儿科医生，考虑更换配方。没有任何一款奶粉能保证100%适配所有婴儿的体质。 Q1：美赞臣奶粉符合中国国家标准吗？A：在中国境内正规渠道销售的美赞臣婴幼儿配方奶粉，均标注“国食注字”编号，通过国家配方注册，符合GB10765-2021、GB10767-2021等食品安全国家标准。","image":"https://media.bjnews.com.cn/xn/2026/10/24/6adc263d883051130056adc263d88302.png"},{"title":"MARKET CLOSE: NZ shares rise ahead of final election results; Synlait, A2, Fonterra drop - BusinessDesk","summary":"新西兰股市在最终选举结果公布前上涨，Synlait、A2、Fonterra等乳企股价下跌。这一市场波动反映了投资者对乳业公司未来业绩的预期变化。对跨境母婴行业从业者而言，需密切关注新西兰乳业市场动态，特别是主要乳企的股价变化可能预示着行业竞争格局和供应链成本的未来走向。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.businessdesk.co.nz/news/market-close-nz-shares-rise-ahead-of-final-election-results-synlait-a2-fonterra-drop/JSNAELTA3BNRFC7AICICIICBMU/","published_at":"2026-10-24T11:46:48+08:00","published_guessed":false,"fetched_at":"2026-10-27T01:49:48+08:00","language":"en","author":"","tags":["市场数据","品牌动态","供应链"],"priority":"P0","score":12.8,"matched":["a2","fonterra","synlait"],"id":"63b18b858d1aa958","title_zh":"新西兰股市收盘上涨，Synlait、A2、Fonterra股价下跌","summary_source":"llm","summary_kind":"brief","points":["Synlait、A2、Fonterra股价下跌","市场波动反映投资者预期","需关注乳业竞争格局和供应链成本变化"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Oct. 6 (BusinessDesk) - New Zealand shares gained, led by Meridian Energy and Port of Tauranga, as investors keep an eye on tomorrow's final count of the general election and the subsequent coalition talks, while dairy stocks Synlait Milk and A2 Milk Co gave up gains. The S&P/NZX50 Index rose 2.64 points, or 0.03 percent, to 7,977.34. Within the index, 25 stocks rose, 20 fell and five were unchanged. Turnover was $155.6 million. \"It's a quiet day leading into tomorrow's update on the special votes - that's probably related, people are waiting to see what happens over the weekend and in negotiations through to the 12th,\" said James Lindsay, senior portfolio manager at Nikko Asset Management. \"If there is a marked move to one side or the other, you would see currency movements first.\" Meridian Energy led the index, up 2.5 percent to $2.89, while Port of Tauranga gained 2.1 percent to $4.39 and Sanford rose 1.9 percent to $8. Synlait Milk was the worst performer, down 2.6 percent to $6.72, and A2 Milk Co dropped 1.4 percent to $7.16, both falling from record highs. The two stocks have gained since last Thursday on confirmation that their brands and recipes have gained registration in China, removing an obstacle in a market with soaring sales, before both giving up gains yesterday. They have had strong years so far, rising 122 percent and 241 percent respectively. \"After a particularly strong period for Synlait and A2, they've obviously given back a little bit of their gains, and A2 continues to trade on pretty solid volumes,\" Linsday said. \"The strength earlier in the week was partly to do with one of the Aussie brokers upgrading A2, a Goldmans analyst upgraded it to buy and put a $7.90 price target on it. There has obviously been very good demand for Synlait itself, and it's not too long since they received Chinese accreditation which helps Synlait too, but that certainly assisted this week.\" Fonterra Shareholders Fund units declined 2.2 percent, or 14 cents, to $6.10 after shedding rights to a 20 cents per share final dividend. Polish Dairy, the fifth largest producer of milk in the European Union, will join Fonterra Cooperative Group's Global Dairy Trade platform from Nov. 21, initially offering skim milk powder, whole milk powder, butter and lactose on the platform.","image":"https://www.businessdesk.co.nz/resizer/v2/SFZN2GQIJVPLXLAHPXUO7RX2FU.png?auth=a242d87b0b0927b864a88cd7ddb2481530968429b9104dfac7882be5303299da&width=1200&height=675&quality=70&smart=true"},{"title":"庖根闻笛丨在光环与争议中崛起的君乐宝","summary":"君乐宝品牌在光环与争议中崛起，其发展历程对母婴行业从业者具有重要启示。品牌通过不断创新和提升产品质量，赢得了市场认可，但也面临行业竞争和消费者信任的挑战。君乐宝的案例表明，企业需在追求发展的同时，注重品牌建设和风险管理，以应对市场变化和消费者需求。","source_id":"muyingqianyan","source_name":"母婴前沿","source_url":"https://www.muyingqianyan.com/feed","original_url":"https://www.muyingqianyan.com/123360.html","published_at":"2026-10-24T10:32:32+08:00","published_guessed":false,"fetched_at":"2026-10-25T12:05:19+08:00","language":"zh","author":"前沿, 母婴","tags":["品牌动态","质量安全","市场数据"],"priority":"P0","score":4.8,"matched":["君乐宝"],"id":"563de4b245c4dded","summary_source":"llm","summary_kind":"brief","title_zh":"庖根闻笛丨在光环与争议中崛起的君乐宝","translated":true,"image":"https://www.muyingqianyan.com/wp-content/uploads/2021/07/e6570c2e9d90b442ec5abe68c80669c.png","points":["品牌在光环与争议中崛起","面临行业竞争和消费者信任挑战","需注重品牌建设和风险管理"],"points_source":"llm"},{"title":"Fonterra-Backed Vivici Puts ‘Pink Gold’ Into Everyday Wellness - PlanetFood News","summary":"荷斯坦乳业支持的Vivici公司致力于将富含蛋白质的乳制品推广至日常保健领域。这一举措旨在提升乳制品在健康产品中的价值，对乳制品行业从业者而言，意味着乳制品的多元化应用和市场拓展。乳制品行业一直依赖传统销售模式，此类创新有助于开拓新的消费场景，增强产品竞争力。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.planetfood.news/post/fonterra-backed-vivici-puts-pink-gold-into-everyday-wellness","published_at":"2026-10-24T07:04:18+08:00","published_guessed":false,"fetched_at":"2026-10-26T22:39:54+08:00","language":"en","author":"","tags":["行业动态"],"priority":"P0","score":4.8,"matched":["fonterra"],"id":"5fff8e1e698568ce","title_zh":"荷斯坦乳业支持Vivici将“粉色黄金”融入日常保健","summary_source":"llm","summary_kind":"brief","points":["Vivici公司推广乳制品保健价值","乳制品行业多元化应用拓展","增强产品市场竞争力","开拓新的消费场景"],"points_source":"llm","translated":true,"link_resolved":true,"body":"A tropical drink for gut health, an iron-support capsule and a protein-packed soda. Fonterra-backed Vivici is offering a taste of where everyday nutrition could be heading, with products designed to fit around people’s lives. The Dutch company will showcase its latest concepts at SupplySide Global in Las Vegas this month. They’re ideas for brands to develop, rather than products heading straight onto supermarket shelves. At the heart of its wellness pitch is lactoferrin, an iron-binding protein sometimes called “pink gold”. Vivici makes it through precision fermentation and is exploring its potential in supporting iron balance and gut health. One concept combines lactoferrin with iron and vitamin C; another puts it into a coconut-and-golden-pineapple drink mix with prebiotic fibre and probiotics. For consumers, the appeal could be a simple daily addition with a clear purpose, provided the finished products deliver on their promise. For those looking to lift their protein intake, Vivici is also showing an Italian lemon soda and a small mangosteen lassi shot delivering 25g of protein in just 100ml. These use its separate BLG whey protein ingredient, rather than lactoferrin. The attraction is easy to see: more choice beyond the familiar thick shake, especially for people who want their protein in something refreshing or small enough to drink in a few mouthfuls. For New Zealand, Fonterra’s involvement makes this particularly interesting. Through its stake in Vivici, the dairy co-operative has a foothold in producing valuable dairy proteins without extracting them from cows milk. That could open additional opportunities in health, wellness and active nutrition, extending the ways its protein expertise reaches consumers. Lactoferrin supplements already exist, so this is no clear-cut world first. The more useful question is whether fermentation can make these ingredients accessible to more people. Taste, price and credible benefits will decide that. A good concept gets attention at a trade show. A product people enjoy, can afford and find useful earns a place in the daily routine.","image":"https://static.wixstatic.com/media/09a3a6_0fca86e6d6fc4c81baa3f0637e3d37fa~mv2.png/v1/fill/w_1000,h_1000,al_c,q_90,usm_0.66_1.00_0.01/09a3a6_0fca86e6d6fc4c81baa3f0637e3d37fa~mv2.png"},{"title":"今年第四季度山东省生鲜乳交易参考价定为每公斤3.10—3.45元 - 凤凰网山东","summary":"山东省畜牧兽医局发布通知，2026年第四季度全省生鲜乳交易参考价设定为每公斤3.10至3.45元，执行期10月1日至12月31日。要求生鲜乳质量符合国家标准，按质论价。此举旨在保障养殖企业与加工企业的稳定经营，对乳业从业者而言，价格稳定有助于成本控制与经营规划。10月23日，新黄河记者从山东省畜牧兽医局了解到，该局发布山东省生鲜乳价格协调委员会公告（〔2026〕4号）。","source_id":"gnews_cn_supply","source_name":"Google News·奶源与原料价格（中文）","source_url":"https://news.google.com/rss/search?q=(%E5%8E%9F%E5%A5%B6%20OR%20%E7%94%9F%E9%B2%9C%E4%B9%B3%20OR%20%E4%B9%B3%E6%B8%85%20OR%20%E4%B9%B3%E9%93%81%E8%9B%8B%E7%99%BD%20OR%20%E5%A4%A7%E5%8C%85%E7%B2%89%20OR%20%E5%8E%9F%E6%96%99%E5%A5%B6%E7%B2%89)%20(%E4%BB%B7%E6%A0%BC%20OR%20%E6%8B%8D%E5%8D%96%20OR%20%E4%BE%9B%E5%BA%94%20OR%20%E4%BA%A7%E8%83%BD)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://sd.ifeng.com/c/8xSc0hKiMh6","published_at":"2026-10-24T06:58:22+08:00","published_guessed":false,"fetched_at":"2026-10-26T11:16:41+08:00","language":"zh","author":"","tags":["市场数据","供应链"],"priority":"P0","score":4.8,"matched":["生鲜乳"],"id":"690d41b22072ec2f","summary_source":"llm","title_zh":"山东省2026年第四季度生鲜乳交易参考价定为每公斤3.10—3.45元","translated":true,"link_resolved":true,"body":"10月23日，新黄河记者从山东省畜牧兽医局了解到，该局发布山东省生鲜乳价格协调委员会公告（〔2026〕4号）。鉴于当前奶业生产形势，为确保养殖企业生鲜乳交售不断档，加工企业维持生产不停产，经山东省畜牧协会奶业分会测算，并征求山东省生鲜乳价格协调委员会全体委员意见，2026年第四季度全省生鲜乳交易参考价设定为每公斤3.10—3.45元的区间价格。乳企做到应收尽收、如期续签收购合同。执行期限2026年10月1日至12月31日。 公告表示，生鲜乳质量应符合《食品安全国家标准 生乳》（GB 19301-2010）要求（蛋白质含量2.8%、脂肪含量3.1%、菌落总数200万以下）。生鲜乳生产、收购双方应以交易参考价为基础，按照质价相符、按质论价、优质优价原则，协商确定生鲜乳实际收购价格。","image":"https://x0.ifengimg.com/ucms/2026_43/B9C3F1B5EC85B3C6634454E363BE2B76464DC740_size32_w840_h479.jpg","points":["参考价3.10-3.45元/公斤","执行期10月1日至12月31日","质量符合国家标准"],"points_source":"llm"},{"title":"Nestlé turnaround taking shape a year after new CEO","summary":"CEO 菲利普·纳夫拉蒂尔表示，产品创新与业务剥离推动北美等关键市场改善，但他对整体业绩“仍不满意”。","source_id":"fooddive","source_name":"Food Dive","source_url":"https://www.fooddive.com/feeds/news/","original_url":"https://www.fooddive.com/news/Nestle-turnaround-ceo-frozen-coffee-snacking/833742","published_at":"2026-10-24T02:58:00+08:00","published_guessed":false,"fetched_at":"2026-10-25T12:05:14+08:00","language":"en","author":"Christopher Doering","tags":["品牌动态"],"priority":"P1","score":4.8,"matched":["nestlé"],"id":"6efa5c4631d2176e","title_zh":"新 CEO 上任一年，雀巢重组初见成效","translated":true,"body":"Philipp Navratil said innovations and category divestitures have helped lead to improvements in key markets like North America, but he’s still “not satisfied” with the company’s performance. Published Oct. 23, 2026 Christopher Doering Senior Reporter Share Copy link Email LinkedIn X/Twitter Facebook Print License Add us on Google Copy link Email LinkedIn X/Twitter Facebook Print Listen to the article 4 min This audio is auto-generated. Please let us know if you have feedback . Nestlé is making significant progress to turn around declining sales, the food maker’s CEO told analysts on Thursday, as the company sees a rebound in snacks and frozen offerings in its key U.S. market. Philipp Navratil, who took over Nestlé in September 2025 , inherited a company facing declines in consumer spending, plus uncertainty from tariffs and volatile commodity costs. The world's largest food company also saw some of its key segments underperform compared to the rest of the industry. Navratil has spent much of his tenure at Nestlé boosting innovation and shedding slower-growth assets including its premium waters unit, the remainder of its ice cream business and some vitamins, minerals and supplement brands. He also announced plans soon after he took over to cut 16,000 jobs, or about 6% of Nestlé’s global workforce, over a two-year period. So far, the plan is gaining traction. Nestlé posted third-quarter sales of $27.69 billion (22.756 billion Swiss francs,) with organic sales jumping 4%. Real internal growth, which measures volume, rose 1.8% in North America during the third quarter, compared to being down 0.6% in the prior three months. “We are starting to see improvement in the way the organization is changing and in our financial results. This gives me confidence that we are on the right path,” Navratil told analysts . “I am pleased with our progress, but I'm not satisfied.","image":"https://imgproxy.divecdn.com/Y7KueCCmpmeJldv01vYQ0r_kDGYJpCb0hpbTXlWo-kQ/g:ce/rs:fit:770:435/Z3M6Ly9kaXZlc2l0ZS1zdG9yYWdlL2RpdmVpbWFnZS9JTUdfMDk4MC1mb3Rvci0yMDI1MDQyNTEzNDkxMS5qcGc=.webp"},{"title":"母婴经营凭经验总踩坑？你缺的是颗粒度足够细的数据","summary":"母婴行业从业者常因依赖全国大盘数据做决策导致经营失误，精细化数据能提升决策准确性。对从业者而言，掌握更细分的市场数据有助于精准定位客户需求，优化产品布局与营销策略，增强市场竞争力。这一观点强调了数据在母婴行业经营中的重要性，精细化数据是提升经营效率的关键。从业者应重视数据分析，利用数据指导决策，以实现更精准的市场定位和更有效的业务运营。","source_id":"cbiline","source_name":"中童传媒","source_url":"https://www.cbiline.com/news/","original_url":"https://www.cbiline.com/detail/15007.html","published_at":"2026-10-24T00:00:00+08:00","published_guessed":false,"fetched_at":"2026-10-25T12:05:19+08:00","language":"zh","author":"","tags":["市场数据"],"priority":"P0","score":4.8,"matched":["母婴"],"id":"63e3850c5df98016","summary_source":"llm","title_zh":"母婴经营凭经验总踩坑？你缺的是颗粒度足够细的数据","translated":true,"points":["依赖全国大盘数据常导致经营失误","精细化数据能提升决策准确性","有助于精准定位客户需求","优化产品布局与营销策略"],"points_source":"llm","summary_kind":"brief"},{"title":"今年第四季度山东省生鲜乳交易参考价定为每公斤3.10—3.45元 - 搜狐网","summary":"今年第四季度山东省生鲜乳交易参考价定为每公斤3.10至3.45元。这一价格变动反映了当前生鲜乳市场的供需关系和成本变化，对行业从业者意味着需密切关注原料价格波动，合理调整生产成本和产品定价，以保持市场竞争力。同时，这也提醒从业者需关注原料供应链的稳定性和可持续性，以确保产品质量和供应安全。","source_id":"gnews_cn_supply","source_name":"Google News·奶源与原料价格（中文）","source_url":"https://news.google.com/rss/search?q=(%E5%8E%9F%E5%A5%B6%20OR%20%E7%94%9F%E9%B2%9C%E4%B9%B3%20OR%20%E4%B9%B3%E6%B8%85%20OR%20%E4%B9%B3%E9%93%81%E8%9B%8B%E7%99%BD%20OR%20%E5%A4%A7%E5%8C%85%E7%B2%89%20OR%20%E5%8E%9F%E6%96%99%E5%A5%B6%E7%B2%89)%20(%E4%BB%B7%E6%A0%BC%20OR%20%E6%8B%8D%E5%8D%96%20OR%20%E4%BE%9B%E5%BA%94%20OR%20%E4%BA%A7%E8%83%BD)&hl=zh-CN&gl=CN&ceid=CN:zh-Hans","original_url":"https://www.sohu.com/a/1091892638_121347613","published_at":"2026-10-23T23:14:30+08:00","published_guessed":false,"fetched_at":"2026-10-26T13:54:09+08:00","language":"zh","author":"","tags":["供应链","市场数据"],"priority":"P0","score":4.8,"matched":["生鲜乳"],"id":"a14e7ee832a64254","title_zh":"今年第四季度山东省生鲜乳交易参考价定为每公斤3.10—3.45元","summary_source":"llm","summary_kind":"brief","points":["今年第四季度山东省生鲜乳交易参考价定为每公斤3.10—3.45元","反映了当前生鲜乳市场的供需关系和成本变化","从业者需密切关注原料价格波动","关注原料供应链的稳定性和可持续性"],"points_source":"llm","translated":true,"link_resolved":true,"body":"10月23日，新黄河记者从山东省畜牧兽医局了解到，该局发布山东省生鲜乳价格协调委员会公告（〔2026〕4号）。鉴于当前奶业生产形势，为确保养殖企业生鲜乳交售不断档，加工企业维持生产不停产，经山东省畜牧协会奶业分会测算，并征求山东省生鲜乳价格协调委员会全体委员意见，2026年第四季度全省生鲜乳交易参考价设定为每公斤3.10—3.45元的区间价格。乳企做到应收尽收、如期续签收购合同。执行期限2026年10月1日至12月31日。","image":"https://q1.itc.cn/q_70/images03/20261023/2aa20ea4e306402b88982442ddd8256b.jpeg"},{"title":"Study: Maternal gut bacteria may help predict infant eczema","summary":"最新研究显示，母亲的肠道菌群可能是婴儿肠道菌群的主要来源，而非阴道或母乳菌群。这一发现可能影响对母婴健康的研究方向。对母婴行业从业者而言，需关注肠道菌群对婴幼儿健康的影响，并可能推动相关产品研发。这一发现为理解婴幼儿健康提供了新的视角，也为母婴行业提供了新的产品研发方向。从业者需关注肠道菌群与婴幼儿健康的关系，开发相关功能性产品，满足消费者对婴幼儿健康的需求。","source_id":"nutraingredients","source_name":"NutraIngredients","source_url":"https://www.nutraingredients.com/arc/outboundfeeds/rss/","original_url":"https://www.nutraingredients.com/Article/2026/10/23/study-maternal-gut-bacteria-may-help-predict-infant-eczema","published_at":"2026-10-23T23:07:41+08:00","published_guessed":false,"fetched_at":"2026-10-25T12:05:13+08:00","language":"en","author":"Cassandra Stern","tags":["市场数据","品牌动态","跨境电商"],"priority":"P1","score":4.8,"matched":["infant"],"id":"cdca64f36ec57b16","title_zh":"研究：母亲肠道菌群或可预测婴儿湿疹","translated":true,"body":"A mother’s gut bacteria could offer clues about her baby’s risk of developing eczema, according to recent research published in Nature that followed more than 700 families from pregnancy through the child’s first year. The study also found that babies get much of their early gut bacteria from their mothers’ intestines, not primarily from breast milk or the vaginal microbiome. Researchers analyzed 4,526 stool samples from 714 mother–infant pairs and compared bacterial strains to identify which were shared between mothers and their children. At both two and four weeks, infants shared a median of 65% of their gut bacterial strains with their mothers. By their first birthday, that figure had fallen to 25%.","summary_source":"llm","image":"https://www.nutraingredients.com/resizer/v2/PNDWPWR6SJDGPD7HG5FKEQANTA.jpg?auth=4dcff4b92772be66d92f77b8d6192f9cda3dba83b0d544632a97fab967836c7c&width=1200&height=630&smart=true","points":["母亲肠道菌群是婴儿主要来源","影响母婴健康研究方向","推动相关产品研发","关注肠道菌群影响"],"points_source":"llm","summary_kind":"brief"},{"title":"Danone joins Nestlé and Coca-Cola in labelling changes","summary":"达能同意更改其塑料瓶标签，使可回收性声明更清晰。此前，雀巢和可口可乐已达成 2025 年和 2026 年的承诺。此举旨在减少误导消费者，符合欧盟不公平商业实践规则。对从业者而言，这意味着需关注欧盟相关法规，及时调整产品标签。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/23/danone-joins-nestle-and-coca-cola-in-labelling-changes","published_at":"2026-10-23T21:17:01+08:00","published_guessed":false,"fetched_at":"2026-10-25T12:05:13+08:00","language":"en","author":"Lisa Buckingham","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","score":9.6,"matched":["danone","nestlé"],"id":"211ef6e021b2447e","title_zh":"达能跟进雀巢、可口可乐调整标签表述","translated":true,"body":"Danone has agreed to change the labelling on its plastic bottles to make recyclability claims clearer, according to statements from the European Commission and the European Consumer Organisation (BEUC). Nestlé and Coca-Cola had already concluded their discussions and agreed to commitments in 2025 and early 2026. Now Danone has joined the drinks giants. According to the EU Commission, all three companies will now: National consumer protection authorities will monitor the implementation of these commitments and may proceed with enforcement measures if companies fail to comply with them, according to the EU Commission.","summary_source":"llm","image":"https://www.foodnavigator.com/resizer/v2/CWK4WXEZKBAP5LPLHESMF5A6SY.jpg?auth=290da5e856029b9679a6b3e91f0308e74c7b2a8aa214ff398f4ff3a9d3733217&width=1200&height=630&smart=true","points":["达能更改塑料瓶标签可回收性声明","雀巢和可口可乐已承诺标签更改","符合欧盟不公平商业实践规则","从业者需关注欧盟法规调整"],"points_source":"llm"},{"title":"Danone joins Nestlé and Coca-Cola in labelling changes","summary":"达能根据欧盟委员会打击潜在漂绿行动的举措，修订了塑料瓶回收声明。这一变化反映了乳制品行业对可持续发展和环保责任的重视，对跨境母婴行业的从业者意味着需要关注并调整产品包装和营销策略，以符合国际环保标准，避免市场风险。这类事件通常意味着行业在追求更高品质和更细分的市场满足，从业者需紧跟技术发展和消费者需求变化，以保持竞争力。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.foodnavigator.com/Article/2026/10/23/danone-joins-nestle-and-coca-cola-in-labelling-changes","published_at":"2026-10-23T21:17:01+08:00","published_guessed":false,"fetched_at":"2026-10-26T23:38:46+08:00","language":"en","author":"Lisa Buckingham","tags":["政策法规","质量安全","跨境电商"],"priority":"P0","image":"https://www.dairyreporter.com/resizer/v2/CWK4WXEZKBAP5LPLHESMF5A6SY.jpg?auth=290da5e856029b9679a6b3e91f0308e74c7b2a8aa214ff398f4ff3a9d3733217&smart=true&width=2120&height=1414","score":9.6,"matched":["danone","nestlé"],"id":"a29d59b40cf508f3","title_zh":"达能跟随雀巢和可口可乐进行标签变更","summary_source":"llm","summary_kind":"brief","points":["达能修订塑料瓶回收声明","欧盟打击潜在漂绿行动","乳制品行业重视可持续发展","跨境从业者需调整策略"],"points_source":"llm","translated":true},{"title":"Danone partners in energy project to turn yogurt waste into renewable fuel","summary":"达能与能源项目合作，将美国最大酸奶制造设施的废料转化为可再生能源。该项目由 PurposeEnergy 承建，预计年产生约 50,000 MMBtu 的生物燃气。这一举措体现了达能的可持续发展战略，对从业者而言，关注环保技术有助于提升企业社会责任形象，符合市场趋势。","source_id":"dairyreporter","source_name":"DairyReporter","source_url":"https://www.dairyreporter.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/23/danone-partners-in-energy-project-to-turn-yogurt-waste-into-renewable-fuel","published_at":"2026-10-23T21:11:44+08:00","published_guessed":false,"fetched_at":"2026-10-25T12:05:13+08:00","language":"en","author":"","tags":["品牌动态","供应链"],"priority":"P0","score":4.8,"matched":["danone"],"id":"fabd5410ab56f6c9","title_zh":"达能参与能源项目，把酸奶废料转化为可再生燃料","translated":true,"body":"PurposeEnergy, which designs, builds, owns, and operates industrial anaerobic digestion infrastructure, has commissioned a $40 million industrial food waste and wastewater pre-treatment facility in Minster, Ohio. This project marks Danone’s first project with the company, Designed to process up to 250,000 gallons per day, the facility, when fully operational, is expected produce about 50,000 MMBtu of renewable biogas per year. The site has an official opening planned for spring of 2027. The facility will convert wastewater and high-strength organic food waste piped directly from Danone USA’s largest US yogurt manufacturing facility, and from other regional food and beverage producers.","summary_source":"llm","image":"https://www.dairyreporter.com/resizer/v2/ITO6SQRNCNC7LO7ZRNWZ34RZPU.jpg?auth=c46c3089c9987d699d16edafc2b8ad72a534f43a8852b0e737ae7676dfc9124b&width=1200&height=630&smart=true","points":["废料转化为生物燃气"],"points_source":"llm"},{"title":"Danone partners in energy project to turn yogurt waste into renewable fuel","summary":"达能宣布其在美国最大酸奶生产设施的废料将被转化为可再生能源，此举旨在加强可持续发展。该合作表明达能正积极应对环境挑战，通过创新技术减少废弃物对环境的影响。对行业从业者而言，这意味着企业需要更加重视环保措施，探索资源循环利用的新途径，以符合全球绿色发展的趋势。","source_id":"foodnavigator","source_name":"FoodNavigator","source_url":"https://www.foodnavigator.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/23/danone-partners-in-energy-project-to-turn-yogurt-waste-into-renewable-fuel","published_at":"2026-10-23T21:11:44+08:00","published_guessed":false,"fetched_at":"2026-10-26T17:56:38+08:00","language":"en","author":"","tags":["品牌动态","质量安全","供应链"],"priority":"P0","image":"https://www.foodnavigator.com/resizer/v2/ITO6SQRNCNC7LO7ZRNWZ34RZPU.jpg?auth=c46c3089c9987d699d16edafc2b8ad72a534f43a8852b0e737ae7676dfc9124b&smart=true&width=2120&height=1414","score":4.8,"matched":["danone"],"id":"564db712a76a23da","title_zh":"达能与美国能源项目合作，将酸奶废料转化为可再生能源","summary_source":"llm","summary_kind":"brief","points":["达能美国工厂废料将转化","可再生能源项目合作","企业可持续发展举措","环保技术创新应用"],"points_source":"llm","translated":true,"body":"23-Oct-2026 Last updated on 23-Oct-2026 at 14:11 GMT Danone is stepping up its sustainability efforts after it was revealed that waste from its largest US yogurt manufacturing facility will be converted into renewable energy. (Getty Images) PurposeEnergy, which designs, builds, owns, and operates industrial anaerobic digestion infrastructure, has commissioned a $40 million industrial food waste and wastewater pre-treatment facility in Minster, Ohio. This project marks Danone’s first project with the company, Designed to process up to 250,000 gallons per day, the facility, when fully operational, is expected produce about 50,000 MMBtu of renewable biogas per year. The site has an official opening planned for spring of 2027. The facility will convert wastewater and high-strength organic food waste piped directly from Danone USA’s largest US yogurt manufacturing facility, and from other regional food and beverage producers. This will be converted into renewable biogas, water treated to municipal discharge standards, and nutrient-rich soil amendments. The renewable biogas will be piped to a dedicated boiler at Danone’s Minster plant, where it will displace conventional natural gas. According to standard EPA/EIA combustion emission factors, the project is equivalent to displacing approximately 3,200 U.S. tons of CO2e per year."},{"title":"Danone partners in energy project to turn yogurt waste into renewable fuel","summary":"达能与美国环保企业合作，将旗下美国最大酸奶制造设施的废料转化为可再生能源。该项目投资4000万美元，设计日处理量25万加仑，预计年产生约5万百万英热单位生物燃气。此举标志着达能可持续发展努力的重要进展，对行业产生示范效应。对从业者而言，需关注企业可持续发展趋势，探索环保技术应用，提升品牌形象和市场竞争力。","source_id":"foodnavigator_asia","source_name":"FoodNavigator-Asia","source_url":"https://www.foodnavigator-asia.com/arc/outboundfeeds/rss/","original_url":"https://www.dairyreporter.com/Article/2026/10/23/danone-partners-in-energy-project-to-turn-yogurt-waste-into-renewable-fuel","published_at":"2026-10-23T21:11:44+08:00","published_guessed":false,"fetched_at":"2026-10-26T18:18:36+08:00","language":"en","author":"","tags":["品牌动态","质量安全"],"priority":"P1","image":"https://www.foodnavigator.com/resizer/v2/ITO6SQRNCNC7LO7ZRNWZ34RZPU.jpg?auth=c46c3089c9987d699d16edafc2b8ad72a534f43a8852b0e737ae7676dfc9124b&smart=true&width=2120&height=1414","score":4.8,"matched":["danone"],"id":"423877ec37976839","title_zh":"达能参与能源项目，将酸奶废料转化为可再生燃料","summary_source":"llm","summary_kind":"brief","points":["达能参与能源项目","将酸奶废料转化为可再生燃料","利用美国最大酸奶工厂废料","符合循环经济理念"],"points_source":"llm","translated":true,"body":"23-Oct-2026 Last updated on 23-Oct-2026 at 14:11 GMT Danone is stepping up its sustainability efforts after it was revealed that waste from its largest US yogurt manufacturing facility will be converted into renewable energy. (Getty Images) PurposeEnergy, which designs, builds, owns, and operates industrial anaerobic digestion infrastructure, has commissioned a $40 million industrial food waste and wastewater pre-treatment facility in Minster, Ohio. This project marks Danone’s first project with the company, Designed to process up to 250,000 gallons per day, the facility, when fully operational, is expected produce about 50,000 MMBtu of renewable biogas per year. The site has an official opening planned for spring of 2027. The facility will convert wastewater and high-strength organic food waste piped directly from Danone USA’s largest US yogurt manufacturing facility, and from other regional food and beverage producers. This will be converted into renewable biogas, water treated to municipal discharge standards, and nutrient-rich soil amendments. The renewable biogas will be piped to a dedicated boiler at Danone’s Minster plant, where it will displace conventional natural gas. According to standard EPA/EIA combustion emission factors, the project is equivalent to displacing approximately 3,200 U.S. tons of CO2e per year."},{"title":"Global milk supply is set to grow 2.2% in 2026 - Dairynews.today","summary":"据行业新闻网站Dairynews.today报道，预计2026年全球牛奶供应量将增长2.2%。这一增长趋势反映出全球乳制品市场的持续扩张，对乳制品供应链和跨境贸易的从业者而言，意味着更广阔的市场机会和供应链调整的必要性。乳制品行业作为全球重要的农产品之一，其供应量的增长将直接影响市场价格和行业竞争格局。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://dairynews.today/news/global_milk_supply_is_set_to_grow_2_2_in_2026_5906493.html","published_at":"2026-10-23T20:53:52+08:00","published_guessed":false,"fetched_at":"2026-10-26T22:39:54+08:00","language":"en","author":"","tags":["市场数据","供应链","跨境电商"],"priority":"P0","score":6.4,"matched":["milk supply"],"id":"24674e87c2c49654","title_zh":"2026年全球牛奶供应预计增长2.2%","summary_source":"llm","summary_kind":"brief","points":["全球牛奶供应量预计增长2.2%","乳制品市场持续扩张","供应链调整的必要性","影响市场价格和竞争格局"],"points_source":"llm","translated":true,"link_resolved":true,"body":"Milk collection has so far exceeded expectations in many major producing regions. The Ornua Global Dairy Market Report for October estimates that global supply increased by about 1.4% in August, although the pace is expected to weaken as drought in Europe and El Niño-related conditions affect production. The report puts the expected increase for 2027 at 1%. It says the eventual effect of El Niño is “currently unknown”, while higher oil prices, inflation and interest rates represent a “considerable” source of macroeconomic uncertainty. European dairy markets have remained relatively stable despite strong global availability. Milk output in the European Union rose by 1.1% in September, compared with 2.5% in August. Volumes were above expectations despite dry conditions, prompting the report to restore the bloc’s annual production estimate to its pre-drought level of 1.9%. Join the 2nd MENA Dairy Congress on January 24–25 in Al Ain, UAE — a key meeting point for dairy industry leaders, producers, investors, experts, and technology providers from across the MENA region and beyond. Discover new market opportunities, exchange expertise, build valuable business connections, and discuss the future of the dairy industry in one of the region’s most dynamic markets. Register here: https://menadc.dairynews.today In the United States, production increased by 1.7% in both July and August, and the annual forecast remains at 2.2%. Ornua identifies high beef prices and newly available cheese-processing capacity as the main factors supporting the expansion. New Zealand recorded a 2.4% rise in milk flows and a 3.4% increase in milk solids; at the current rate, growth could reach 4% or more. Favourable conditions also lifted production in major South American producers, including Argentina, Brazil and Uruguay. “Global flows are expected to continue expanding, although at a slower pace in the fourth quarter. The full impact of weather-related supply disruptions is unlikely to appear before the beginning of next year,” the report says. European butter production increased in July and August, while exports remained firm, supported by demand from the United States, China and Turkey. Drought concerns, historically low prices and seasonal activity supported the market in August and early September. British production slowed in recent months, although steady exports provided support."},{"title":"Fonterra has record quarterly exports, gets creative with shipping - BusinessDesk","summary":"荷斯坦乳业在最新季度实现了出口创纪录，同时积极创新运输方式。这一成绩反映出荷斯坦乳业在国际市场上的强劲表现和供应链管理的优化。对乳制品行业从业者而言，这意味着高效供应链和出口策略的重要性。随着全球贸易环境的不断变化，乳制品企业需要不断优化运输和物流体系，以适应市场需求和提升竞争力。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.businessdesk.co.nz/news/fonterra-has-record-quarterly-exports-gets-creative-with-shipping/RJXREBZBQVLHJEHRIWMU4BBNIA/","published_at":"2026-10-23T19:15:32+08:00","published_guessed":false,"fetched_at":"2026-10-26T22:39:54+08:00","language":"en","author":"","tags":["供应链"],"priority":"P0","score":4.8,"matched":["fonterra"],"id":"5ca6ab3783d66d3a","title_zh":"荷斯坦乳业季度出口创纪录，创新运输方式","summary_source":"llm","summary_kind":"brief","points":["荷斯坦乳业季度出口创纪录","出口策略的重要性"],"points_source":"llm","translated":true,"link_resolved":true,"body":"By Peter Kerr Aug 20 (BusinessDesk) - Fonterra Cooperative Group, the world’s biggest exporter of dairy products, achieved record export in the final three months of its season of 620,000 tonnes. Its 2012 May, June and July shipments were 36% more than the same period last year, reinforcing the 2011/2012 record milk production by its 10,500 dairy farmer members. Total milk production was up 10% on 2010/2011. “We traditionally ship just over 450,000 tonnes at this time of year, but we’ve had a lot more product to move, and this has meant some creative planning across the wider supply chain to manage and store the additional volumes,” said Fonterra NZ Milk Products managing director, Gary Romano. “For the first time since Fonterra was formed, we chartered our own break-bulk vessel to send product to the Middle East.” Romano said that though dairy product demand usually lifts ahead of the Islamic month of Ramadan, the demand spike was more than expected. “There was not enough available container capacity at that time of year,” he said. “This meant Fonterra had to charter its own vessel to take 7,500 tonnes of products to ports in Dubai and Saudi.” Romano said the new dairy season has now begun. (BusinessDesk) The combined business will employ about 100 people across New Zealand and the Pacific. Regular inviters had a 13% promotion rate, against 6.7% across the sample. The couple had no prenup, despite Two Sigma managing about $350m by their wedding. Sponsored Labour, National face off on Super Sponsored Willis, Edmonds clash over debt, tax cuts","image":"https://www.businessdesk.co.nz/resizer/v2/SFZN2GQIJVPLXLAHPXUO7RX2FU.png?auth=a242d87b0b0927b864a88cd7ddb2481530968429b9104dfac7882be5303299da&width=1200&height=675&quality=70&smart=true"},{"title":"Change in Directors appointed by Bright Dairy - BusinessDesk","summary":"刘瑞兵（Ryan）因个人原因辞去光明乳业控股有限公司（光明乳业）首席财务官职务，并已停止担任光明乳业任命的Synlait Milk Limited（Synlait）董事，鉴于其已停止在光明乳业的雇佣关系。光明乳业将适时提供Ryan继任者的更新。Ryan的辞职立即生效。光明乳业在Synlait的持股比例为39.0%。对于从业者而言，这意味着需关注乳业高层变动对行业格局的影响。","source_id":"gnews_en_nz_dairy","source_name":"Google News·新西兰奶源（英文）","source_url":"https://news.google.com/rss/search?q=%28Fonterra%20OR%20DairyNZ%20OR%20Synlait%20OR%20%22farmgate%20milk%20price%22%20OR%20%22milk%20supply%22%29%20%28%22New%20Zealand%22%20OR%20NZ%20OR%20dairy%29&hl=en-NZ&gl=NZ&ceid=NZ:en","original_url":"https://www.businessdesk.co.nz/nzx-announcements/synlait/425914/","published_at":"2026-10-23T19:00:03+08:00","published_guessed":false,"fetched_at":"2026-10-26T23:15:45+08:00","language":"en","author":"","tags":["品牌动态","政策法规","供应链"],"priority":"P0","score":4.8,"matched":["dairy"],"id":"8bea1cfbf169b016","title_zh":"贝因美任命新董事","summary_source":"llm","summary_kind":"brief","translated":true,"link_resolved":true,"body":"Liu Ruibing (Ryan) has resigned as CFO of Bright Dairy Holding Limited (Bright Dairy) for personal reasons and he has subsequently stood down as a Bright Dairy appointed Director of Synlait Milk Limited (Synlait) given his employment has ceased with Bright Dairy. Synlait and Bright Dairy thank Ryan for his contribution to Synlait. Ryan’s resignation is effective immediately. Bright Dairy will provide an update on Ryan’s replacement in due course. The resignation does not impact Synlait’s daily operations. Bright Dairy has a 39.0% shareholding in Synlait. For more information contact: Hannah Lynch Head of Strategy & Corporate Affairs P: +64 21 252 8990 E: hannah.lynch@synlait.com The S&P/NZX 50 fell 0.09% to 13,733.93, leaving it flat for the week. Fuel-price-linked airline cuts reduced passenger numbers year on year. ikeGPS's platform subscription revenue rose 22% to about $11m. Plus, who's on board, who's on the block, what should be off the agenda, and more. The Australian activist expects to raise the issue at about 30 AGMs this year. Group same-store sales rose 6.6% over 16 weeks on a constant-currency basis.","points":["贝因美CFO辞职并卸任Synlait董事","贝因美持有Synlait39%股份","变动不影响Synlait日常运营"],"points_source":"llm"}]};
